INSERT INTO `master_tasks` (`id`, `original_task_ids`, `originating_show_id`, `adapting_show_ids`, `adaptations`, `title`, `description`, `cover_image`, `cover_image_thumb`) VALUES
(1, '|3|', 1, '|2|3|5|6|7|9|11|12|13|', 9, 'Paint a mode of transportation while using that mode of transportation', 'The contestants have to paint the given mode of transportation (usually a horse, but has also been a rowboat) while also using that mode of transportation.|If the contestants are unwilling to ride a real horse, the show producers usually have an alternative prepared to simulate the experience.|When horses are the subject of the task, the contestants ride the horse (or equivalent) with an arm-mounted easel and limited range of paints.|In the case of the rowboat, the canvas and painting supplies are just provided within the boat.|They are awarded points based on the quality of their paintings, though are sometimes marked down if they choose not to use the mode of transportation originally provided.', '00003_horse_painting.jpg', '00003_horse_painting.jpg'),
(2, '|4|', 1, '|2|3|4|9|11|13|', 6, 'Empty the bathtub', 'The contestants have to empty the water from a bathtub as quickly as possible, without removing the plug, or tipping or damaging the bath.', '00004_empty_bathtub.jpg', '00004_empty_bathtub.jpg'),
(3, '|5|', 1, '|2|3|5|7|11|13|16|', 7, 'Pop up a tent and pop on a onesie', 'In this live studio task, the contestants compete to be the quickest to erect a small tent, get inside, and emerge dressed in a novelty onesie.', '00005_pop_on_a_onesie.jpg', '00005_pop_on_a_onesie.jpg'),
(4, '|10|', 1, '|2|3|4|6|7|9|11|12|13|', 9, 'Do something that will look impressive in reverse', 'The contestants are asked to complete an action or perform a scene which will look impressive when played in reverse.', '00010_impressive_in_reverse.jpg', '00010_impressive_in_reverse.jpg'),
(6, '|13|', 1, '|2|3|6|9|11|13|', 6, 'Throw a teabag into a mug', 'The contestants have to throw a teabag into a mug from the furthest distance.', '00013_throw_a_teabag_into_a_mug.jpg', '00013_throw_a_teabag_into_a_mug.jpg'),
(7, '|14|', 1, '|2|4|5|9|13|', 5, 'Draw an image using a GPS device', 'The contestants have to make a line drawing by walking around while wearing a GPS tracking device.', '00014_draw_an_image_using_gps.jpg', '00014_draw_an_image_using_gps.jpg'),
(8, '|15|', 1, '|1|3|4|6|9|12|13|', 12, 'A gift for the Taskmaster', 'In this task the contestants are usually given a fixed amount of money and have an extended period between receipt of the task brief and the filming of the studio segments to purchase a suitable gift for the Taskmaster.|However, in one instance, the contestants are given a budget for supplies, which they must then use to make a gift for the Taskmaster, at the Taskmaster house.|The gifts are presented to the Taskmaster in the studio, and points are awarded based on which ones they like the most.', '00015_buy_a_gift_for_the_taskmaster.jpg', '00015_buy_a_gift_for_the_taskmaster.jpg'),
(9, '|16|', 1, '|4|6|13|', 4, 'Get an egg as high as possible', 'The contestants are provided with a limited set of materials, and have to get an egg as high as possible without breaking it in the process.', '00016_get_an_egg_as_high_as_possible.jpg', '00016_get_an_egg_as_high_as_possible.jpg'),
(10, '|17|', 1, '|2|3|5|6|11|12|', 15, 'Stand up after exactly a given number of seconds', 'In this live studio task, the contestants have to judge when a given number of seconds have passed, and then stand up. The person who stands up closest to the given number of seconds wins.|Typically, the hosts of the show will have some fun with the contestants by trying to distract them and interfere with any internal counting they may be doing to keep track of time.', '00017_stand_up_after_100_seconds.jpg', '00017_stand_up_after_100_seconds.jpg'),
(11, '|20|', 1, '|2|3|6|7|9|11|13|', 7, 'Make a block of ice disappear', 'The contestants have to make a large block of ice ‘disappear’ as quickly as possible.', '00020_make_this_ice_block_disappear.jpg', '00020_make_this_ice_block_disappear.jpg'),
(12, '|23|', 1, '|2|3|4|5|6|8|9|11|16|', 12, 'Score a given number of points', 'In this team task the contestants are presented with an array of objects in a location, and are told they have to score a given number of points as quickly as possible. They have to figure out for themselves how the points are actually earned.', '00023_score_11_points.jpg', '00023_score_11_points.jpg'),
(13, '|24|', 1, '|2|4|5|6|9|11|12|13|', 8, 'Collect as many tears as possible', 'In this task, the contestants are instructed to collect as many tears as possible in a limited time frame. Most contestants attempt to make themselves cry by cutting onions or applying other irritants to their face and eyes.', '00024_fill_an_egg_cup_with_tears.jpg', '00024_fill_an_egg_cup_with_tears.jpg'),
(14, '|26|', 1, '|3|4|5|9|13|', 6, 'Memorise the individuals’ identities', 'In this live task the contestants have to memorise and recall the names of a group of individuals, such as the members of a sports team, a group of bearded men, or some randomly selected members of the audience.', '00026_memorise_an_aussie_football_team.jpg', '00026_memorise_an_aussie_football_team.jpg'),
(15, '|28|', 1, '|2|3|4|9|11|', 5, 'Move a bulky item as far away as possible', 'In this task the contestants have to move a bulky item as far away from the Taskmaster house as possible within a given timeframe.|The distance travelled is measured in a straight line from the start position to the end position, so keeping track of the direction being travelled is just as important as keeping moving.', '00028_move_the_boulder_as_far_as_possible.jpg', '00028_move_the_boulder_as_far_as_possible.jpg'),
(16, '|30|', 1, '|2|3|11|13|', 4, 'Make a bed while holding hands', 'In this team task, the contestants must make a bed while holding hands with their team-mate(s).', '00030_make_a_bed_while_holding_hands.jpg', '00030_make_a_bed_while_holding_hands.jpg'),
(17, '|32|', 1, '|2|3|4|5|6|7|11|12|13|', 9, 'Inflate the largest balloon while blindfolded', 'In this live task, the blindfolded contestants have to attempt to inflate the largest balloon.|They typically only have one balloon, so have to try to avoid bursting it by over-inflating.', '00032_blow_up_the_biggest_balloon.jpg', '00032_blow_up_the_biggest_balloon.jpg'),
(18, '|34|', 1, '|2|3|4|6|', 4, 'Play mini golf with eggs', 'In this task, the contestants have to complete a round of mini golf using eggs instead of a ball. Their score is calculated based on the time taken, number of strokes taken, and number of eggs used.', '00034_play_mini_golf_with_eggs.jpg', '00034_play_mini_golf_with_eggs.jpg'),
(19, '|35|', 1, '|2|3|4|', 3, 'Stage a realistic home movie blooper', 'In this task, the contestants have to stage a realistic-looking home movie blooper, as might be seen on a show such as You’ve Been Framed (in the UK), or America’s Funniest Home Videos (in the US).', '00035_stage_a_realistic_home_movie_blooper.jpg', '00035_stage_a_realistic_home_movie_blooper.jpg'),
(21, '|37|', 1, '|2|3|5|6|7|12|13|', 7, 'Separate sweets of a specific colour while wearing gloves', 'In this live task, the contestants are asked to separate out a specific colour of mixed-colour sweets into a bowl, while wearing boxing gloves or mittens to impair their dexterity.', '00037_separate_the_blue_sweets.jpg', '00037_separate_the_blue_sweets.jpg'),
(23, '|284|', 1, '|3|4|11|', 3, 'Alter your appearance during a lift journey', 'In this task, the contestants are instructed to dramatically alter their appearance during a short journey in a lift, using a selection of supplies provided.', '00284_alter_your_appearance_during_a_lift_journey.jpg', '00284_alter_your_appearance_during_a_lift_journey.jpg'),
(24, '|208|', 1, '|3|4|6|13|', 4, 'Make the tallest lemon tower', 'In this task the contestants are instructed to make the tallest possible tower out of lemons.|Sometimes a knife is provided and there are restrictions on how many times the knife may be wielded.|Sometimes a number of wooden cocktail sticks are hidden inside one of the lemons, which could help greatly in construction, if found.', '00208_make_the_tallest_lemon_tower.jpg', '00208_make_the_tallest_lemon_tower.jpg'),
(25, '|98|', 1, '|3|5|9|', 3, 'Make the most fruit juice', 'In this live task, the contestants have to produce as much juice as possible from a fruit of their choice, using a tool of their choice. Handicaps are applied to those contestants who choose the same fruit and/or tool.', '00098_make_the_most_fruit_juice.jpg', '00098_make_the_most_fruit_juice.jpg'),
(26, '|177|', 1, '|3|4|6|9|11|', 5, 'Balance the Taskmaster’s assistant on a see-saw', 'In this task the contestants are instructed to balance the Taskmaster’s assistant on a see-saw by adding objects with a combined equal weight to a box on the other end. The Taskmaster’s assistant does not get onto their end of the see-saw until the contestant has finished adding items.', '00177_balance_alex_on_a_see_saw.jpg', '00177_balance_alex_on_a_see_saw.jpg'),
(27, '|82|', 1, '|4|5|6|13|', 5, 'Anchor balloons to the ground using the supplied items', 'In this task (which is usually a live studio task, but has also appeared as a pre-recorded task), the contestants are instructed to anchor as many helium-filled balloons as possible to the ground using just the supplied items.', '00082_anchor_balloons_using_bread.jpg', '00082_anchor_balloons_using_bread.jpg'),
(28, '|389|', 1, '|4|6|', 2, 'Arrange the playdough / Separate the playdough while blindfolded', 'In this two-part live studio task, the contestants are first instructed to do something with the coloured playdough balls which encourages them to mix them up in some manner (e.g. \'make an arrangement\', or \'make a fine work of art\').|They are then blindfolded before the second part of the task, in which they are instructed to separate the playdough by colour.|They may be asked to do different things with the dough of different colours (e.g. flatten balls of one colour, throw balls of another colour into a bucket, and combine balls of the third colour into one), or may just be told to return the dough to the plate of the corresponding colour.', '00389_arrange_the_playdough_balls.jpg', '00389_arrange_the_playdough_balls.jpg'),
(29, '|197|', 1, '|3|6|', 2, 'Blow something substantial off a table', 'In this task the contestants are instructed to blow something ‘substantial’ off a table. The meaning of the word ‘substantial’ is very much open to their interpretation.', '00197_blow_something_substantial_off_the_table.jpg', '00197_blow_something_substantial_off_the_table.jpg'),
(30, '|64|', 1, '|2|5|6|7|13|', 5, 'Build a structure for the potato', 'In this task the contestants are instructed to build a structure to support a potato (e.g. a bridge or tower) on a scale model of a (usually pastoral) scene, using just the items on the table. The items on the table are typically very poor supplies for bridge-building, but there are more suitable supplies hidden on the underside of the table, with subtle clues to this fact hidden in the room.', '00064_build_a_bridge_for_the_potato.jpg', '00064_build_a_bridge_for_the_potato.jpg'),
(31, '|337|', 1, '|6|9|', 2, 'Build the best volcano', 'In this task the contestants are instructed to build a volcano using any supplies of their choice.', '00337_build_the_best_volcano.jpg', '00337_build_the_best_volcano.jpg'),
(32, '|910|', 3, '|1|4|6|13|', 4, 'Build the tallest cardboard box tower', 'In this task the contestants are instructed to build the tallest tower out of cardboard moving boxes.|Normally, the contestants’ time only begins once they have folded their first cardboard box.', '00910_build_a_cardboard_box_tower.jpg', '00910_build_a_cardboard_box_tower.jpg'),
(33, '|106|', 1, '|3|4|6|7|9|11|12|13|', 8, 'Camouflage yourself', 'In this task the contestants are instructed to camouflage themselves somewhere in or around the Taskmaster house. The Taskmaster is then shown a photo of the scene in which the contestant is camouflaged, and has to try to identify where they are hidden.', '00106_camouflage_yourself.jpg', '00106_camouflage_yourself.jpg'),
(34, '|190|', 1, '|3|6|9|11|', 4, 'Transport something as far as possible without touching the ground', 'In this task the contestants are instructed to carry something (usually a coconut, but a cactus has also been used) as far away from where they received the task brief as possible without touching the ground, and without stepping on the same thing twice.', '00190_carry_a_coconut_as_far_as_possible.jpg', '00190_carry_a_coconut_as_far_as_possible.jpg'),
(35, '|368|', 1, '|3|6|9|11|', 4, 'Complete the five-syllable words', 'In this live studio task the contestants are instructed to complete the five-syllable words started by the Taskmaster, as they utter each syllable in turn.', '00368_complete_the_five_syllable_words.jpg', '00368_complete_the_five_syllable_words.jpg'),
(36, '|57|', 1, '|2|3|4|5|6|9|11|', 7, 'Conceal a fruit on your person', 'In this task the contestants are instructed to conceal a fruit (usually a pineapple, but they may be offered a choice, in the live studio task version) on themselves.|In most versions, The Taskmaster’s assistant then performs a visual inspection of the contestant and makes guesses about where the pineapple may be hidden. The contestant for whom the assistant makes the most incorrect guesses wins the task.|However, as a live task, the Taskmaster may be the one guessing where the fruit is hidden.', '00057_conceal_a_pineapple_on_your_person.jpg', '00057_conceal_a_pineapple_on_your_person.jpg'),
(37, '|217|', 1, '|3|4|6|9|11|13|', 6, 'Conceal a small edible item in your mouth or your hand\r\n', 'In this live studio task the contestants take it in turns to conceal a small edible item (usually a grape) either in their mouth or their hand. They then have to answer a question from the Taskmaster, who has to guess where the item is concealed.', '00217_conceal_grapes_in_your_mouth_or_your_hand.jpg', '00217_conceal_grapes_in_your_mouth_or_your_hand.jpg'),
(38, '|21|', 1, '|2|3|4|12|13|', 7, 'Count the numerous edible items in a container', 'In this special, non-competition task, a single contestant is instructed to count the edible items in a container, e.g. the number of beans in a can of baked beans, the number of grains of rice in a bag of rice, etc.', '00021_count_the_bake_beans.jpg', '00021_count_the_bake_beans.jpg'),
(39, '|181|', 1, '|5|', 1, 'Make yourself monotone\r\n', 'In this live studio task the contestants wear a white boiler suit and are instructed to cover as much of the suit as possible in one colour using pigmented supplies such as paint and chalk powder.', '00181_make_yourself_monochrome.jpg', '00181_make_yourself_monochrome.jpg'),
(40, '|67|', 1, '|3|7|11|13|', 4, 'Reach a destination using as few steps as possible', 'In this task the contestants are instructed to reach a destination within a given time limit using the fewest steps possible.', '00067_reach_the_microwave_in_the_fewest_steps.jpg', '00067_reach_the_microwave_in_the_fewest_steps.jpg'),
(41, '|178|', 1, '|3|7|11|', 3, 'Record the most incredible PoV footage', 'In this task the contestants are instructed to record some incredible PoV footage using a camera strapped to their head.', '00178_record_the_most_incredible_pov_footage.jpg', '00178_record_the_most_incredible_pov_footage.jpg'),
(42, '|73|', 1, '|6|7|11|13|', 4, 'Release the Taskmaster’s assistant', 'In this task the contestants receive a vague instruction about their time starting, without being given an explicit objective. A clue to the actual objective of the task (to free the Taskmaster’s assistant from their handcuffs) is hidden in the room (usually in UV ink on the task brief itself). Additional clues are hidden around the Taskmaster’s house, leading them on a treasure hunt which ultimately informs them that the key to the handcuffs is hidden on the assistant themself (often right in their hand).', '00073_release_alex.jpg', '00073_release_alex.jpg'),
(43, '|158|', 1, '|6|7|9|11|13|', 5, 'Retrieve the table tennis ball from the tube', 'In this task the contestants are instructed to retrieve a table tennis ball from the bottom of a PVC tube attached to a tray. They are instructed not to move the tube itself, and are provided with fluids which may be used to fill the tube, raising the ball to the top. However, the tube also has a number of holes drilled into it, through which the fluid will quickly drain.', '00158_retrieve_the_ping_pong_ball_from_the_tube.jpg', '00158_retrieve_the_ping_pong_ball_from_the_tube.jpg'),
(44, '|114|', 1, '|3|5|11|13|', 4, 'Ringtone choreography', 'In this task the contestants are instructed to choose a ringtone and then choreograph a dance to that ringtone for themselves and the Taskmaster’s assistant. They are also provided with a greenscreen so that the performance can be superimposed upon a background video of their choice.', '00114_ringtone_choreography.jpg', '00114_ringtone_choreography.jpg'),
(45, '|149|', 1, '|3|6|7|9|11|13|', 6, 'Score a basket without your hands', 'In this task the contestants are instructed to score a basket with a basketball without using their hands.', '00149_score_a_basket_without_your_hands.jpg', '00149_score_a_basket_without_your_hands.jpg'),
(46, '|357|', 1, '|3|6|9|11|13|14|', 7, 'Score a goal from the greatest distance', 'In this task the contestants are instructed to score a goal (often on a football pitch, but it has also been adapted for an ice hockey rink, and just throwing a frisbee into a caravan) from the greatest distance.|The contestants are also instructed to either perform an elaborate goal celebration, whether or not they successfully score the goal, or to celebrate their misses and commiserate their successful shots.|They may have just one attempt, or be given unlimited attempts.|In some versions, the Taskmaster\'s assistant actively participates as a goalkeeper.', '00357_score_a_goal_from_the_greatest_distance.jpg', '00357_score_a_goal_from_the_greatest_distance.jpg'),
(47, '|323|', 1, '|3|4|6|9|11|13|', 6, 'Sausage or finger?', 'In this live studio task the contestants take it in turns to touch each other with either a sausage (usually attached to the finger of a rubber glove), or one of their fingers. The person touched has to then guess whether it was a sausage or a finger. If they guess correctly, the person who touched them is eliminated from the task.', '00323_sausage_or_finger.jpg', '00323_sausage_or_finger.jpg'),
(48, '|58|', 1, '|3|6|', 6, 'Set a task / Guess who set the tasks', 'In this task, all but one of the contestants are instructed to write a task of their own which can be completed within a short timeframe. The remaining contestant is then assigned all of the tasks, and has to guess which one of their competitors wrote which one. Points are earned for correct guesses, or given to the task creator for incorrect guesses.', '00058_set_a_tesk_guess_who_set_the_tasks.jpg', '00058_set_a_tesk_guess_who_set_the_tasks.jpg'),
(49, '|229|', 1, '|3|4|6|9|11|', 6, 'Greet the Taskmaster without revealing your identity', 'In this live studio task, the contestants take it in turns to greet the blindfolded Taskmaster (usually by shaking hands, but a verbal greeting may be specified instead).|The Taskmaster has to guess which of the contestants greeted them.|If they guess correctly, the contestant is eliminated from the task.', '00229_shake_hands_with_the_taskmaster.jpg', '00229_shake_hands_with_the_taskmaster.jpg'),
(50, '|119|', 1, '|3|4|5|6|9|11|13|', 7, 'Slide as far as possible', 'In this task the contestants are instructed to slide as far as possible.', '00119_slide_the_furthest.jpg', '00119_slide_the_furthest.jpg'),
(51, '|167|', 1, '|3|6|11|13|', 4, 'Sneeze the fastest', 'In this task the contestants are instructed to make themselves sneeze as quickly as possible.', '00167_sneeze_the_fastest.jpg', '00167_sneeze_the_fastest.jpg'),
(52, '|210|', 1, '|3|6|9|12|13|', 5, 'Sort the objects by size using your feet', 'In this live studio task the contestants are instructed to sort a collection of objects by size under a table using just their feet. The contestants must keep their elbows on the table and their head on their hands at all times during the task. They are also instructed to remove any fruit from under the table.', '00210_sort_the_objects_by_size_using_your_feet.jpg', '00210_sort_the_objects_by_size_using_your_feet.jpg'),
(53, '|374|', 1, '|3|6|11|13|', 4, 'Stack the most bowls and plates on your head', 'In this live studio task the contestants are instructed to alternately stack the most bowls and plates on top of a mortar board on their head.', '00374_stack_the_most_bowls_and_plates_on_your_head.jpg', '00374_stack_the_most_bowls_and_plates_on_your_head.jpg'),
(54, '|72|', 1, '|3|6|9|11|13|', 5, 'Surprise the Taskmaster’s assistant', 'In this task the contestants are instructed to surprise the Taskmaster’s assistant when they come out of a shed in one hour.', '00072_surprise_alex.jpg', '00072_surprise_alex.jpg'),
(55, '|356|', 1, '|3|6|11|', 3, 'Recall the order of the deck of cards', 'In this task the contestants are instructed to tell the Taskmaster’s assistant the order of a custom deck of cards after a short period of time.', '00356_tell_alex_the_order_of_the_deck_of_cards.jpg', '00356_tell_alex_the_order_of_the_deck_of_cards.jpg'),
(56, '|1037|', 1, '|1|3|4|6|7|9|11|', 13, 'The lowest unique number of items', 'In this task the contestants are instructed to choose the lowest unique number of items. This usually takes the form of placing between one and five doughnuts on a stick which is hidden in a box. The contestant who chooses the lowest unique number of items wins. If no-one chooses a unique number of items, the game is replayed.', '01037_the_lowest_unique_number_of_doughnuts.jpg', '01037_the_lowest_unique_number_of_doughnuts.jpg'),
(57, '|3409|141|142|', 1, '|1|3|4|5|6|11|12|13|', 10, 'Make something edible and then eat your creation', 'In this task the contestants are instructed to make something edible (e.g. the most exotic sandwich, the longest piece of Christmas confectionery, a beautiful edible sculpture).|In a second task brief, sometimes assigned and scored as a separate task, they are then instructed to eat their creation.', '00141_the_most_exotic_sandwich.jpg', '00141_the_most_exotic_sandwich.jpg'),
(58, '|40|', 1, '|1|2|3|6|9|11|13|', 7, 'Get the potato into the hole', 'In this task the contestants are instructed to get a potato into a hole without touching a designated circular area around the hole.|This circular area is often in the form of a red mat (referred to as the ‘red green’), but has also been a white plastic sheet, and a circular patch of gravel.', '00040_throw_a_potato_into_a_hole.jpg', '00040_throw_a_potato_into_a_hole.jpg'),
(59, '|194|', 1, '|3|7|', 2, 'Throw an egg through a basketball hoop', 'In this live studio task the contestants are instructed to throw am egg through a basketball hoop as many times as possible in the given time.', '00194_throw_an_egg_through_a_basketball_hoop.jpg', '00194_throw_an_egg_through_a_basketball_hoop.jpg'),
(60, '|412|', 1, '|6|', 1, 'Throw eggs into receptacles', 'In this task the contestants are instructed to throw eggs into metal or concrete receptacles without leaving their chair.', '00412_throw_eggs_into_metal_things.jpg', '00412_throw_eggs_into_metal_things.jpg'),
(61, '|54|', 1, '|2|5|9|', 3, 'Catch some objects in a hat while wearing a belt', 'In this live studio task the contestants are instructed to catch something (e.g. small plush rabbit toys, or balls) in an open-topped hat that they are wearing.|The contestants begin the task with their arms strapped to their sides with a belt, and are instructed not to remove the belt.', '00054_throw_rabbits_into_a_hat.jpg', '00054_throw_rabbits_into_a_hat.jpg'),
(62, '|417|', 1, '|3|4|6|9|11|', 5, 'Throw something into a pedal bin', 'In this task the contestants are instructed to throw something into a pedal bin while ensuring that the bin’s lid is closed at the moment the object is released.', '00417_throw_something_into_a_pedal_bin.jpg', '00417_throw_something_into_a_pedal_bin.jpg'),
(63, '|122|', 1, '|3|6|7|13|', 4, 'Throw something into something', 'In this task the contestants are instructed to throw something into something in an impressive manner.', '00122_throw_something_into_something.jpg', '00122_throw_something_into_something.jpg'),
(64, '|322|', 1, '|3|6|9|11|', 4, 'Tie yourself up as securely as possible', 'In this task the contestants are instructed to tie themselves up as securely as possible within a given timeframe, after which the Taskmasters assistant will attempt to untie them as quickly as possible. As a complicating factor, the task is usually paired with another task where the contestants have to put on a boiler suit and lie down on the floor at the sound of an alarm.', '00322_tie_yourself_up_as_securely_as_possible.jpg', '00322_tie_yourself_up_as_securely_as_possible.jpg'),
(65, '|332|', 1, '|3|6|11|13|', 4, 'Transfer rice to a container in another room using the supplied objects', 'In this task the contestants are instructed to transfer rice to a container in another room using only the objects supplied.', '00332_transfer_rice_to_the_bottle_using_the_supplied_objects.jpg', '00332_transfer_rice_to_the_bottle_using_the_supplied_objects.jpg'),
(66, '|53|', 1, '|2|3|9|13|', 4, 'See nothing, hear nothing, speak nothing', 'In this team task, the contestants must achieve an objective involving a certain item (e.g. moving a vegetable from one location to another, or placing a specific item inside another) while one of them is blindfolded, one is wearing headphones, and one is not permitted to speak.', '00053_hear_no_see_no_speak_no_potato.jpg', '00053_hear_no_see_no_speak_no_potato.jpg'),
(67, '|9|', 1, '|5|', 1, 'Identify the pie fillings', 'In this task the contestants are instructed to identify the fillings of a series of pies, either without breaching the pastry or touching the pies at all (depending on the show).', '00009_identify_the_pies.jpg', '00009_identify_the_pies.jpg'),
(68, '|386|', 1, '|3|4|6|12|', 4, 'Identify which bin the Taskmaster’s assistant is in', 'In this task the contestants are instructed to identify which bin contains the Taskmaster’s assistant. They are permitted to use certain methods to investigate some of the bins, to help them eliminate them.|In the episode of Taskmaster: The People\'s Podcast released on 22 July 2022, David Sundin revealed that a version of this task had been tried twice by Bäst i Test but that the results were never good enough. He also shared that they would be trying it again (possibly for the last time) for season 7 of the show.', '00386_identify_which_bin_alex_is_in.jpg', '00386_identify_which_bin_alex_is_in.jpg'),
(69, '|50|', 1, '|2|3|4|6|7|8|9|', 10, 'Impress a respectable person', 'In this task the contestants are instructed to impress someone within a limited timeframe. Often the individual to be impressed is a dignitary, such as a Mayor or Ambassador, but it may also be someone else respectable, such as a centenarian.', '00050_impress_the_mayor.jpg', '00050_impress_the_mayor.jpg'),
(70, '|313|', 1, '|6|', 1, 'Improve your hula-hooping', 'In this task, which is often assigned as a special task to one individual or a subset of the contestants, the contestants are instructed to improve their hula-hooping ability over an extended period, culminating in an in-studio demonstration of their skill.', '00313_take_a_photo_of_yourself_in_a_fez_improve_your_hula_ing.jpg', '00313_take_a_photo_of_yourself_in_a_fez_improve_your_hula_ing.jpg'),
(71, '|100|', 1, '|3|6|9|13|', 4, 'Keep the basketball on the treadmill', 'In this task the contestants are instructed to keep a basketball on a treadmill for as long as possible without touching either item.|They are given a very short time to prepare before the treadmill is turned on.', '00100_keep_the_basketball_on_the_treadmill.jpg', '00100_keep_the_basketball_on_the_treadmill.jpg'),
(72, '|97|', 1, '|3|4|5|6|7|11|13|', 8, 'Fell all the ducks', 'In this task the contestants are instructed to knock over all of the rubber ducks in the garden as quickly as possible. The ducks are typically balanced on top of fence panels and breeze blocks. The contestants must be behind a line or velvet rope when the ducks fall.', '00097_knock_over_all_the_ducks.jpg', '00097_knock_over_all_the_ducks.jpg'),
(73, '|78|', 1, '|6|9|13|', 3, 'Fill a receptacle with sweat', 'In this task the contestants are instructed to fill a small receptacle (usually an eggcup, but may also be a sample cup) with as much sweat as possible within a limited timeframe.', '00078_fill_an_egg_cup_with_sweat.jpg', '00078_fill_an_egg_cup_with_sweat.jpg'),
(74, '|41|', 1, '|2|3|4|5|6|9|11|12|13|', 9, 'Find out about the foreign person', 'In this task the contestants are instructed to find out as much as possible about a person who understands their language, but may only reply in their native language.', '00041_find_out_about_the_swedish_person.jpg', '00041_find_out_about_the_swedish_person.jpg'),
(75, '|813|', 5, '|1|3|6|9|', 4, 'Find out what you have in common with a stranger', 'In this task the contestants are instructed to find out the most interesting thing they have in common with a stranger.', '00813_find_out_what_you_have_in_common_with_a_stranger.jpg', '00813_find_out_what_you_have_in_common_with_a_stranger.jpg'),
(76, '|202|', 1, '|3|4|6|9|', 4, 'Find out what’s in the briefcase', 'In this task the contestants are instructed to find out what’s in a locked briefcase as quickly as possible. Clues to the number needed to unlock the case’s combination locks are provided in the room, but the contestants are also permitted to deduce the contents in other ways, or break open the case by force.', '00202_find_out_whats_in_the_briefcase.jpg', '00202_find_out_whats_in_the_briefcase.jpg'),
(77, '|325|', 1, '|3|4|6|', 3, 'Find the baby monitor receiver', 'In this task the contestants are instructed to find a baby monitor receiver as quickly as possible while wearing a transmitter attached to a helmet.', '00325_find_the_baby_monitor_receiver.jpg', '00325_find_the_baby_monitor_receiver.jpg'),
(78, '|870|', 3, '|1|3|5|9|', 8, 'Identify the people of a given demographic', 'In this live studio task the contestants are instructed to identify the individual(s) of a given demographic (often a specific nationality) from a group of strangers lined up on stage.|Sometimes they are permitted to ask questions, but sometimes it is a game based purely on guesswork.', '00870_find_the_finns.jpg', '00870_find_the_finns.jpg'),
(79, '|174|', 1, '|3|4|5|6|11|', 5, 'Build a can tower while naming different countries', 'In this task the contestants are instructed to build a can tower on a table, while either naming unique countries or greeting the Taskmaster’s assistant as if from a different country (either every 10 seconds, or before each can is placed).|In solo versions of the task, the contestants are usually tethered to a table with a short piece of rope, and the cans are usually in an immovable container.', '00174_build_a_can_tower.jpg', '00174_build_a_can_tower.jpg'),
(80, '|425|', 1, '|4|6|11|12|13|', 5, 'Communicate pictures by drawing on your team-mate’s back', 'In this live studio team task the contestants take it in turns to convey a line drawing to their team-mates by drawing on their backs with their fingers. The contestant at the front of the line renders the drawing on paper with a marker, and it is then compared to the original drawing.', '00425_communicate_a_picture_by_drawing_on_your_team_mates_back.jpg', '00425_communicate_a_picture_by_drawing_on_your_team_mates_back.jpg'),
(81, '|116|', 1, '|5|', 1, 'Do something brilliant with a pommel horse', 'In this task the contestants are instructed to do something brilliant with a pommel horse.', '00116_do_something_brilliant_with_a_pommel_horse.jpg', '00116_do_something_brilliant_with_a_pommel_horse.jpg'),
(82, '|339|', 1, '|3|6|9|11|', 4, 'Do the worst thing and make the best apology', 'In this task the contestants are instructed to do the worst thing to the Taskmaster’s assistant, and then make the best apology for it.', '00339_do_the_worst_thing_and_make_the_best_apology.jpg', '00339_do_the_worst_thing_and_make_the_best_apology.jpg'),
(83, '|871|', 3, '|1|4|6|9|11|12|13|', 7, 'Don’t blink', 'In this task the contestants are instructed to not blink for as long as possible.', '00871_dont_blink.jpg', '00871_dont_blink.jpg'),
(84, '|96|', 1, '|3|6|9|11|13|', 5, 'Draw a blind portrait', 'In this task the contestants are instructed to draw a portrait of a hidden stranger based upon their answers to questions (to which they may only replay ‘yes’ or ‘no’). They are also offered bonus points if they are able to identify the stranger’s full name.', '00096_draw_a_blind_caricature.jpg', '00096_draw_a_blind_caricature.jpg'),
(85, '|1036|', 1, '|1|7|', 2, 'Create the best flag meal', 'In this task the contestants are instructed to create the best ‘flag meal’ (i.e. a meal which looks like a flag).\r\n', '01036_create_the_best_flag_meal.jpg', '01036_create_the_best_flag_meal.jpg'),
(86, '|348|', 1, '|6|9|11|13|', 4, 'Divert the sand from one bucket to another', 'In this task the contestants are instructed to get as much sand as possible from one bucket (hanging from the ceiling) to another (a short distance away on the floor) using only the items supplied in the room, before the sand stops flowing from the first bucket. Their hand is tethered to a blockage in a hole of the first bucket in such a way that the sand typically starts to flow before they have even read the task brief, which they have to stretch to reach.', '00348_divert_the_sand_from_one_bucket_to_another.jpg', '00348_divert_the_sand_from_one_bucket_to_another.jpg'),
(87, '|145|', 1, '|3|9|11|13|', 6, 'Draw the median thing', 'In this task (usually a live studio task) the contestants are instructed to draw the median-sized version of a specific thing (e.g. a duck, Buddha, or the Taskmaster).|The person with the median-sized thing wins the task.', '00145_draw_the_median_duck.jpg', '00145_draw_the_median_duck.jpg'),
(88, '|384|', 1, '|3|4|6|11|', 4, 'Draw a snake on a toilet roll', 'In this live studio task the contestants are instructed to draw a snake on a roll of toilet paper.|In most versions they are instructed to draw the second longest snake, but in at least one version they are told to draw the longest.|A bonus point may also be made available for the ‘best’ snake.', '00384_draw_the_second_longest_snake.jpg', '00384_draw_the_second_longest_snake.jpg'),
(89, '|420|', 1, '|3|6|11|13|', 4, 'Draw your own face on a face shield', 'In this live studio task the contestants are instructed to draw their own face on a face shield that they are wearing, with a specific expression (e.g. happy or angry).', '00420_draw_your_own_face_on_a_welders_mask.jpg', '00420_draw_your_own_face_on_a_welders_mask.jpg'),
(90, '|44|', 1, '|2|6|11|13|', 4, 'Quickly eat an egg', 'In this task the contestants are instructed to eat an egg as quickly as possible.', '00044_eat_an_egg_the_fastest.jpg', '00044_eat_an_egg_the_fastest.jpg'),
(91, '|95|', 1, '|3|5|6|13|', 4, 'Beautifully destroy a cake', 'In this task the contestants are instructed to destroy a cake in a beautiful way.', '00095_beautifully_destroy_a_cake.jpg', '00095_beautifully_destroy_a_cake.jpg'),
(92, '|262|', 1, '|3|4|6|11|12|13|', 6, 'Blow out a candle from a distance', 'In this task the contestants are instructed to blow out a candle from as far away as possible. Certain items may be provided in the room for them to use, or it may be left completely open-ended.', '00262_blow_out_a_candle_from_a_distance.jpg', '00262_blow_out_a_candle_from_a_distance.jpg'),
(93, '|742|', 4, '|1|3|6|', 3, 'Prepare beverages using items secured to a table', 'In this task the contestants are instructed to prepare or pour a beverage (tea, coffee, juice, etc) using equipment which is either glued or padlocked to a table.', '00742_fill_the_cup_with_coffee.jpg', '00742_fill_the_cup_with_coffee.jpg'),
(94, '|203|', 1, '|6|', 1, 'Make a delicious mask', 'In this task the contestants are instructed to make and wear a mask entirely from food. The Taskmaster’s assistant then samples the food mask directly from their faces.', '00203_make_a_delicious_mask.jpg', '00203_make_a_delicious_mask.jpg'),
(95, '|296|', 1, '|6|11|', 2, 'Make a portrait using your 50 items', 'In this task the contestants are instructed to make a portrait of the Taskmaster or the Taskmaster\'s assistant using just the 50 items they previously put into a bin, in an associated task.', '00296_make_a_picture_of_the_taskmaster_using_50_items.jpg', '00296_make_a_picture_of_the_taskmaster_using_50_items.jpg'),
(96, '|402|', 1, '|3|6|11|13|16|', 5, 'Lasso the Taskmaster’s assistant', 'In this task the contestants are instructed to lasso the Taskmaster’s assistant as quickly as possible.', '00402_lassoo_alex.jpg', '00402_lassoo_alex.jpg'),
(97, '|180|', 1, '|3|6|11|13|', 4, 'Light a candle using a carried flame', 'In this task the contestants are instructed to light a candle in a separate location using the flame on a candle they are given upon receiving the task brief. All paths between the two locations are typically littered with obstacles which might extinguish their flame, such as fans, sprinklers, and bubble machines. The candle they carry is often in the form of a small birthday candle on a cupcake.', '00180_light_a_candle_using_a_cupcake.jpg', '00180_light_a_candle_using_a_cupcake.jpg'),
(98, '|367|', 1, '|3|6|11|13|', 4, 'Move the beach ball across the finish line using only water', 'In this task the contestants are instructed to move a beach ball across a finish line using only water.', '00367_move_the_beach_ball_using_only_water.jpg', '00367_move_the_beach_ball_using_only_water.jpg'),
(99, '|90|', 1, '|3|11|', 2, 'Move water from one bucket to another', 'In this task the contestants are instructed to transfer as much water as possible from one bucket to another. The buckets are situated 100m apart on a running track, and the contestants are not permitted to move either bucket. A collection of items is provided to help them move the water, but all of the receptacles available have holes in them.', '00090_move_water_from_one_bucket_to_another.jpg', '00090_move_water_from_one_bucket_to_another.jpg'),
(100, '|76|', 1, '|4|6|11|13|15|', 5, 'Unravel the tape', 'In this live studio task the contestants have to unravel an entire roll of adhesive tape and put all of it inside a container as quickly as possible.', '00076_unravel_the_tape.jpg', '00076_unravel_the_tape.jpg'),
(101, '|268|', 1, '|6|9|11|', 3, 'Work out the perimeter of something in terms of small edible items', 'In this task the contestants are instructed to calculate the perimeter of a large outdoor object (e.g. a shed or caravan) in terms of small edible items (e.g. baked beans or meatballs). The contestant who comes up with the closest estimate wins.', '00268_work_out_the_circumference_of_the_caravan_in_beans.jpg', '00268_work_out_the_circumference_of_the_caravan_in_beans.jpg'),
(102, '|231|', 1, '|6|11|', 2, 'Work out the length of a piece of string', 'In this task the contestants are instructed to estimate the length of a long piece of string, much of which has been trailed around the house, without leaving the location in which they receive the task brief.', '00231_work_out_the_length_of_a_piece_of_string.jpg', '00231_work_out_the_length_of_a_piece_of_string.jpg'),
(103, '|283|', 1, '|3|4|6|', 3, 'Work out what the switch does', 'In this task the contestants are instructed to figure out what an electrical switch does. The Taskmaster house is filled with dozens of extra electrical appliances during the task to distract them from what actually happens when the switch is flipped, which is a manual action performed by the Taskmaster’s assistant.', '00283_work_out_what_the_switch_does.jpg', '00283_work_out_what_the_switch_does.jpg'),
(104, '|219|', 1, '|6|12|', 2, 'Write a grown-up bedtime story', 'In this task the contestants are instructed to write, illustrate and read out an original bedtime story for adults.', '00219_write_a_grown_up_bedtime_story.jpg', '00219_write_a_grown_up_bedtime_story.jpg'),
(105, '|154|', 1, '|3|9|', 2, 'Slice bread using something from a specific location', 'In this task the contestants are instructed to cut as many slices as possible from a loaf of bread using only items they have found in a specific location (e.g. the caravan or shed).', '00154_slice_bread_with_something_from_the_caravan.jpg', '00154_slice_bread_with_something_from_the_caravan.jpg'),
(106, '|410|', 1, '|4|6|11|13|', 4, 'Slide bar orders to the Taskmaster', 'In this live studio task the contestants are instructed to slide drinks - and sometimes also food - to the Taskmaster, along a long wooden bar. Those who fail or are least accurate in each round are eliminated from the task.', '00410_slide_drinks_to_the_taskmaster.jpg', '00410_slide_drinks_to_the_taskmaster.jpg'),
(107, '|326|', 1, '|3|6|11|', 3, 'Make and interact with a ventriloquist dummy', 'In this task the contestants are instructed to make and then interact with a ventriloquist dummy.|In some versions, they are instructed to be seduced by the dummy.', '00326_make_a_ventiloquist_dummy.jpg', '00326_make_a_ventiloquist_dummy.jpg'),
(108, '|403|', 1, '|3|4|6|9|12|', 5, 'Make an accurate and inventive food timer', 'In this task the contestants are instructed to make an accurate and inventive food timer (e.g. for an egg or a pizza).|The food is then cooked according to how long the food timer runs for, and the contestants are judged on how that turns out.', '00403_make_an_accurate_and_inventive_egg_timer.jpg', '00403_make_an_accurate_and_inventive_egg_timer.jpg'),
(109, '|275|', 1, '|6|13|', 2, 'Build the tallest can tower within your hoop', 'In this live studio task the contestants are instructed to build a tower of cans within a small hoop, while standing in the hoop.', '00275_build_the_tallest_can_tower.jpg', '00275_build_the_tallest_can_tower.jpg'),
(110, '|366|', 1, '|3|6|11|', 3, 'Catch the most tennis balls', 'In this task the contestants are instructed to catch the most tennis balls using household items. The tennis balls are fired from different directions by serving machines. The task has been used as both a team and solo task, with differing requirements.', '00366_catch_or_dont_catch_the_tennis_balls.jpg', '00366_catch_or_dont_catch_the_tennis_balls.jpg'),
(111, '|930|', 3, '|1|4|9|', 3, 'Draw something upside-down', 'In this live studio task the contestants are instructed to draw a specific item upside-down.', '00930_draw_an_upside_down_bicycle.jpg', '00930_draw_an_upside_down_bicycle.jpg'),
(112, '|922|', 3, '|9|', 1, 'Drop an egg as far as possible without breaking it', 'In this task the contestants are instructed to drop an egg as far as possible without it breaking.', '00922_drop_the_egg_as_far_as_possible_without_it_breaking.jpg', '00922_drop_the_egg_as_far_as_possible_without_it_breaking.jpg'),
(113, '|85|', 1, '|3|6|11|13|', 7, 'Find out something from the lying stranger', 'In this task the contestants are instructed to find out a specific piece of information from a stranger. The stranger is only permitted to respond by nodding or shaking their head, and they always lie. The contestant is instructed to only speak in a whisper throughout the task, and may also be instructed to speak in an accent or dialect other than their own.', '00085_find_out_the_lying_old_mans_occupation.jpg', '00085_find_out_the_lying_old_mans_occupation.jpg'),
(114, '|360|', 1, '|6|13|', 2, 'Find something on the tables', 'In this task the contestants are presented with a grid of tables, each of which has an upturned bowl or a box on it, and are asked to find something under one or more of them (e.g. apples or an elf).|One of the bowls has under it another item (e.g. a green egg, or a lime, or photo of the Taskmaster) which, if discovered, leads to their disqualification.|Clues are usually hidden around the location, providing hints as to the location of the items sought.', '00360_find_the_pink_ladies.jpg', '00360_find_the_pink_ladies.jpg'),
(115, '|315|', 1, '|3|4|6|9|', 4, 'Find the sock containing a specific citrus fruit', 'In this task the contestants are instructed to find out which of many socks (or Christmas stockings) hung from a washing line contains a specific citrus fruit (e.g. a clementine or satsuma). The contestants are permitted to perform certain actions a certain number of times to help them eliminate many of the socks.', '00315_find_the_sock_containing_a_satsuma.jpg', '00315_find_the_sock_containing_a_satsuma.jpg'),
(116, '|39|', 1, '|2|3|4|6|9|13|', 6, 'Get the exercise balls into a small area at the top of a hill', 'In this task the contestants are instructed to get a collection of exercise balls up a hill and into a specified small area (sometimes a yoga mat).', '00039_place_the_exercise_balls_on_the_yoga_mat.jpg', '00039_place_the_exercise_balls_on_the_yoga_mat.jpg'),
(117, '|297|', 1, '|3|6|9|11|12|', 6, 'Make a cliff-hanger', 'In this task the contestants are instructed to make a short film (a movie, or soap opera) with a cliff-hanger ending.', '00297_make_a_soap_opera_cliffhanger.jpg', '00297_make_a_soap_opera_cliffhanger.jpg'),
(118, '|220|', 1, '|3|6|9|11|13|', 5, 'Make something spin for the longest', 'In this task the contestants are instructed to make something spin for the longest without influencing its spin after the time starts.', '00220_make_something_spin_for_the_longest.jpg', '00220_make_something_spin_for_the_longest.jpg'),
(119, '|279|', 1, '|3|6|11|', 3, 'Make the best noise', 'In this task the contestants are instructed to make the best noise.', '00279_make_the_best_noise.jpg', '00279_make_the_best_noise.jpg'),
(120, '|266|', 1, '|3|6|11|13|', 4, 'Make the best quick-change outfit', 'In this task the contestants are instructed to make the best quick-change outfit.', '00266_make_the_best_quick_change_outfit.jpg', '00266_make_the_best_quick_change_outfit.jpg'),
(121, '|115|', 1, '|5|12|', 2, 'Make the best toilet paper celebrity portrait', 'In this task the contestants are instructed to make the best toilet paper celebrity portrait.', '00115_make_the_best_toilet_paper_celebrity_portrait.jpg', '00115_make_the_best_toilet_paper_celebrity_portrait.jpg'),
(122, '|239|', 1, '|6|', 1, 'Make the best announcement', 'In this task the contestants are instructed to make the best announcement.', '00239_make_the_biggest_announcement.jpg', '00239_make_the_biggest_announcement.jpg'),
(123, '|255|', 1, '|3|6|9|13|', 4, 'Make the biggest bubble and burst it with your nose', 'In this task the contestants are instructed to make the biggest bubble and then burst it with their nose.', '00255_make_the_biggest_bubble_and_burst_it_with_your_nose.jpg', '00255_make_the_biggest_bubble_and_burst_it_with_your_nose.jpg'),
(124, '|113|', 1, '|3|6|9|11|13|', 5, 'Make the highest splash', 'In this task the contestants are instructed to make the highest splash.', '00113_make_the_highest_splash.jpg', '00113_make_the_highest_splash.jpg'),
(125, '|104|', 1, '|3|5|6|7|', 4, 'Make the longest balloon chain', 'In this live studio task the contestants are instructed to make the longest chain of balloons beneath a large smock.', '00104_make_the_longest_balloon_chain.jpg', '00104_make_the_longest_balloon_chain.jpg'),
(126, '|123|', 1, '|3|6|7|9|13|', 5, 'Make the longest continuous noise', 'In this live studio task the contestants are instructed to make the longest continuous noise. Those contestants who have not yet taken their turn are blindfolded and wear headphones, so that they can’t tell what the others have done.', '00123_make_the_longest_continuous_noise.jpg', '00123_make_the_longest_continuous_noise.jpg'),
(127, '|247|', 1, '|3|6|', 2, 'Roll eggs to the centre of the target', 'In this live studio task the contestants are instructed to roll eggs to the centre of a target. The contestant whose egg is closest to the centre of the target wins.', '00247_rolls_eggs_to_the_centre_of_the_target.jpg', '00247_rolls_eggs_to_the_centre_of_the_target.jpg'),
(128, '|249|', 1, '|1|6|9|', 3, 'Put something surprising inside a receptacle', 'In this task the contestants are instructed to put something surprising or unusual inside a receptacle, such as a chocolate egg, plastic lemon, or handbag.|In some versions of the task, the Taskmaster or their assistant reveals the item, while in others the contestants reveal it themselves as part of their attempt.|The most surprising or unusual item wins.', '00249_put_something_surprising_inside_a_chocolate_egg.jpg', '00249_put_something_surprising_inside_a_chocolate_egg.jpg'),
(129, '|65|', 1, '|5|6|11|', 3, 'Put on gloves, eat a banana, put on a tie, and do something else as many times as possible', 'In this live studio task the contestants are instructed to put on gloves, eat a banana, put on a tie, and then do something else specific (e.g. clap, or blow bubbles) as many times as possible with the remaining time.', '00065_put_on_gloves_eat_a_banana_put_on_a_tie_clap.jpg', '00065_put_on_gloves_eat_a_banana_put_on_a_tie_clap.jpg'),
(130, '|48|', 1, '|2|6|11|16|', 4, 'Put round things in a basket using sticks', 'In this live studio task the contestants are instructed to collect some round things (e.g. potatoes or balls) in a basket, using long sticks (e.g. pool cues) with something on the end to help them grip (e.g. rubber balls or rubber chicken heads) as giant chopsticks.', '00048_put_potatoes_in_a_basket.jpg', '00048_put_potatoes_in_a_basket.jpg'),
(131, '|319|', 1, '|3|6|11|', 3, 'Put on overalls and lie on the ground when you hear the alarm', 'In this task the contestants are instructed to put on overalls and lie on the ground when they hear an alarm. The task is set up to be called back on during a separate task, in which the contestants have been instructed to tie themselves up as securely as possible.', '00319_put_on_a_boiler_suit_and_lie_on_the_ground.jpg', '00319_put_on_a_boiler_suit_and_lie_on_the_ground.jpg'),
(132, '|295|', 1, '|6|9|11|', 3, 'Put 50 different things in the bin', 'In this task the contestants are instructed to put 50 different things in a bin.|The task is usually followed by a separate task, in which the contestants have to make a portrait of the Taskmaster using only the items they have put in their bin. However, there has been one instance of this task being used alone.', '00295_put_50_different_things_in_the_bin.jpg', '00295_put_50_different_things_in_the_bin.jpg'),
(133, '|132|', 1, '|3|7|11|', 3, 'Prepare the items / Lift all the items in one hand', 'In this live studio task the contestants are first instructed to ‘prepare’ a collection of items for the second part of the task, with no idea of what that will involve. The second part of the task instructs them to hold all of the items with one hand and place their other hand on their head.', '00132_prepare_the_items_lift_all_the_items.jpg', '00132_prepare_the_items_lift_all_the_items.jpg'),
(134, '|102|', 1, '|3|4|5|6|13|', 5, 'Get the flour to the target', 'In this task, often set as a team task, the contestants are instructed to get as much flour onto a target (or into a bowl) as possible, while remaining within a defined area (or not leaving the area while carrying flour).|In most versions the contestants are provided with a collection of supplies to help them move the flour.', '00102_get_as_much_flour_on_the_target_as_possible.jpg', '00102_get_as_much_flour_on_the_target_as_possible.jpg'),
(135, '|213|', 1, '|3|4|6|9|', 4, 'Get the highest darts score', 'In this task the contestants are instructed to get the highest score in darts. They are given an option of three distances from which to throw the darts, with more darts available to them, the further away they choose to stand.', '00213_get_the_highest_darts_score.jpg', '00213_get_the_highest_darts_score.jpg'),
(136, '|185|', 1, '|6|9|', 2, 'Fruit or vegetable bobsleigh', 'In this task the contestants are instructed to get as many fruits or vegetables (e.g. coconuts or cabbages) as possible down a slope while on a vehicle (e.g. a skateboard or toboggan).|They may use other items from a specific location (e.g. caravan or shed), but face disqualification if they use the same item as someone else.', '00185_coconut_bobsleigh.jpg', '00185_coconut_bobsleigh.jpg'),
(137, '|152|', 1, '|3|6|9|11|12|13|', 6, 'Make a coconut-flinging machine', 'In this task the contestants are instructed to make a coconut-flinging machine to throw a coconut as far as possible.', '00152_make_a_coconut_flinging_machine.jpg', '00152_make_a_coconut_flinging_machine.jpg'),
(138, '|2235|', 1, '|1|3|6|7|9|11|12|', 8, 'Order something without using certain words', 'In this task the contestants are instructed to order something (e.g. a pizza, or balloons) via phone without using certain words.|A bonus point is also available to those contestants who can make the person on the other end of the phone say a specific word.', '00047_order_a_pizza_without_using_certain_words.jpg', '00047_order_a_pizza_without_using_certain_words.jpg'),
(139, '|101|', 1, '|3|6|12|', 3, 'Paint a portrait of the Taskmaster without transgressing', 'In this task the contestants are instructed to paint a portrait of the Taskmaster, but are restricted on how close they can get to the canvas.|In most cases, this restriction takes the form of a circular mat, which may only be touched by paint or brushes.|However, the restriction may also be in the form of a rope which they are not permitted to cross or move.', '00101_paint_the_taskmaster_without_touching_the_mat.jpg', '00101_paint_the_taskmaster_without_touching_the_mat.jpg'),
(140, '|156|', 1, '|6|13|', 2, 'Paint your own canvas', 'In this live studio task the contestants are wearing a canvas around their face and covering their torso, and are instructed to paint something recognisable on the canvas.', '00156_paint_your_own_canvas.jpg', '00156_paint_your_own_canvas.jpg'),
(141, '|126|', 1, '|5|6|', 2, 'Pass a stuffed toy through a small gap', 'In this task the contestants are instructed to pass a stuffed toy through as small a gap as possible.', '00126_pass_a_camel_through_a_small_gap.jpg', '00126_pass_a_camel_through_a_small_gap.jpg'),
(142, '|140|', 1, '|3|4|', 2, 'The most cash', 'In this prize task, the contestants are instructed to bring in the most cash.', '00140_the_most_cash.jpg', '00140_the_most_cash.jpg'),
(143, '|1|', 1, '|2|3|', 2, 'The most unusual item', 'In this prize task, the contestants are instructed to bring in the most unusual item.', '00001_most_unusual_item.jpg', '00001_most_unusual_item.jpg'),
(144, '|27|', 1, '|2|3|13|', 3, 'The most valuable item', 'In this prize task the contestants are instructed to bring in the most valuable item.', '00027_the_most_valuable_item.jpg', '00027_the_most_valuable_item.jpg'),
(145, '|43|', 1, '|2|3|9|13|', 4, 'The trendiest item of clothing', 'In this prize task the contestants are instructed to bring in the trendiest item of clothing.', '00043_the_trendiest_clothing.jpg', '00043_the_trendiest_clothing.jpg'),
(146, '|184|', 1, '|6|11|', 2, 'Travel blindfolded for three minutes and retrace your steps', 'In this task the contestants are instructed to travel blindfolded for three minutes and then retrace their steps as accurately as possible. They are usually provided with a slice of bread at the start, but given no idea of its purpose.', '00184_travel_blindfolded_and_retrace_your_steps.jpg', '00184_travel_blindfolded_and_retrace_your_steps.jpg'),
(147, '|161|', 1, '|3|5|6|9|12|', 5, 'Word table tennis', 'In this live studio task the contestants hare instructed to play a game of table tennis in which they have to name a word, each time they strike the ball, which begins with the last letter of the previous word.', '00161_word_table_tennis.jpg', '00161_word_table_tennis.jpg'),
(148, '|1370|', 2, '|1|6|', 2, 'Write down and then mime animals', 'In this task (which has been used as both a solo and team pre-recorded task, and as a live solo studio task) the contestants have to write down the name(s) of one or more animals (optionally of an obscure or fantasy nature). They then have to convey the identity of the animal(s) they have written to either their team mates, or the Taskmaster, or the Taskmaster\'s assistant, through mime alone.', '01370_list_and_then_mime_animals.jpg', '01370_list_and_then_mime_animals.jpg'),
(149, '|378|', 1, '|3|6|11|', 3, 'Blindly drive a vehicle around a course', 'In this task the contestants are instructed to drive a small vehicle (e.g. a mobility scooter or tricycle) around a course while blindfolded, performing certain actions along the way, and then park it in a specific space.', '00378_drive_a_mobility_scooter_blindfolded.jpg', '00378_drive_a_mobility_scooter_blindfolded.jpg'),
(150, '|99|', 1, '|3|', 1, 'The most boastful item', 'In this prize task the contestants are instructed to bring in the most boastful item.', '00099_the_most_boastful_item.jpg', '00099_the_most_boastful_item.jpg'),
(151, '|49|', 1, '|3|', 1, 'The best dinner party guest', 'In this prize task the contestants are instructed to bring in the best dinner party guest.', '00049_the_best_dinner_party_guest.jpg', '00049_the_best_dinner_party_guest.jpg'),
(152, '|299|', 1, '|6|12|', 2, 'Get your inflatable ring as high as possible while holding hands', 'In this live studio task the contestants are instructed to get their inflatable ring as high as possible while holding hands with people on either side of them.', '00299_get_your_doughnut_as_high_as_possible.jpg', '00299_get_your_doughnut_as_high_as_possible.jpg'),
(153, '|949|', 10, '|6|', 1, 'Make the best investment', 'In this task the contestants are instructed to make the best investment using a specific amount of seed money.', '00588_make_the_best_investment.jpg', '00588_make_the_best_investment.jpg'),
(154, '|285|', 1, '|3|6|9|11|13|', 5, 'Make the scales read exactly a given weight', 'In this task the contestants are instructed to make make the display on a set of digital scales equal to a specified value.', '00285_make_the_scales_read_exactly_31770kg.jpg', '00285_make_the_scales_read_exactly_31770kg.jpg'),
(155, '|274|', 1, '|6|9|13|', 3, 'Draw a circle', 'In this task the contestants are instructed to draw a circle in a single stroke.|The task might be judged based on who has drawn the biggest and best circle, or on other criteria such as who has drawn the median-sized circle.', '00274_draw_the_biggest_and_best_circle.jpg', '00274_draw_the_biggest_and_best_circle.jpg'),
(156, '|2|', 1, '|3|6|9|11|12|13|', 7, 'Eat as much watermelon as possible', 'In this task the contestants are instructed to eat as much watermelon as possible in a given timeframe.', '00002_eating_watermelon.jpg', '00002_eating_watermelon.jpg'),
(157, '|414|', 1, '|6|11|', 2, 'Find and put the rings on the stick', 'In this task the contestants are instructed to find as many rings as possible, and put them on a stick, while keeping their hands together at all times.', '00414_find_and_put_the_gold_rings_on_a_stick.jpg', '00414_find_and_put_the_gold_rings_on_a_stick.jpg'),
(158, '|150|', 1, '|6|', 1, 'Get some fruit into the fishbowl', 'In this live studio task the contestants are instructed to get some fruit into a fishbowl using supplies provided, without leaving their seats or throwing the fruit.', '00150_get_some_fruit_into_the_fishbowl.jpg', '00150_get_some_fruit_into_the_fishbowl.jpg'),
(159, '|404|', 1, '|6|11|', 2, 'Get to know a person who alternately tells the truth, lies, and brags', 'In this task the contestants are instructed to find out about an individual who alternately tells the truth, lies, and brags.', '00404_get_to_know_a_person_who_alternately_tells_the_truth_lies_and_brags.jpg', '00404_get_to_know_a_person_who_alternately_tells_the_truth_lies_and_brags.jpg'),
(160, '|251|', 1, '|1|6|', 2, 'Create a join-the-dots image', 'In this task the contestants are instructed to create a join-the-dots image.|The nature and scale of the medium in which the image must be plotted may vary (e.g. it could be using stiletto heels in a large sheet of polystyrene, or stakes and string on a lawn, or marker spots in a field).', '00251_make_a_join_the_dots_with_stillettos.jpg', '00251_make_a_join_the_dots_with_stillettos.jpg'),
(161, '|153|', 1, '|4|6|', 2, 'Painting in the dark', 'In this task the contestants are instructed to complete a painting on a canvas in a dark room.|In some versions, the edges of the paint pots, table and canvas are highlighted with glow-in-the-dark tape, but no visual indication is given as to the colours of the available paints.|In another version, no such visual indicators are provided.|The light switch is also available to the contestants, though many do not notice or think of this.', '00153_paint_a_rainbow_in_the_dark.jpg', '00153_paint_a_rainbow_in_the_dark.jpg'),
(162, '|408|', 1, '|6|13|', 2, 'Push a watermelon up a slide using only breadsticks', 'In this task the contestants are instructed to push a watermelon up a slide using only breadsticks.', '00408_push_a_watermelon_up_a_slide_using_breadsticks.jpg', '00408_push_a_watermelon_up_a_slide_using_breadsticks.jpg'),
(163, '|331|', 1, '|3|6|9|13|', 4, 'Make facial hair out of something unexpected', 'In this task the contestants are instructed to make a moustache or beard out of something unexpected. The Taskmaster is then shown a still image of the contestant wearing the facial hair, and makes a guess as to what they might have made it out of, before a video is shown, revealing the truth.', '00331_something_that_looks_like_a_moustache.jpg', '00331_something_that_looks_like_a_moustache.jpg'),
(164, '|60|', 1, '|2|6|', 2, 'Build the tallest tower using potato products', 'In this live studio task the contestants are instructed to build the tallest tower possible using only potato-based products (e.g. potatoes, potato waffles, etc).', '00060_build_the_tallest_potato_tower.jpg', '00060_build_the_tallest_potato_tower.jpg'),
(165, '|205|', 1, '|3|', 1, 'Record the most steps on your pedometers', 'In this live studio task the contestants have pedometers attached to various parts of their bodies, and have to get them to register the most steps in a limited timeframe.', '00205_record_the_most_steps_on_your_pedometers.jpg', '00205_record_the_most_steps_on_your_pedometers.jpg'),
(166, '|261|', 1, '|3|6|9|', 3, 'Knock over the fewest bowling pins', 'In this task the contestants have to prevent a group of bowling balls from knocking over as many bowling pins as possible by adding obstacles to the sections of an inclined bowling lane.|They are restricted as to the items they can use as obstacles, and the number they can use in each section of the lane.', '00261_protect_the_skittles_using_objects_from_the_table.jpg', '00261_protect_the_skittles_using_objects_from_the_table.jpg'),
(167, '|188|', 1, '|3|11|', 2, 'Zipwire items to the Taskmaster', 'In this task the contestants have to transport items from their table to the Taskmaster’s desk using a wire strung between the two. The surface of the Taskmaster’s desk is divided to provide a landing zone for each contestant’s items.', '00188_zipwire_items_to_the_taskmaster.jpg', '00188_zipwire_items_to_the_taskmaster.jpg'),
(168, '|165|166|4468|', 1, '|3|8|9|13|15|16|', 6, 'Perform an irrelevant task / Spot the difference', 'In this double task the contestants are first instructed to complete a task which serves mainly to distract them from paying attention to their surroundings (e.g. inflate a balloon a specific size while wearing a blindfold, or leave the room and return in exactly 11 minutes).|They then receive a second task brief, which instructs them to identify the changes that have been made at the location while they were blindfolded or out of the room.', '00165_blow_up_a_balloon.jpg', '00165_blow_up_a_balloon.jpg'),
(169, '|207|', 1, '|3|', 1, 'Perform the best wheelbarrow stunt', 'In this task the contestants are instructed to perform a task incorporating a wheelbarrow. It has been used as both a solo and team task.', '00207_perform_the_best_wheelbarrow_stunt.jpg', '00207_perform_the_best_wheelbarrow_stunt.jpg'),
(170, '|209|', 1, '|3|', 1, 'Return to the Taskmaster’s house wearing a hat', 'In this task the contestants are dropped off in an unknown location and instructed to find their way back to the Taskmaster’s house wearing a hat which they have sourced along the way. The winner is the person who   makes it back as close as possible to a given time limit.', '00209_kiss_the_taskmasters_portrait.jpg', '00209_kiss_the_taskmasters_portrait.jpg'),
(171, '|84|', 1, '|3|9|11|', 3, 'Spread your possessions far and wide', 'In this task the contestants are instructed to spread four possessions as far and wide as possible within a given timeframe.', '00084_spread_your_clothes_far_and_wide.jpg', '00084_spread_your_clothes_far_and_wide.jpg'),
(172, '|110|', 1, '|3|6|9|12|13|', 5, 'Musical words', 'In this live studio task the contestants are instructed to say words of a certain length in turn, in each the music stops. Musicians are on stage to play a tune with regular breaks, with the pace of the tune increasing as the game progresses. The length of the words to be named also changes with each round of the game, as contestants are eliminated.', '00110_musical_words.jpg', '00110_musical_words.jpg'),
(173, '|108|', 1, '|3|6|11|13|', 4, 'Persuade animals to stand on the mat', 'In this task the contestants have to persuade animals to stand on a mat, so that there are a given number of legs upon it.|The animals may be birds or dogs and, in two cases, one of the contestants has had to deal with a different animal to the others, due to outbreaks of avian flu.', '00108_persuade_three_animals_to_stand_on_the_mat.jpg', '00108_persuade_three_animals_to_stand_on_the_mat.jpg'),
(174, '|103|', 1, '|3|11|', 2, 'Put an egg in an egg cup without touching either', 'In this task the contestants have to place an egg in an egg cup without touching either. A variety of items are provided, which may be used to move the egg. A time penalty is imposed on any contestants who choose to use the same items.', '00103_put_an_egg_in_an_egg_cup_without_touching_either.jpg', '00103_put_an_egg_in_an_egg_cup_without_touching_either.jpg'),
(175, '|42|', 1, '|3|5|', 2, 'Pack a suitcase', 'In this live studio task the contestants are instructed to pack a variety of supplied holiday-related items into a suitcase within a limited timeframe. Any items which cannot be packed must be worn by the contestant.', '00042_pack_for_a_holiday.jpg', '00042_pack_for_a_holiday.jpg'),
(176, '|75|', 1, '|3|4|9|13|', 4, 'Burst all of the balloons', 'In this task the contestants are instructed to pop a large quantity of balloons as quickly as possible. The contestants’ time begins once they have popped the first balloon. In some versions of the task the balloons are arranged on a washing line to represent a secret message in Morse code, which provides them with a way to win the task without popping every balloon.', '00075_pop_the_balloons.jpg', '00075_pop_the_balloons.jpg'),
(177, '|139|', 1, '|3|9|', 2, 'Open the jar of mayonnaise', 'In this task the contestants have to open a jar of mayonnaise as quickly as possible. To make things more difficult, the jar is smeared with petroleum jelly or mayonnaise.', '00139_open_the_jar_of_mayonnaise.jpg', '00139_open_the_jar_of_mayonnaise.jpg'),
(178, '|46|', 1, '|3|4|6|8|9|', 8, 'Find something or someone that looks like you', 'In this task the contestants have to find or photograph something (or someone) which closely resembles them.', '00046_a_photo_of_an_object_that_looks_like_you.jpg', '00046_a_photo_of_an_object_that_looks_like_you.jpg'),
(179, '|79|', 1, '|3|4|6|9|13|', 5, 'Create the best domino effect', 'In this task the contestants are instructed to create the best domino effect.', '00079_create_the_best_domino_rally.jpg', '00079_create_the_best_domino_rally.jpg'),
(180, '|68|', 1, '|3|9|13|', 3, 'Propel a pea along a red carpet', 'In this task the contestants are instructed to propel a pea along a red carpet from behind a velvet rope.', '00068_propel_a_pea_along_a_red_carpet.jpg', '00068_propel_a_pea_along_a_red_carpet.jpg'),
(181, '|111|', 1, '|3|', 1, 'Decant the beverage into another container', 'In this task - often used as a tie-breaker - the contestants are instructed to decant a bottled beverage from the top of an umpire\'s chair into another small-necked container on the ground.', '00111_decant_wine_from_one_bottle_to_another.jpg', '00111_decant_wine_from_one_bottle_to_another.jpg'),
(182, '|171|', 1, '|3|9|13|', 3, 'Put the largest thing inside a balloon', 'In this task the contestants are instructed to put the largest thing possible inside a balloon and inflate it to a certain size.', '00171_put_the_largest_thing_inside_a_balloon.jpg', '00171_put_the_largest_thing_inside_a_balloon.jpg'),
(183, '|224|', 1, '|3|12|', 2, 'Do something manly with a cardboard box', 'In this task the contestants are instructed to do something manly with a cardboard box.', '00224_do_something_manly_with_a_box.jpg', '00224_do_something_manly_with_a_box.jpg'),
(184, '|63|', 1, '|1|3|4|', 3, 'Make a stop-motion movie', 'In this task the contestants are instructed to make a stop-motion movie.', '00063_create_a_stop_motion_film_starring_a_potato.jpg', '00063_create_a_stop_motion_film_starring_a_potato.jpg'),
(185, '|45|', 1, '|3|13|', 2, 'Make a video for a nursery rhyme', 'In this task the contestants are instructed to create a video for a children\'s nursery rhyme.', '00045_create_a_nursery_rhyme_video.jpg', '00045_create_a_nursery_rhyme_video.jpg'),
(186, '|135|', 1, '|3|5|11|13|', 4, 'Hide from the Taskmaster\'s assistant', 'In this task the contestants have to hide from the Taskmaster\'s assistant, in a game of hide-and-seek.', '00135_hide_from_alex.jpg', '00135_hide_from_alex.jpg'),
(187, '|1021|', 1, '|1|3|4|9|', 4, 'Pop the bubble wrap', 'In this task the contestants are instructed to pop as much of a roll of bubble wrap as possible in a limited timeframe.|The rules usually state that the time doesn\'t start until the first bubble is popped, potentially giving the contestants as much time as they would like to prepare.', '00860_pop_the_most_bubbles.jpg', '00860_pop_the_most_bubbles.jpg'),
(188, '|215|', 1, '|3|', 1, 'Take a picture of people holding eggs', 'In this task the contestants are instructed to take a picture of as many people holdings eggs as possible.|The contestants typically have many weeks between the assignment of the task and the reveal of their attempts in the studio.', '00215_take_a_picture_of_people_holding_eggs.jpg', '00215_take_a_picture_of_people_holding_eggs.jpg'),
(189, '|241|', 1, '|3|9|', 4, 'Predict how many words you can list in a category', 'In this live studio task, the contestants have to first predict how many words they think they might be able to list in 10 seconds in an as-yet-unknown category.|They then have to correctly list that number of words in their randomly assigned category.', '00241_predict_how_many_correct_answers_you_can_give.jpg', '00241_predict_how_many_correct_answers_you_can_give.jpg'),
(190, '|252|', 1, '|3|11|13|', 3, 'Stick something to the correct body parts', 'In this live studio task, the contestants are instructed to place adhesive plasters, or stickers, on the body parts which fall in the middle, alphabetically of lists of three parts.|Those who are slowest or who put a plaster or sticker on an incorrect body part are eliminated until just one contestant remains.', '00252_stick_plasters_to_the_correct_body_parts.jpg', '00252_stick_plasters_to_the_correct_body_parts.jpg'),
(191, '|168|', 1, '|3|9|11|13|', 5, 'The Taskmaster says...', 'In this Taskmaster version of the kids\' game Simon Says, the contestant must follow the instructions given by the Taskmaster, but ignore those given by their assistant.|To complicate matters, the contestants must do this while standing on one foot, with the other - adorned with needles - hovering over a balloon on the ground.|Contestants who follow the wrong instructions or fail to follow the Taskmaster\'s instructions, and those who fail to keep their foot above the balloon or burst it, are eliminated, until just one remains.', '00168_simons_says_taskmaster_edition.jpg', '00168_simons_says_taskmaster_edition.jpg'),
(192, '|186|', 1, '|3|', 1, 'Vote for who should receive five points', 'In this task the contestants are instructed to vote for either themselves or one of their competitors to receive five points.|The catch is that if they vote for themselves and do not receive the most votes, they will actually lose points.', '00186_vote_for_who_should_receive_five_points.jpg', '00186_vote_for_who_should_receive_five_points.jpg'),
(193, '|199|', 1, '|3|9|', 2, 'The second longest T-word', 'In this live studio task the contestants have to write down a word beginning with \'T\'. The person who writes down the second-longest word wins the round.|In some versions, multiple rounds are used, with the winner of each getting to take a step down a short set of steps, and the person who writes the longest word having to skip a turn.|In these multi-round versions, there is usually also a list of secret bonus words which, if matched, allow the contestants to take a step down.|The winner in the multi-round versions is the first person to reach the bottom of the steps.', '00199_the_t_step_word_game.jpg', '00199_the_t_step_word_game.jpg'),
(194, '|200|', 1, '|1|3|4|6|9|11|13|', 10, 'Perform along with the Taskmaster theme tune', 'In this usually \'special\' (and pointless) task, one of the contestants is singled out to sing or dance along with the Taskmaster theme tune.|The video and audio of them doing so is then integrated into the title sequence of the episode.|However, there have also been several instances of a version of this task where the brief is given to all of the contestants, who are then actually awarded points for their efforts.', '00200_sing_along_to_the_taskmaster_theme_tune.jpg', '00200_sing_along_to_the_taskmaster_theme_tune.jpg'),
(195, '|204|', 1, '|3|11|', 2, 'Make a mess and then clean it up', 'In this task the contestants are instructed to make as much of a mess as possible and then clear it all up again within a limited timeframe.', '00204_make_a_mess_and_then_clean_it_up.jpg', '00204_make_a_mess_and_then_clean_it_up.jpg'),
(196, '|193|', 1, '|3|5|12|13|', 4, 'Write and perform a song about a stranger', 'In this task, usually set as a team task, the contestants are introduced to a stranger and have to find out as much as they can about them in a limited timeframe.|They then have to incorporate what they found out into an original song about the stranger, which they must perform in front of them.', '00193_write_and_perform_a_song_about_a_stranger.jpg', '00193_write_and_perform_a_song_about_a_stranger.jpg'),
(197, '|232|', 1, '|3|4|9|13|', 4, 'Remove the tablecloth from underneath the eggs', 'In this task the contestants are instructed to remove a tablecloth from underneath some eggs while breaking as few of them as possible.', '00232_pull_the_tablecloth_off_the_table.jpg', '00232_pull_the_tablecloth_off_the_table.jpg'),
(198, '|147|', 1, '|3|6|', 2, 'Give the Taskmaster\'s assistant a special cuddle', 'In this task the contestants are instructed to give the Taskmaster\'s assistant a special, or memorable, cuddle or hug.', '00147_give_alex_a_special_cuddle.jpg', '00147_give_alex_a_special_cuddle.jpg'),
(199, '|950|', 10, '|2|3|9|', 3, 'Gain the most weight', 'In this task the contestants are instructed to gain as much weight as possible within a limited timeframe.', '01298_gain_the_most_weight.jpg', '01298_gain_the_most_weight.jpg'),
(200, '|415|', 1, '|4|6|13|', 3, 'Read the Taskmaster\'s mind', 'In this live studio task the contestants are instructed to attempt to read the Taskmaster\'s mind and correctly guess which of two pictures they have selected, behind a screen.|The contestant who guesses correctly the most times wins.', '00415_horse_or_laminator.jpg', '00415_horse_or_laminator.jpg'),
(201, '|394|', 1, '|6|11|', 2, 'Break something apart and put it back together', 'In this task the contestants are instructed to break something up into as many pieces as possible, and then reassemble it to its original form.', '00394_break_something_and_put_it_back_together.jpg', '00394_break_something_and_put_it_back_together.jpg'),
(202, '|164|', 1, '|3|6|', 2, 'Do something remarkable synchronised', 'In this team task the contestants are instructed to do something remarkable in synchrony.', '00164_do_something_remarkable_synchronised.jpg', '00164_do_something_remarkable_synchronised.jpg'),
(203, '|196|', 1, '|3|', 1, 'Choose between putting certain objects into certain receptacles', 'In this task the contestants are given a choice about the task they wish to complete, but all of the options involve getting some kind of objects (e.g. coconuts or exercise balls) into a specific receptacle (e.g. a bath or shopping trolley), with certain other restrictions in place.', '00196_throw_exercise_ball_into_bath_put_coconuts_in_trolley.jpg', '00196_throw_exercise_ball_into_bath_put_coconuts_in_trolley.jpg'),
(204, '|214|', 1, '|3|9|11|13|', 4, 'Keep the Taskmaster\'s assistant dry', 'In this task, the contestants (often in teams) are instructed to keep the Taskmaster\'s assistant dry when a shower above their head turns on in a short period of time.', '00214_keep_alex_dry.jpg', '00214_keep_alex_dry.jpg'),
(205, '|221|', 1, '|1|3|4|8|11|13|', 9, 'Identify the mystery flavours', 'In this task the contestants are instructed to deduce the flavours of several custom varieties of a specific type of food (e.g. crisps, baby food, dips).', '00221_identify_the_baby_food_flavours.jpg', '00221_identify_the_baby_food_flavours.jpg'),
(206, '|225|226|3411|', 1, '|6|11|12|', 3, 'Have as much fun as possible / Exactly recreate your fun', 'In this task, the contestants are instructed to have as much fun as possible within a given timeframe, and are then asked to exactly recreate their fun experience.|Sometimes these are scored as separate tasks, sometimes not.', '00225_have_the_most_fun_in_3_minutes.jpg', '00225_have_the_most_fun_in_3_minutes.jpg'),
(207, '|88|', 1, '|3|8|', 2, 'Have the most fun with a specific thing', 'In this special task, one of the contestants is singled out and instructed to have as much fun as possible with something (e.g. a bouncy castle, or a frisbee) for an entire hour.|Short clips of their forced enjoyment are typically shown throughout the episode.', '00088_have_fun_on_a_bouncy_castle.jpg', '00088_have_fun_on_a_bouncy_castle.jpg'),
(208, '|228|', 1, '|3|4|6|', 3, 'Extract the cash without spilling the beverage', 'In this task the contestants are instructed to remove one or more banknotes from beneath one or more glasses of beverage, without touching the glass(es) or spilling any of the beverage.', '00228_remove_the_5_note_from_under_the_pint.jpg', '00228_remove_the_5_note_from_under_the_pint.jpg'),
(209, '|263|', 1, '|3|6|12|13|', 4, 'Declare your love for the Taskmaster', 'In this task the contestants are instructed to express their love for the Taskmaster in a meaningful way.', '00263_declare_your_love_for_the_taskmaster.jpg', '00263_declare_your_love_for_the_taskmaster.jpg'),
(210, '|308|', 1, '|3|11|13|', 3, 'Follow the clues and then do what they spell', 'In this task the contestants have to follow a series of clues to collect all of the letters of a word which then tells them what they need to do to complete the task (usually \'scream\').', '00308_find_the_six_clues_and_do_what_they_spell.jpg', '00308_find_the_six_clues_and_do_what_they_spell.jpg'),
(211, '|278|', 1, '|3|4|6|9|13|', 5, 'Raise the Taskmaster\'s assistant\'s heart rate', 'In this task the contestants are instructed to raise the Taskmaster\'s assistant\'s heart rate as much as possible.', '00278_increase_alexs_heart_rate.jpg', '00278_increase_alexs_heart_rate.jpg'),
(212, '|305|', 1, '|3|9|13|', 3, 'Beat on the drum after exactly a given number of seconds', 'In this live studio task the contestants are instructed to approach and then beat on drum after exactly a given number of seconds (often 9.58 seconds, which is the world record for the 100m sprint).|A bonus point is usually assigned to the contestant with the most unique or flamboyant walk up to the drum.', '00305_hit_the_drum_at_exactly_9_58_seconds.jpg', '00305_hit_the_drum_at_exactly_9_58_seconds.jpg'),
(213, '|312|', 1, '|6|', 1, 'Put the most money in the floating bowl', 'In this task the contestants are instructed to place the most money in a small bowl which is floating inside a fishbowl, without sinking the bowl.', '00312_put_the_most_money_in_the_floating_bowl.jpg', '00312_put_the_most_money_in_the_floating_bowl.jpg'),
(214, '|358|', 1, '|3|11|13|', 3, 'Roll a toilet roll, and then use it to retrieve something', 'In this live studio task the contestants are instructed to roll a toilet roll past a certain line on a platform on the stage.|Anyone whose toilet roll does not make it past the first line, or falls off the platform, is eliminated.|An object (either one of their shoes, or a glass of water) is then placed on the toilet paper of any remaining contestants, and they have to retrieve it as quickly as possible by pulling on the paper, without tearing it.', '00358_roll_your_toilet_roll_and_retrieve_your_show.jpg', '00358_roll_your_toilet_roll_and_retrieve_your_show.jpg'),
(215, '|327|', 1, '|1|3|4|6|8|14|', 7, 'Complete an objective while trying to avoid being spotted by the Taskmaster\'s assistant', 'In this task, the contestants have to achieve a goal while trying to avoid being seen by the Taskmaster\'s assistant, who alternatively surveys the scene and looks away, or closes their eyes, on a predictable schedule.|In some cases, this is mechanically controlled (e.g. buy having the assistant sit in a hunting blind which is on a turntable). In other cases, the assistant must avert their gaze on a set schedule, and a sound cue is used to let the contestant know when it is safe to move.|In most versions, the contestant\'s attempt ends as soon as the assistant spots them. However, there have now been a couple of instances of a task variation where they instead must return to a given starting point, and try again, and one instance where the Taskmaster\'s assistant must correctly identify the colour of a cape they are wearing before they are disqualified.', '00327_sneak_up_on_alex.jpg', '00327_sneak_up_on_alex.jpg'),
(216, '|354|', 1, '|3|11|', 2, 'Completely hide yourself inside of something specific', 'In this task the contestants are instructed to completely hide themselves inside of something specific (e.g. a telephone box, or a Volvo).', '00354_conceal_yourself_inside_a_phone_box.jpg', '00354_conceal_yourself_inside_a_phone_box.jpg'),
(217, '|343|', 1, '|6|', 1, 'Entertain a toddler', 'In this task the contestants are instructed to create something which will entertain a toddler.', '00343_make_the_best_thing_to_engage_a_toddler.jpg', '00343_make_the_best_thing_to_engage_a_toddler.jpg'),
(218, '|395|', 1, '|6|11|', 2, 'Fill a glass with water while blindfolded', 'In this live studio task the contestants have to fill a glass with as much water as possible while blindfolded, using small containers of various types of fluid which are attached to their body.', '00395_fill_a_pint_glass_with_water.jpg', '00395_fill_a_pint_glass_with_water.jpg'),
(219, '|143|', 1, '|3|11|', 2, 'Strike your chosen item as far as possible with your chosen club', 'In this task the contestants are instructed to select an item to hit, and a club to hit it with, and then have to strike the item as far as possible.', '00143_strike_an_item_the_furthest.jpg', '00143_strike_an_item_the_furthest.jpg'),
(220, '|1014|', 1, '|1|3|6|9|12|13|', 6, 'Write a short story while running', 'In this task the contestants are instructed to write a short story while running a short distance.', '00271_wrote_a_ten_word_story_while_running.jpg', '00271_wrote_a_ten_word_story_while_running.jpg'),
(221, '|335|', 1, '|3|4|9|11|13|', 8, 'Think, do, and nominate', 'In this live studio task, the contestants must complete a quick mental task (e.g. name something in a category, or solve a calculation), complete a short physical task (e.g. eat a small item of food, press a button, or ring a bell), and name another contestant, all without hesitating too long.|In some versions they must set a new mental task for the next contestant to complete, before naming them.|If they hesitate for too long, give an incorrect answer, perform the actions out of order, set an invalid mental task, or repeat something already named, they are eliminated.', '00335_name_a_bird_eat_a_grape_name_a_contestant.jpg', '00335_name_a_bird_eat_a_grape_name_a_contestant.jpg'),
(222, '|286|', 1, '|3|11|', 2, 'Get dressed while wearing handcuffs', 'In this live studio task the contestants are instructed to correctly put on as many items of clothing as possible while handcuffed.', '00286_wear_the_most_clothing_while_handcuffed.jpg', '00286_wear_the_most_clothing_while_handcuffed.jpg'),
(223, '|945|', 10, '|1|3|6|', 3, 'Cheer up the miserable person', 'In this task the contestants are instructed to cheer up an individual who is perceived to be miserable (e.g. a traffic warden, or a TV critic).', '00291_cheer_up_the_traffic_warden.jpg', '00291_cheer_up_the_traffic_warden.jpg'),
(224, '|345|', 1, '|3|', 1, 'Throw a frying pan into a hoop', 'In this live studio task the contestants are instructed to throw a frying pan into one of three differently-sized hoops.|The smaller the hoop they choose, the more chances they get to throw the frying pan.|They also get to choose how far away to place the hoop, with the person who successfully lands their frying pan in their hoop from the farthest distance winning the task.', '00345_throw_a_frying_pan_into_a_hoop.jpg', '00345_throw_a_frying_pan_into_a_hoop.jpg'),
(225, '|1141|', 3, '|1|6|11|', 3, 'Make the best marble run', 'In this task the contestants are instructed to build the best and longest-lasting marble run for a given spherical object.', '01141_build_an_impressive_lime_path.jpg', '01141_build_an_impressive_lime_path.jpg'),
(226, '|763|', 4, '|1|3|', 2, 'Project the heaviest thing the greatest distance', 'In this task the contestants are instructed to project the heaviest thing the greatest distance possible.|Their scores are based on the result of multiplying the weight of the object by the distance it was projected.', '00763_throw_something_heavy_as_far_as_possible.jpg', '00763_throw_something_heavy_as_far_as_possible.jpg'),
(227, '|434|', 1, '|6|8|', 2, 'Make the biggest thing disappear', 'In this task the contestants are instructed to make something as large as possible completely disappear.', '00434_make_a_large_object_vanish.jpg', '00434_make_a_large_object_vanish.jpg'),
(228, '|334|', 1, '|3|6|11|13|', 4, 'Travel the furthest while making a continuous sound', 'In this task the contestants are instructed to travel as far as possible while making a single, continuous sound with their mouth.', '00334_run_the_furthest_while_making_a_continuous_noise.jpg', '00334_run_the_furthest_while_making_a_continuous_noise.jpg'),
(229, '|18|', 1, '|1|7|', 2, 'Guess someone\'s age in an unconventional unit of time', 'In this task - which is typically used as a tie-breaker - the contestants must guess someone\'s age in a unconventional unit of time (e.g. minutes, or Sundays).', '00018_guess_franks_age_in_minutes.jpg', '00018_guess_franks_age_in_minutes.jpg'),
(230, '|1003|', 3, '|4|6|8|', 3, 'Perform a magic trick', 'In this task the contestants are instructed to perform a magic trick.', '01003_impress_a_stranger_with_a_magic_trick.jpg', '01003_impress_a_stranger_with_a_magic_trick.jpg'),
(231, '|429|', 1, '|3|6|9|11|12|13|', 6, 'Solve all the tasks in any order', 'In this task the contestants are presented with several task briefs, which they may complete in any order.|The catch is that some of the tasks will make some of the other tasks much harder to complete, depending on the order in which they are performed.', '00429_complete_the_seven_tasks_in_any_order.jpg', '00429_complete_the_seven_tasks_in_any_order.jpg'),
(232, '|244|', 1, '|1|', 1, 'Reproduce a scene based only on touch', 'In this task the contestants must draw or sculpt a scene which they cannot see, but can feel with their hands.', '00244_draw_the_contents_of_the_box.jpg', '00244_draw_the_contents_of_the_box.jpg'),
(233, '|1062|', 3, '|4|6|9|', 3, 'Unravel as much string as possible', 'In this task the contestants are instructed to unravel as much string or yarn as possible in a limited timeframe.', '01062_unravel_the_reel_of_yarn.jpg', '01062_unravel_the_reel_of_yarn.jpg'),
(234, '|8|', 1, '|3|11|', 2, 'Greet people and ask them their ages', 'In this task, the contestants are instructed to accost members of the public and ask them their age, in pursuit of a specific goal (e.g. finding someone of a specific age, or reaching a goal with the sum of their ages).', '00008_high_five_a_55_year_old.jpg', '00008_high_five_a_55_year_old.jpg'),
(235, '|351|', 1, '|3|6|', 2, 'Herd the ping pong balls into a pen', 'In this task the contestants are instructed to herd a group of ping pong balls from one pen to another.|The catch is that they are only allowed to touch the balls with specific things.', '00351_herd_the_ping_pong_balls_into_a_pen.jpg', '00351_herd_the_ping_pong_balls_into_a_pen.jpg'),
(236, '|372|373|3412|', 1, '|3|11|', 2, 'Make yourselves look like one person / Complete tasks as one person', 'In this team task the contestants are instructed to make themselves appear to be just one person, and are then asked to complete one or more physical tasks as one.|Sometimes the two parts of the task are scored separately, sometimes they are a single task.', '00372_make_yourselves_look_like_one_person.jpg', '00372_make_yourselves_look_like_one_person.jpg'),
(237, '|977|', 3, '|3|6|8|', 3, 'Squirt a specific liquid as far as possible', 'In this task the contestants are instructed to squirt or splash a specific liquid as far as possible along a surface (e.g. a roll of paper or a plastic tarpaulin) from a given start point.', '00977_get_ketchup_as_far_along_a_roll_of_paper_as_possible.jpg', '00977_get_ketchup_as_far_along_a_roll_of_paper_as_possible.jpg'),
(238, '|160|', 1, '|3|4|9|11|13|', 5, 'Eat one item, balance one item, throw one item', 'In this task the contestants are given three mini tasks to complete (eat one item, balance one item, throw one item), and three items with which they may complete them.', '00160_eat_one_item_balance_one_item_throw_one_item.jpg', '00160_eat_one_item_balance_one_item_throw_one_item.jpg'),
(239, '|137|', 1, '|3|6|11|12|', 4, 'Invent a new greeting', 'In this task the contestants are instructed to develop a new means of greeting someone, and demonstrate it with the Taskmaster\'s assistant.', '00137_unveil_a_new_handshake.jpg', '00137_unveil_a_new_handshake.jpg'),
(240, '|11|', 1, '|2|3|11|13|', 4, 'Unshackle yourself and achieve a goal', 'In this live studio task the contestants are chained to their seats, and have to solve a combination lock to free themselves, before achieving another simple goal (such as sprinting one metre, or eating a cupcake).|Clues are provided by the Taskmaster\'s assistant to help them along the way.', '00011_unshackle_yourself.jpg', '00011_unshackle_yourself.jpg'),
(241, '|755|', 4, '|3|9|', 2, 'Catch some objects in your very tall hat', 'In this live task, the contestants are instructed to catch as many objects (e.g. tomatoes or balls) as possible in their tall, topless hats.|Although very similar to the \'Catch some objects in a hat while wearing a belt\' task, this one differs in that the contestants\' arms are not strapped to their sides to make throwing more difficult, but the hats are much taller instead.', '00755_catch_tomatoes_in_your_chef_hat.jpg', '00755_catch_tomatoes_in_your_chef_hat.jpg'),
(242, '|56|', 1, '|2|3|13|', 3, 'Rescue the cat from the tree', 'In this task the contestants are instructed to rescue a stuffed toy cat from a tree.', '00056_rescue_the_cat.jpg', '00056_rescue_the_cat.jpg'),
(243, '|501|', 8, '|1|3|6|9|11|13|', 6, 'Strike poses to represent your choices in some categories', 'In this live studio task the contestants are instructed to write down examples of things meeting a number of categories (e.g. a sport or hobby, an animal, a colour, or a celebrity) and then strike poses to represent their choices.|In one adaptation, the contestants have to strike a single pose representing two different categories simultaneously.|The contestants earn points if the Taskmaster is able to correctly guess what their poses represent.', '00501_strike_poses_to_represent_a_sport_animal_and_colour.jpg', '00501_strike_poses_to_represent_a_sport_animal_and_colour.jpg'),
(244, '|1136|', 3, '|1|6|11|', 3, 'Pop the balloon', 'In this task the contestants are instructed to pop a balloon from a distance using items which they can buy from the Taskmaster\'s assistant with time. The contestant who pops the balloon fastest wins.', '01136_pop_the_balloon.jpg', '01136_pop_the_balloon.jpg'),
(245, '|71|', 1, '|4|', 1, 'The heaviest thing that fits in a shoebox', 'In this prize task, the contestants are instructed to bring in the heaviest thing that fits inside a shoebox.', '00071_the_heaviest_shoebox_sized_item.jpg', '00071_the_heaviest_shoebox_sized_item.jpg'),
(246, '|447|', 1, '|6|11|13|', 3, 'Catapult a shoe into a bathtub', 'In this task the contestants are instructed to catapult a shoe into a bathtub. They have to build their own catapult and fire it with only their feet. The brief states only that the catapult must be built on the red mat, so it is technically acceptable to move the catapult after construction.', '00447_catapult_a_shoe_into_a_bath.jpg', '00447_catapult_a_shoe_into_a_bath.jpg'),
(247, '|730|', 1, '|6|9|11|13|', 4, 'Stack your buckets so that they are taller than you', 'In this live studio task, the contestants are instructed to stack buckets to a greater height than themselves, place a beanbag on top, and then put their hands on their hips. They are not permitted to leave their designated spots on the stage, but are provided with several more beanbags than they actually need (giving them the option of sabotaging other contestants\' efforts).', '00730_stack_your_buckets.jpg', '00730_stack_your_buckets.jpg'),
(248, '|1576|', 4, '|3|6|', 3, 'Fill the bathtub with water from the box', 'In this task the contestants are told that the water supply from a box will be turned on for a limited period after a given time, and they have to prepare to move as much of the water as possible to a nearby bathtub.', '01576_fill_the_bathtub_with_water_from_the_box.jpg', '01576_fill_the_bathtub_with_water_from_the_box.jpg'),
(249, '|461|', 1, '|6|9|11|13|', 4, 'Make something as quietly as possible', 'In this task the contestants are instructed to make something (e.g. a new cocktail, or a wooden bird house) as quietly as possible.|Each time they make a sound above a certain decibel level, they have to complete a forfeit (e.g. discard their drink in a bucket, shout a specific phrase, and begin again; or make and identify a unique bird call).', '00461_silently_make_a_cocktail.jpg', '00461_silently_make_a_cocktail.jpg'),
(250, '|493|', 8, '|3|6|9|', 3, 'Keep a balloon in the air', 'In this task the contestants are instructed to keep a balloon in the air for the longest. They may only touch the balloon with unique objects.', '00493_keep_a_balloon_in_the_air_the_longest.jpg', '00493_keep_a_balloon_in_the_air_the_longest.jpg'),
(251, '|464|', 1, '|6|13|', 2, 'Draw animals using straight lines', 'In this live studio task, the contestants are instructed to convey an animal to another person by drawing just three straight lines at a time. The task has been used as both a team and a solo live task.', '00464_draw_animals_using_three_straight_lines_at_a_time.jpg', '00464_draw_animals_using_three_straight_lines_at_a_time.jpg'),
(252, '|1044|', 3, '|4|', 1, 'Build a boat for the Taskmaster\'s assistant', 'In this task the contestants are instructed to construct a boat which will safely support the Taskmaster\'s assistant in water.', '01044_build_a_boat_to_carry_david_across_the_pond.jpg', '01044_build_a_boat_to_carry_david_across_the_pond.jpg'),
(253, '|934|', 10, '|1|2|8|', 3, 'Give money to the Taskmaster or their assistant', 'In this task the contestants are instructed to give money to either the Taskmaster or their assistant, with the person who gives the greatest amount of money winning.|The task may explicitly ask the contestants to transfer money to an account, or the nature of the transaction may be left open to interpretation.', '01296_transfer_money_to_gerts_bank_account.jpg', '01296_transfer_money_to_gerts_bank_account.jpg'),
(254, '|1041|', 3, '|6|11|', 2, 'Hide the coconut inside the box', 'In this task the contestants are instructed to hide a coconut inside a large wooden frame set out on the ground, and the Taskmaster\'s assistant has to try to find it as quickly as possible.', '01041_hide_the_coconut_inside_the_box.jpg', '01041_hide_the_coconut_inside_the_box.jpg'),
(255, '|1608|', 4, '|6|', 1, 'Build a birdhouse', 'In this task the contestants are provided with a plank of wood and instructed to build a birdhouse. The catch is that they will be disqualified if they use any of the same tools as any of the other contestants.', '01608_build_a_birdhouse.jpg', '01608_build_a_birdhouse.jpg'),
(256, '|1602|', 4, '|6|', 1, 'Convince a foreigner that you are the most famous contestant.', 'In this task the contestants are introduced to a foreigner who is not familiar with the culture of the host country, and are instructed to convince that person that they are the most famous of the contestants in the current series.', '01602_convince_a_swede_that_you_are_the_most_famous_contestant.jpg', '01602_convince_a_swede_that_you_are_the_most_famous_contestant.jpg'),
(257, '|485|', 1, '|6|13|', 2, 'Balance all the mints or biscuits on a spaghetti bridge', 'In this live studio task the contestants must, while wearing mittens, make a bridge from spaghetti between two coconuts, and then balance either all the ring-shaped mints, or all the ring-shaped biscuits, on the bridge.', '00485_balance_all_the_mints_or_biscuits_on_a_spaghetti_bridge.jpg', '00485_balance_all_the_mints_or_biscuits_on_a_spaghetti_bridge.jpg'),
(258, '|1212|', 8, '|4|14|', 2, 'Make the loudest noise', 'In this task the contestants are instructed to make the loudest noise.', '01212_make_the_loudest_noise.jpg', '01212_make_the_loudest_noise.jpg'),
(260, '|407|', 1, '|6|11|', 2, 'Make a body part abnormally long', 'In this task the contestants are instructed to make a body part abnormally long.', '00407_make_a_part_of_your_body_abnormally_long.jpg', '00407_make_a_part_of_your_body_abnormally_long.jpg'),
(261, '|1213|', 8, '|3|4|6|', 3, 'Slice your food item in twain', 'In this live studio task the contestants are instructed to select a tool and then a food item, and have to attempt to divide the food item exactly in half with the tool.', '01213_slice_your_snack_in_twain.jpg', '01213_slice_your_snack_in_twain.jpg'),
(262, '|467|', 1, '|6|', 1, 'Communicate something through reversed audio', 'In this task, which has been used in both team and split task formats, the contestants have to communicate something via reversed audio.|In the team version, one contestant tried to communicate with their teammate(s), and in the split task format one contestant has to attempt to understand all the others\' audio messages.', '00467_communicate_the_safe_contents_via_reversed_audio.jpg', '00467_communicate_the_safe_contents_via_reversed_audio.jpg'),
(263, '|956|', 1, '|3|6|13|', 3, 'One leg or two?', 'In this live studio task the Taskmaster has to guess whether the contestants are standing on one leg or two, behind a curtain covering their legs.', '00956_one_leg_or_two.jpg', '00956_one_leg_or_two.jpg'),
(264, '|891|', 3, '|9|', 1, 'Eat the ice lolly', 'In this task the contestants are instructed to eat an ice lolly as quickly as possible.', '00891_eat_the_lollipop.jpg', '00891_eat_the_lollipop.jpg'),
(265, '|19|', 1, '|2|4|14|', 3, 'The most beautiful item', 'In this prize task the contestants are instructed to bring in the most beautiful item.', '00019_most_beautiful_item.jpg', '00019_most_beautiful_item.jpg'),
(266, '|12|', 1, '|2|9|13|', 3, 'The most meaningful item.', 'In this prize task the contestants are instructed to bring in the most meaningful item.', '00012_most_meaningful_item.jpg', '00012_most_meaningful_item.jpg'),
(267, '|38|', 1, '|2|9|12|13|', 4, 'The most important document', 'In this prize task the contestants are instructed to bring in the most important document.', '00038_the_most_important_document.jpg', '00038_the_most_important_document.jpg'),
(268, '|1096|', 3, '|6|', 1, 'Rotate the Taskmaster\'s assistant', 'In this task the contestants are instructed to rotate the Taskmaster\'s assistant as many times as possible in a given timeframe.', '01096_rotate_david.jpg', '01096_rotate_david.jpg'),
(269, '|1165|', 3, '|6|', 1, 'Land a ball in a hat after three bounces', 'In this task the contestants are instructed to bounce a ball off of three different objects before catching it in a hat.|The ball they have to use is the first one they touch, from those presented to them.', '01165_land_a_ball_in_a_hat_after_three_bounces.jpg', '01165_land_a_ball_in_a_hat_after_three_bounces.jpg'),
(270, '|480|', 1, '|4|6|11|12|', 4, 'Draw the monster described by the Taskmaster', 'In this live studio task, the contestants are instructed to draw a monster as it is described by the Taskmaster.|The idea for this task was devised by one of <a href=\"/person.php?id=175\">Lee Mack</a>\'s children.', '00480_draw_the_monster_described_by_the_taskmaster.jpg', '00480_draw_the_monster_described_by_the_taskmaster.jpg'),
(271, '|433|', 1, '|4|6|11|', 3, 'Relocate a tray full of drinks', 'In this task, the aim is to relocate a tray of very full drinks from one location to another as quickly as possible.|This task is complicated by additional rules, such as: having to always carry a teddy bear with them (the size of which may be inversely determined according to how well they did in an initial task, asking them to do something such as knock a coconut off a pole, or fell a stack of cans); not being allowed to step on a certain area of the ground (such as a lawn or patio); not spilling any of the drinks; or even completing a task during each trip, before crossing a certain line.', '00433_move_all_the_drinks_while_carrying_a_teddy_bear.jpg', '00433_move_all_the_drinks_while_carrying_a_teddy_bear.jpg'),
(272, '|856|', 1, '|3|6|11|13|', 4, 'Reach a location without triggering an alarm', 'In this task the contestants are instructed to reach a specific location within a grid or following a course of stepping stones.|Whenever their actions cause an alarm to sound, they must return to the beginning and start again.|The contestants do not know what causes the alarm to sound, and must attempt to try to figure this out.', '00856_get_out_of_the_front_gate.jpg', '00856_get_out_of_the_front_gate.jpg'),
(273, '|1591|', 4, '|6|', 1, 'Decorate the rotating cake', 'In this task the contestants are instructed to decorate a cake which is rotating at quite a high speed on the end of an arm attached to a turntable.', '01591_decorate_the_rotating_cake.jpg', '01591_decorate_the_rotating_cake.jpg'),
(274, '|845|', 1, '|3|6|11|13|', 4, 'Slap and tong', 'In this live studio task, the contestants are divided into teams and must play rounds of \'slap and tong\' against each other.|In this game, one contestant must attempt to grab a marshmallow from a table while their opponent must attempt to slap the marshmallow off the table.|The \'slapper\' may only reach across the table once the tong-wielder\'s hand is over the table.', '00845_slap_and_tong.jpg', '00845_slap_and_tong.jpg'),
(275, '|516|', 8, '|1|3|4|6|9|13|', 8, 'Do something before the object pops', 'In this live studio task the contestants are instructed to complete an action (e.g. stand up, or ring a bell) before a given object (e.g. a toaster) pops up.|The task may take place over a single round, or multiple rounds.', '00516_pop_up_before_the_toast_does.jpg', '00516_pop_up_before_the_toast_does.jpg'),
(276, '|1137|', 3, '|1|6|11|13|', 4, 'Do the right thing', 'In this task the contestants are given a wordy task brief which includes a series of compound negative clauses about whether they should or should not ring a bell, and they have to determine what they are actually being told to do.|In some versions, the contestants are given a minor physical task to do while they make their decision, both as a distraction and in order to slow them down.', '01137_do_the_opposite_of_the_instructions.jpg', '01137_do_the_opposite_of_the_instructions.jpg'),
(277, '|1066|', 3, '|9|', 1, 'Make the jumper as long as possible', 'In this task the contestants are instructed to make a jumper as long as possible. ', '01066_make_the_jumper_as_long_as_possible.jpg', '01066_make_the_jumper_as_long_as_possible.jpg'),
(278, '|87|', 1, '|3|4|9|11|', 4, 'Cover yourself in sticky notes', 'In this live studio task the contestants are blindfolded and have to attach as many sticky notes to themselves as possible within a limited timeframe.', '00087_cover_yourself_in_sticky_notes.jpg', '00087_cover_yourself_in_sticky_notes.jpg'),
(279, '|77|', 1, '|9|11|13|', 3, 'The best battery-operated item', 'In this prize task the contestants are instructed to bring in the best battery-operated item.', '00077_the_best_battery_powered_object.jpg', '00077_the_best_battery_powered_object.jpg'),
(280, '|1436|', 9, '|1|11|13|', 3, 'Make the sauna stones hiss', 'In this task the contestants are instructed to make a sauna stove/sauna stones hiss from as far away as possible.', '01436_make_the_sauna_stove_hiss.jpg', '01436_make_the_sauna_stove_hiss.jpg'),
(281, '|911|', 3, '|9|', 1, 'Cut a string to the contestants’ total height', 'In this live studio task the contestants are instructed to cut a piece of string to a length equivalent to the total height of all of the contestants.', '00911_cut_a_string_to_the_contestants_total_height.jpg', '00911_cut_a_string_to_the_contestants_total_height.jpg'),
(282, '|176|', 1, '|9|13|', 2, 'The best home-made item', 'In this prize task the contestants are asked to bring in the best home-made item.', '00176_the_best_homemade_item.jpg', '00176_the_best_homemade_item.jpg'),
(283, '|1441|', 9, '|1|3|4|', 3, 'Break open a coconut in a unique way', 'In this task the contestants are instructed to either break open a coconut, or consume some of the contents of the coconut, using a method of their choice.|If they use the same method to break open or extract contents of the coconut, they may receive a time penalty, or be disqualified.', '01441_break_open_a_coconut.jpg', '01441_break_open_a_coconut.jpg'),
(284, '|112|', 1, '|9|11|13|', 3, 'The most surprising picture of yourself', 'In this prize task the contestants are instructed to bring in the most surprising picture of themselves.', '00112_the_most_surprising_photo_of_yourself.jpg', '00112_the_most_surprising_photo_of_yourself.jpg'),
(285, '|212|', 1, '|9|13|', 2, 'The best non-living hairy thing', 'In this prize task the contestants are instructed to bring in the best non-living hairy thing.', '00212_the_best_non_living_hairy_thing.jpg', '00212_the_best_non_living_hairy_thing.jpg'),
(286, '|31|', 1, '|6|9|', 2, 'Make someone blush', 'In this task the contestants are instructed to make a specific stranger blush as much as possible.', '00031_make_a_swedish_person_blush.jpg', '00031_make_a_swedish_person_blush.jpg'),
(287, '|1178|', 3, '|1|', 1, 'Find the soldier with hindsight', 'In this task the contestants wear a helmet which only allows them to see what is behind them, and have to find a camouflaged soldier by listening out for his voice as he calls their name.', '01178_find_the_sergeant_with_hindsight.jpg', '01178_find_the_sergeant_with_hindsight.jpg'),
(288, '|94|', 1, '|6|9|', 2, 'The most interesting vegetable autograph', 'In this prize task the contestants are instructed to bring in the most interesting autograph on a vegetable.', '00094_the_most_unusual_vegetable_autograph.jpg', '00094_the_most_unusual_vegetable_autograph.jpg'),
(289, '|157|', 1, '|1|9|13|', 3, 'The proudest item', 'In this prize task the contestants are instructed to bring in an item of which they are the most proud.', '00157_the_proudest_item.jpg', '00157_the_proudest_item.jpg'),
(290, '|151|', 1, '|3|', 1, 'The hippest headwear', 'In this prize task the contestants are asked to bring in the hippest item of headwear.', '00151_the_hippest_headwear.jpg', '00151_the_hippest_headwear.jpg'),
(291, '|301|', 1, '|3|4|11|', 3, 'Throw something into the receptacle behind the barrier', 'In this task the contestants have to try to throw something into a receptacle which they cannot see because it is on the other side of a fence, wall, or hedge.', '00301_throw_something_into_the_bin_behind_the_fence.jpg', '00301_throw_something_into_the_bin_behind_the_fence.jpg'),
(292, '|265|', 1, '|12|', 1, 'The thing most people want to touch', 'In this prize task the contestants are instructed to bring in the thing that most people want to touch.', '00265_the_thing_most_people_want_to_touch.jpg', '00265_the_thing_most_people_want_to_touch.jpg'),
(293, '|844|', 1, '|6|11|12|', 3, 'Sort the objects with your face', 'In this task the contestants are blindfolded and instructed to sort a group of objects on a table using only their face.', '00844_arrange_the_objects_by_their_number_of_sides.jpg', '00844_arrange_the_objects_by_their_number_of_sides.jpg'),
(294, '|1499|', 3, '|1|6|', 2, 'Duel with the Taskmaster\'s assistant', 'In this task the contestants are instructed to come up with a duel, and then duel against the Taskmaster\'s assistant.|The most even and exciting duel wins.', '01499_duel_with_david.jpg', '01499_duel_with_david.jpg'),
(295, '|383|', 1, '|3|6|8|', 3, 'Make the most dramatic entrance or exit', 'In this task the contestants are instructed to make the most dramatic entrance or exit.', '00383_make_the_most_dramatic_entrance.jpg', '00383_make_the_most_dramatic_entrance.jpg'),
(296, '|387|', 1, '|3|6|11|', 3, 'Draw a portrait of the Taskmaster across a flipchart', 'In this task the contestants are instructed to draw a portrait of the Taskmaster across 16 pages of a flipchart pad, without removing the pages.|The pages are then removed and arranged according to a numbered plan presented on the front of the pad.', '00387_draw_a_portrait_of_the_taskmaster_on_16_a1_sheets.jpg', '00387_draw_a_portrait_of_the_taskmaster_on_16_a1_sheets.jpg'),
(297, '|446|', 1, '|3|9|11|12|', 4, 'Put the most spaghetti in a citrus fruit', 'In this task the contestants have to put as much spaghetti as possible in a grapefruit or orange.|In some versions, the task starts out in a lit room and then the lights are turned out part-way through.|In other versions, the entire task takes place in a darkened room.', '00446_put_the_most_spaghetti_in_a_grapefruit.jpg', '00446_put_the_most_spaghetti_in_a_grapefruit.jpg'),
(298, '|452|', 1, '|3|6|', 2, 'Drop a water balloon as far as possible without it bursting', 'In this task the contestants are instructed to drop a water balloon as far as possible from a lift device without it bursting.', '00452_drop_a_water_balloon_from_the_greatest_height_without_it_bursting.jpg', '00452_drop_a_water_balloon_from_the_greatest_height_without_it_bursting.jpg'),
(299, '|1029|', 1, '|3|', 1, 'Erect a tent while simulating video controls', 'In this team task the contestants have to successfully erect a tent while adhering to rules about working under the effects of video controls such as fast-forward, slow-motion, rewind, and pause.', '01533_erect_the_tent_while_rewinding_fast_forwarding_and_pausing.jpg', '01533_erect_the_tent_while_rewinding_fast_forwarding_and_pausing.jpg'),
(300, '|740|', 4, '|3|9|', 2, 'Put on a frozen shirt and tie', 'In this live task the contestants must put on a shirt and tie which have been frozen stiff.', '00740_put_on_a_frozen_shirt_and_tie.jpg', '00740_put_on_a_frozen_shirt_and_tie.jpg'),
(301, '|282|', 1, '|12|', 1, 'The most confusing thing', 'In this prize task, the contestants are instructed to bring in the most confusing thing.', '00282_the_most_confusing_thing.jpg', '00282_the_most_confusing_thing.jpg'),
(302, '|960|', 1, '|3|12|', 2, 'Appear as different as possible in four photos', 'In this task the contestants are instructed to appear as different as possible in four photographs.|The photos are taken by a camera which slowly rotates 360 degrees before each shot, giving them a limited amount of time to change.', '00960_appear_as_different_as_possible_in_four_photos.jpg', '00960_appear_as_different_as_possible_in_four_photos.jpg'),
(303, '|109|', 1, '|9|11|12|13|', 4, 'Transfer water from one fishbowl to another', 'In this task the contestants are provided with a range of generally useless items, and instructed to use them to transfer the water from one fishbowl to another, without moving the fishbowl.|A bar of chocolate is included amongst the items but, if the contestants eat any of the chocolate, they lose five points (as specified <em>clearly</em> on the back of the task brief).', '00109_transfer_water_from_one_fishbowl_to_another.jpg', '00109_transfer_water_from_one_fishbowl_to_another.jpg'),
(304, '|435|', 1, '|3|13|', 2, 'Get the most eggs in the pan', 'In this task the contestants are instructed to get as many eggs as possible from their position on a balcony into a frying pan balanced on top of a tower.', '00435_land_the_most_eggs_in_a_pan.jpg', '00435_land_the_most_eggs_in_a_pan.jpg'),
(305, '|469|', 1, '|3|4|9|11|12|13|', 6, 'Communicate things to the Taskmaster using only sounds', 'In this live studio task, the contestants have to communicate given items (e.g. animals, machines, foods, instruments) to the Taskmaster using only sounds, but no words or actions.|To help prevent the contestants from communicating via gestures, they may be instructed to hold an umbrella out in front of themselves with both hands, or be hidden from the Taskmaster\'s view by being behind a screen or behind the Taskmaster\'s back.|In some versions of the task, the contestants each communicate one animal per round, with the slowest communicator being eliminate each time, until there is just one contestant remaining.|In other versions, contestants are eliminated if the Taskmaster makes an incorrect guess at what they are trying to communicate, with the last one standing being named the winner.|In some versions, the contestants have a short amount of time to communicate as many items as possible, with the winner being the one who successfully communicates the most.', '00469_communicate_an_item_to_the_taskmaster_without_words_or_actions.jpg', '00469_communicate_an_item_to_the_taskmaster_without_words_or_actions.jpg'),
(306, '|376|', 1, '|3|4|11|13|', 4, 'Erase the eraser', 'In this task the contestants are instructed to either completely erase an eraser as quickly as possible, or to erase as much of an eraser as possible in a  limited timeframe.', '00376_completely_erase_the_eraser.jpg', '00376_completely_erase_the_eraser.jpg'),
(307, '|1030|', 1, '|3|', 1, 'Point due North', 'In this task the contestants are instructed to determine which direction is North, and point in that direction.', '01558_point_due_north.jpg', '01558_point_due_north.jpg'),
(308, '|1018|', 1, '|3|', 1, 'Put an increasing number of things between the rungs of a ladder', 'In this task the contestants are instructed to place an increasing number of different objects between the subsequent pairs of rungs of a ladder lying on the ground.', '01562_put_an_increasing_number_of_things_between_the_rungs_of_a_ladder.jpg', '01562_put_an_increasing_number_of_things_between_the_rungs_of_a_ladder.jpg'),
(309, '|1564|', 4, '|1|6|', 2, 'The best collection', 'In this prize task the contestants are instructed to bring in the best/greatest collection.', '01564_the_best_collection.jpg', '01564_the_best_collection.jpg'),
(310, '|1206|', 8, '|3|', 1, 'Perform an original Christmas song', 'In this task the contestants first have to choose a gift to unwrap, and they then have to write and perform an original Christmas song without using a specified set of common Christmas-related words, but incorporating the object found in their gift.', '01206_perform_an_original_christmas_song.jpg', '01206_perform_an_original_christmas_song.jpg'),
(311, '|1604|', 4, '|3|', 1, 'Find the smallest item', 'In this live studio task, the contestants must search the stage to find a given item (e.g. key, fish) hidden there.|The smallest version of the given item gives them the most points.', '01604_find_the_smallest_key.jpg', '01604_find_the_smallest_key.jpg'),
(312, '|1575|', 4, '|8|', 1, 'Something which looks edible but isn\'t', 'In this prize task the contestants are instructed to bring in something which looks edible but isn\'t.', '01575_something_which_looks_like_food_but_isnt_food.jpg', '01575_something_which_looks_like_food_but_isnt_food.jpg'),
(313, '|273|', 1, '|4|6|9|13|', 4, 'Predict what other contestants will do', 'In this task the contestants are presented with one or more objects, and are asked to predict what one or more of the other contestants will do when presented with the same object(s), before doing something themselves.|If a contestant\'s prediction matches what the other contestant does, then both of them earn points.', '00273_do_something_with_an_object_predict_what_another_will_do.jpg', '00273_do_something_with_an_object_predict_what_another_will_do.jpg'),
(314, '|1596|', 4, '|3|4|6|11|', 4, 'Get a food item into a piece of kitchen equipment', 'In this task the contestants are instructed to get a specific item of food (e.g. slice of bread, pizza, carton of milk) into a relevant piece of kitchen equipment (e.g. toaster, oven, refrigerator) from the furthest distance possible.|Only the contestants\' last attempts are counted.', '01596_get_a_slice_of_bread_into_a_toaster.jpg', '01596_get_a_slice_of_bread_into_a_toaster.jpg'),
(315, '|391|', 1, '|3|4|6|9|13|', 5, 'Surprise memory test', 'In this task the contestants enter a room in which a selection of seemingly random objects are strung from the ceiling, and the Taskmaster\'s assistant makes some seemingly random statements.|The contestants are instructed to read the first task brief once the Taskmaster\'s assistant has left the room.|The second task brief, read once they have reunited with the Taskmaster\'s assistant in another location, asks them to recall not only the objects which were hanging from the ceiling, but the things that were said by the assistant.', '00391_enter_the_caravan_within_2_minutes.jpg', '00391_enter_the_caravan_within_2_minutes.jpg'),
(316, '|1167|', 3, '|4|6|9|', 3, 'Make and serve the Taskmaster\'s assistant a drink', 'In this task the contestants are instructed to make and serve the Taskmaster\'s assistant a drink.|The Taskmaster\'s assistant is seated within a cordoned-off area, and the contestant must remain outside that area.', '01167_make_and_serve_david_a_drink.jpg', '01167_make_and_serve_david_a_drink.jpg'),
(317, '|1612|', 4, '|6|8|', 2, 'Perform an informative puppet show', 'In this task the contestants are instructed to perform an educational or thought-provoking puppet show.', '01612_perform_a_thought_provoking_puppet_show.jpg', '01612_perform_a_thought_provoking_puppet_show.jpg'),
(318, '|400|', 1, '|4|11|15|', 3, 'Throw objects, but not too far', 'In this live studio task, the contestants are instructed to select one of three very different items supplied to them, and throw that thing so it lands within a designated area.|If their object lands outside the area, they are eliminated.|In some versions, the person who throws their item the longest distance is eliminated.|The task continues until there is just one contestant remaining.', '00400_throw_some_things_beyond_a_line.jpg', '00400_throw_some_things_beyond_a_line.jpg'),
(319, '|1622|', 4, '|3|6|', 2, 'Build a carrot tower while listing items in a category', 'In this task the contestants have to construct a tower out of carrots.|They begin with 30 seconds on the timer, but can reset the timer back to 30 seconds again each time they shout the name of an item belonging to a given category (e.g. mammals, or provinces).|If they repeat an item, the task is over.', '01622_build_a_carrot_tower.jpg', '01622_build_a_carrot_tower.jpg'),
(320, '|1104|', 3, '|4|6|', 2, 'Pop a popcorn kernel', 'In this task the contestants are instructed to pop a popcorn kernel as quickly as possible.|They are not permitted to enter the house, so have to use equipment found in the garden or shed.', '01104_pop_a_popcorn_kernel.jpg', '01104_pop_a_popcorn_kernel.jpg'),
(321, '|69|', 1, '|6|12|', 2, 'Make the best snowman', 'In this task the contestants are asked to build the best snowman, without any snow.', '00069_make_the_best_snowman.jpg', '00069_make_the_best_snowman.jpg'),
(322, '|782|', 4, '|6|', 1, 'Melt the candle', 'In this task the contestants are instructed to melt a candle as quickly as possible.|In some versions they have to melt as much as possible in a given time frame. In others, it is the person who melts all of the candle fastest who wins.', '00782_melt_the_candle.jpg', '00782_melt_the_candle.jpg'),
(323, '|269|', 1, '|6|', 1, 'Decorate your headwear using litter-pickers', 'In this live studio task the contestants are instructed to decorate their headwear with the items provided (e.g. fruits, Christmas decoartions) using only a pair of litter-pickers to handle the items.|There is no rule against collaborating with other contestants, which some take advantage of.', '00269_make_the_most_exotic_fruit_hat.jpg', '00269_make_the_most_exotic_fruit_hat.jpg'),
(324, '|971|', 3, '|4|', 1, 'Memorise the code', 'In this task the contestants are instructed to memorise a code for recollection at a later date.|The contestants then have to recall the code to the best of their ability in studio. ', '00971_memorise_the_code.jpg', '00971_memorise_the_code.jpg'),
(325, '|258|', 1, '|4|13|', 2, 'Make a plastic bag as heavy as possible', 'In this task the contestants have to add as much weight as possible to a plastic shopping bag without the handles breaking.', '00258_make_a_plastic_bag_as_heavy_as_possible.jpg', '00258_make_a_plastic_bag_as_heavy_as_possible.jpg'),
(326, '|311|', 1, '|9|', 1, 'The most surprisingly beautiful thing', 'In this prize task the contestants are instructed to bring in the most surprisingly beautiful thing.', '00311_the_most_surprisingly_beautiful_thing.jpg', '00311_the_most_surprisingly_beautiful_thing.jpg'),
(327, '|240|', 1, '|3|9|11|', 3, 'Make a parachute for an object', 'In this task the contestants have to build a parachute for a given object (e.g. a wooden spoon, an egg, or a stuffed toy flamingo), in order to either slow down its descent as much as possible, or to make the descent last a specific length of time.', '00240_make_a_parachute_for_a_wooden_spoon.jpg', '00240_make_a_parachute_for_a_wooden_spoon.jpg'),
(328, '|236|', 1, '|9|11|', 2, 'The best invention', 'In this prize task the contestants are instructed to bring in the best invention.', '00236_the_best_invention.jpg', '00236_the_best_invention.jpg'),
(329, '|390|', 1, '|9|13|', 2, 'The weirdest wooden thing', 'In this prize task the contestants are asked to bring in the weirdest wooden thing.', '00390_the_weirdest_wooden_thing.jpg', '00390_the_weirdest_wooden_thing.jpg'),
(330, '|277|', 1, '|9|13|', 2, 'The best thing from the ‘90s', 'In this prize task the contestants are instructed to bring in the best thing from the 1990s.', '00277_the_best_thing_from_the_90s.jpg', '00277_the_best_thing_from_the_90s.jpg'),
(331, '|281|', 1, '|9|11|13|', 3, 'Silently mouth a fact to the Taskmaster', 'In this live studio task the contestants first have to write down a fact consisting of a given number of words.|They then have to silently mouth their fact to the Taskmaster, who tries to guess what their fact is.|Their performances are evaluated based on how many words the Taskmaster is able to guess correctly.|There may also be a bonus point available for the best fact.', '00281_silently_mouth_a_ten_word_fact_to_greg.jpg', '00281_silently_mouth_a_ten_word_fact_to_greg.jpg'),
(332, '|223|', 1, '|9|11|', 2, 'The most thought-provoking thing', 'In this prize task the contestants are instructed to bring in the most thought-provoking thing.', '00223_the_most_thought_provoking_thing.jpg', '00223_the_most_thought_provoking_thing.jpg'),
(333, '|260|', 1, '|9|11|', 2, 'The least appropriate wedding accessory', 'In this prize task the contestants are instructed to bring in the least appropriate wedding accessory.', '00260_the_least_appropriate_wedding_accessory.jpg', '00260_the_least_appropriate_wedding_accessory.jpg'),
(334, '|411|', 1, '|9|11|13|', 3, 'The best thing taken from someone else’s home', 'In this prize task the contestants are instructed to bring in the best thing taken from someone else’s house.', '00411_the_best_thing_taken_from_someone_elses_house.jpg', '00411_the_best_thing_taken_from_someone_elses_house.jpg'),
(335, '|51|', 1, '|9|13|', 2, 'Make an unexpected silhouette\r\n', 'In this task the contestants are asked to create a surprising silhouette on a screen.', '00051_make_an_unexpected_silhouette.jpg', '00051_make_an_unexpected_silhouette.jpg'),
(336, '|375|', 1, '|4|9|11|13|', 4, 'Something that will make your life better', 'In this prize task the contestants are asked to bring in something that makes life better.', '00375_the_best_thing_that_will_change_your_life.jpg', '00375_the_best_thing_that_will_change_your_life.jpg'),
(337, '|850|', 1, '|12|15|', 2, 'Identify the contents of the edible coating', 'In this task, the contestants are instructed to identify a number of items which have either been fried in batter, or coated in mashed potato.|They are permitted to carry out certain actions to a limited number of the items, such as licking, sniffing, eating, biting, squeezing, poking with a finger, stamping on, throwing on the floor, examining with a magnifying glass, or dropping in water.|A clue to the hidden items is normally provided somewhere in the room, either as a full list hidden inside one of the items, or as labels in a location that the contestant might not think to look.', '00850_identify_the_contents_of_the_battered_items.jpg', '00850_identify_the_contents_of_the_battered_items.jpg'),
(338, '|128|', 1, '|12|', 1, 'Hide the giant, brightly-coloured inflatables', 'In this task, the contestants are instructed to try to hide one or more large, brightly-coloured inflatable items (e.g. a giant beach ball, or a set of large inflatable bright pink flamingos) in a very open location which offers few, if any, hiding places.|The task has been used as a special task assigned to just one person, and also as a general task assigned to all contestants.', '00128_hide_the_giant_beach_ball.jpg', '00128_hide_the_giant_beach_ball.jpg'),
(339, '|131|', 1, '|12|', 1, 'Identify the contents of the sleeping bag', 'In this task the contestants are instructed to identify the contents of a sleeping bag without looking in the bag or removing the items.', '00131_identify_the_contents_of_a_sleeping_bag.jpg', '00131_identify_the_contents_of_a_sleeping_bag.jpg'),
(340, '|471|', 1, '|12|', 1, 'The best thing with wings', 'In this prize task the contestants are instructed to bring in the best thing with wings.', '00471_the_best_thing_with_wings.jpg', '00471_the_best_thing_with_wings.jpg'),
(341, '|727|', 1, '|3|4|6|12|', 4, 'Do something impressive under the table while waving', 'In this task the contestants are instructed to do something impressive under the table with one hand while maintaining eye contact with the camera and waving with their other hand.', '00727_the_most_impressive_thing_under_the_table.jpg', '00727_the_most_impressive_thing_under_the_table.jpg'),
(342, '|381|', 1, '|4|9|11|12|', 4, 'Hide three fruits or vegetables from the Taskmaster\'s assistant', 'In this task the contestants are instructed to hide three fruits or vegetables (e.g. aubergines, onions, or lemons) within a specific location in a limited time.|Once the time is up, the Taskmaster\'s assistant returns and attempts to find all three fruits or vegetables as quickly as possible.|The winner is the person who most effectively hides the items, causing the assistant to spend the longest searching for them, or to find the least of them.', '00381_hide_three_aubergines_from_alex.jpg', '00381_hide_three_aubergines_from_alex.jpg'),
(343, '|246|', 1, '|12|', 1, 'Make and eat a pancake with objects tucked into your sweatband', 'In this task the contestants are instructed to don a sweatband, tuck as many things as possible from around the kitchen into the sweatband, and then make and eat a pancake, all within a limited timeframe.|The winner is the contestant who manages to keep the most things in their sweatband throughout the process.', '00246_make_and_eat_a_pancake.jpg', '00246_make_and_eat_a_pancake.jpg'),
(344, '|896|', 3, '|12|', 1, 'Get the tent and its contents through the tunnel', 'In this task the contestants must attempt to pass an entire tent and all of its contents through a play tunnel, and then ring a service bell, within a limited timeframe.', '00896_get_the_tent_through_the_tunnel.jpg', '00896_get_the_tent_through_the_tunnel.jpg'),
(345, '|206|', 1, '|12|', 1, 'The best liquid', 'In this prize task the contestants are instructed to bring in the best liquid.', '00206_the_best_liquid.jpg', '00206_the_best_liquid.jpg'),
(346, '|409|', 1, '|12|', 1, 'Serenade yourself', 'In this task the contestants have to serenade themselves.|They are given a limited time to prepare, and are then shown apparently serenading themselves through the use of video editing.', '00409_serenade_yourself.jpg', '00409_serenade_yourself.jpg'),
(347, '|454|', 1, '|12|', 1, 'The best pointy thing', 'In this prize task the contestants are instructed to bring in the best pointy thing.', '00454_the_best_pointy_thing.jpg', '00454_the_best_pointy_thing.jpg'),
(348, '|125|', 1, '|11|12|', 2, 'The best sheep-related item', 'In this prize task the contestants are instructed to bring in the best sheep-related item.', '00125_the_best_sheep_related_item.jpg', '00125_the_best_sheep_related_item.jpg'),
(349, '|423|', 1, '|4|11|13|', 3, 'Inflate, tie, and pop the most balloons', 'In this task the contestants have a limited time to inflate, tie, and pop the most balloons possible.|They are not given any indication of how much time they have remaining, so must estimate this themselves, and make a judgment call on when to stop inflating and start bursting.|In some versions, they are disqualified if they leave any balloons unburst while, in others, any unburst balloons are merely deducted from their total count.', '00423_inflate_tie_and_pop_the_most_balloons.jpg', '00423_inflate_tie_and_pop_the_most_balloons.jpg'),
(350, '|839|', 1, '|3|4|6|9|11|', 5, 'Get the toilet paper as far away as possible', 'In this task the contestants have to get the end sheet of a roll of toilet paper as far away as possible without the toilet paper breaking or touching the ground.', '00839_get_the_sheet_of_loo_roll_as_far_away_as_possible.jpg', '00839_get_the_sheet_of_loo_roll_as_far_away_as_possible.jpg'),
(351, '|732|', 1, '|3|13|', 2, 'Make a balloon hover', 'In this task the contestants are instructed to make a helium balloon hover between waist and shoulder/cheek height for a given length of time, while sneering.', '00732_make_that_balloon_hover.jpg', '00732_make_that_balloon_hover.jpg'),
(352, '|1155|', 8, '|1|3|6|11|', 4, 'Build the tallest tower of toilet rolls', 'In this live studio task the contestants must first build a tower out of toilet rolls.|Each then has an opportunity to knock down one of the other contestants\' towers by throwing one or more of their shoes at them from a specific location.|The person with the tallest remaining tower wins the task.', '01155_build_the_tallest_tower_of_toilet_rolls.jpg', '01155_build_the_tallest_tower_of_toilet_rolls.jpg'),
(353, '|380|', 1, '|12|', 1, 'The most stressful thing', 'In this prize task the contestants are asked to bring in the most stressful thing.', '00380_the_most_stressful_thing.jpg', '00380_the_most_stressful_thing.jpg'),
(354, '|729|', 1, '|3|', 1, 'Transport all the dinnerware', 'In this task the contestants are instructed to move a large quantity of crockery/glassware from one place to another, but must do so using one of the provided means of personal transport (e.g. a hoverboard, scooter, bicycle, or unicycle).|The winner of the task is the one who completes the task fastest, but time penalties are added for every item of crockery/glassware broken during the process. ', '00729_deliver_all_the_plates_to_alex.jpg', '00729_deliver_all_the_plates_to_alex.jpg'),
(355, '|531|', 8, '|3|4|6|', 3, 'Create an amusement park ride', 'In this task the contestants are instructed to create an amusement park ride for the Taskmaster\'s assistant.', '00531_create_an_amusement_park_ride.jpg', '00531_create_an_amusement_park_ride.jpg'),
(356, '|539|', 8, '|3|', 1, 'Karate chop the thickest spaghetti log', 'In this live studio task the contestants must attempt to break in half, with their hand, the thickest bundle of spaghetti.', '00539_karate_chop_the_thickest_spaghetti_log.jpg', '00539_karate_chop_the_thickest_spaghetti_log.jpg'),
(357, '|959|', 1, '|3|6|13|', 3, 'Build and topple a tower for a pot of yoghurt', 'In this task the contestants are instructed to construct a tower, place a pot of yoghurt at the top of the tower, and then topple the tower in an attempt to get the yoghurt to land in a target area.', '00959_build_and_topple_a_tower_for_a_pot_of_yoghurt.jpg', '00959_build_and_topple_a_tower_for_a_pot_of_yoghurt.jpg'),
(358, '|953|', 1, '|3|6|11|13|', 4, 'Complete tasks while repeating a word in time with a metronome', 'In this task the contestants must complete one or more tasks while also remembering to say a word (sometimes \'metronome\', and sometimes a word of their choice) between each tick of a metronome.|In some versions of the task, they have to complete a series of mini-tasks, such as inflating a balloon, and eating poppadoms.', '00953_complete_various_tasks_while_saying_metronome.jpg', '00953_complete_various_tasks_while_saying_metronome.jpg'),
(359, '|451|', 1, '|3|4|', 2, 'Persuade someone to look in your bag', 'In this task the contestants must first hide something inside a fabric shopping trolley, and then persuade someone to want to see the contents of their trolley over their competitors\'.', '00451_persuade_the_security_guard_to_look_in_your_bag.jpg', '00451_persuade_the_security_guard_to_look_in_your_bag.jpg'),
(360, '|134|', 1, '|3|11|13|', 3, 'Bring the Taskmaster\'s assistant their lunch', 'In this task the contestants are instructed to bring a tray of food to the Taskmaster\'s assistant while hopping on one leg.|Their path is usually blocked by strings of bunting, which they must cross or go under.|Each time their raised foot touches the ground, they must eat a piece of the assistant\'s lunch.|The person who delivers the most food to the assistant the fastest wins.', '00134_cross_the_bunting_to_give_alex_his_lunch.jpg', '00134_cross_the_bunting_to_give_alex_his_lunch.jpg'),
(361, '|422|', 1, '|3|6|', 2, 'Subtly deliver a five word instruction to the Taskmaster\'s assistant', 'In this task the contestants must subtly deliver a five-word instruction to the Taskmaster\'s assistant, who awaits dressed like a caricature of a spy.', '00422_subtly_deliver_a_five_word_instruction_to_alex.jpg', '00422_subtly_deliver_a_five_word_instruction_to_alex.jpg'),
(362, '|1351|', 1, '|3|11|', 2, 'Get the most forks in your bucket', 'In this live studio task the contestants must attempt to throw the most forks into their bucket.|Before each throw, they must perform one full rotation on their swivel chairs.', '01351_get_the_most_forks_in_your_bucket.jpg', '01351_get_the_most_forks_in_your_bucket.jpg'),
(363, '|195|', 1, '|11|', 1, 'The most embarrassing thing', 'In this prize task the contestants are instructed to bring in the most embarrassing thing.', '00195_the_most_embarrassing_item.jpg\r\n', '00195_the_most_embarrassing_item.jpg\r\n'),
(364, '|526|', 8, '|3|', 1, 'Reassemble a keyboard / Type a message to the Taskmaster', 'In this two-part task the contestants first have to try to replace all of the keys removed from a computer keyboard in a very limited time.|They then have to type a message to the Taskmaster using their reassembled keyboards.|The winner is the person whose message is the most comprehensible.', '00526_place_the_keys_back_on_the_keyboard_and_send_a_message.jpg', '00526_place_the_keys_back_on_the_keyboard_and_send_a_message.jpg'),
(365, '|518|', 8, '|3|11|', 2, 'Hit the Taskmaster\'s assistant with a frisbee', 'In this task the contestants have to locate the Taskmaster\'s assistant and hit them with a frisbee.|The contestants are not allowed to travel at the same time as the frisbee and, each time they throw it, they must don an extra piece of clothing from a clothing rack provided.', '00518_find_paul_and_hit_him_with_a_frisbee.jpg', '00518_find_paul_and_hit_him_with_a_frisbee.jpg'),
(366, '|840|', 1, '|3|', 1, 'Identify the contents of the bowl under the table', 'In this live studio task the contestants must identify the contents of a bowl under the table at which they are sat.', '00840_identify_the_contents_of_the_bowl_under_the_table.jpg', '00840_identify_the_contents_of_the_bowl_under_the_table.jpg'),
(367, '|491|', 8, '|3|', 1, 'Pack a suitcase as close to 23kg as possible', 'In this live studio task the contestants must pack a suitcase so that it weighs as close to 23kg as possible, without going over.', '00491_pack_a_suitcase_to_23kg.jpg', '00491_pack_a_suitcase_to_23kg.jpg'),
(368, '|722|', 1, '|3|9|11|', 3, 'Get the biggest/heaviest thing through the doughnut', 'In this task the contestants are instructed to get either the biggest, or heaviest, thing through the hole of a doughnut.', '00722_get_the_biggest_thing_through_the_doughnut.jpg', '00722_get_the_biggest_thing_through_the_doughnut.jpg'),
(369, '|494|', 8, '|3|', 1, 'Dramatically smash the vase / Reassemble the vase', 'In this task the contestants are instructed to smash a vase in as dramatic a fashion as possible, and are provided with an array of tools/weapons with which to do so.|The second part of the task, written on a task brief hidden inside the vase, instructs them to then reassemble the vase as perfectly as possible.', '00494_dramatically_smash_the_vase.jpg', '00494_dramatically_smash_the_vase.jpg'),
(370, '|525|', 8, '|3|4|6|', 3, 'Wear the most unexpected costume under your outfit', 'In this homework task, the contestants are instructed to wear an unexpected costume under their regular studio filming clothes, which they must then reveal live in the studio.', '00525_the_most_outlandish_costume.jpg', '00525_the_most_outlandish_costume.jpg'),
(371, '|1223|', 8, '|3|8|', 2, 'Messy roulette', 'In this live studio task, the contestants must make a binary decision before taking an action which may or may not end up with them getting in a mess.|The decision may be about which bottle of soda to open up, not knowing which one the Taskmaster has just shaken, or whether to ask the Taskmaster to flick the power switch on a vacuum cleaner set to blow and loaded with flour one more time, not knowing whether he has already turned it on or off.|The contestants are given the opportunity to first ask the Taskmaster one or more questions, but the Taskmaster is under no obligation to tell the truth.', '01223_lemonade_roulette.jpg', '01223_lemonade_roulette.jpg'),
(372, '|397|', 1, '|6|11|', 2, 'Create an impressive water feature', 'In this task the contestants are instructed to create an impressive water feature.', '00397_make_the_most_striking_water_feature.jpg', '00397_make_the_most_striking_water_feature.jpg'),
(373, '|289|', 1, '|6|11|', 2, 'Deliver the task to the Taskmaster\'s assistant', 'In this task the contestants are instructed to deliver the task brief to the Taskmaster\'s assistant in the most spectacular or superior way.', '00289_spectacularly_deliver_the_task_to_alex.jpg', '00289_spectacularly_deliver_the_task_to_alex.jpg'),
(374, '|1207|', 8, '|3|4|6|9|', 4, 'Name powerful animals and throw fish-shaped snacks into a fishbowl', 'In this task the contestants must try to throw a fish-shaped snack into a fishbowl from across the room.|Before each throw, they must name a species of animal. The animal they name before they succeed in their throw is the one that they have chosen.|The animals are then compared in terms of how \'powerful\' they are, with the most powerful animal winning the task.', '01207_name_powerful_animals_and_throw_a_chocolate_fish_into_a_fishbowl.jpg', '01207_name_powerful_animals_and_throw_a_chocolate_fish_into_a_fishbowl.jpg'),
(375, '|499|', 8, '|3|', 1, 'Catch a grape with a tuba', 'In this team task the contestants must catch a grape with a tuba.|The grape must not be thrown, and the tuba must be played throughout the duration of the grape\'s flight.|The team who catches the grape in the tuba over the greatest distance wins.', '00499_catch_a_grape_with_a_tuba.jpg', '00499_catch_a_grape_with_a_tuba.jpg'),
(376, '|1479|', 1, '|3|4|6|13|', 4, 'Make noises without being identified by the Taskmaster', 'In this live studio task, the contestants are instructed to make certain noises.|The Taskmaster is seated with their back to the contestants, and must determine who is making each noise.|If the Taskmaster guesses correctly, they are eliminated.|The winner of the task is the last contestant standing.', '01479_make_noises_without_being_identified.jpg', '01479_make_noises_without_being_identified_thumb.jpg'),
(377, '|842|', 1, '|3|11|', 2, 'Cover your legs in cling film and duct tape / Reach a target destination', 'In this two-part task, the contestants are first instructed to cover their lower body entirely in cling film and/or gaffer tape.|They are then handed a second task brief, which instructs them to reach a target location.|The person who reaches the target location and completes a specified action fastest wins.', '00842_cover_your_legs_in_cling_film_and_gaffer_tape.jpg', '00842_cover_your_legs_in_cling_film_and_gaffer_tape.jpg'),
(378, '|1639|', 4, '|3|', 1, 'Stack your groceries', 'In this live task the contestants each have a selection of grocery items and must select one of them, name a different one, balance it on a stack, and name another contestant.|The order of these operations may vary from version to version.|If they name an incorrect item, their tower collapses, or they hesitate for too long, they are disqualified.|The winner is either the last one standing, or the one with the tallest tower of groceries.', '01639_name_a_different_food_item_balance_the_food_item_name_a_contestant.jpg', '01639_name_a_different_food_item_balance_the_food_item_name_a_contestant.jpg'),
(379, '|738|', 4, '|3|9|', 2, 'Long-distance waffle-making', 'In this task the contestants must make a waffle using a waffle iron, with the catch being that the waffle iron is inside a designated area in which they must not set food.|The contestant who makes the best waffle wins.', '00738_make_a_waffle_without_stepping_on_the_red_mat.jpg', '00738_make_a_waffle_without_stepping_on_the_red_mat.jpg'),
(380, '|227|', 1, '|9|', 1, 'Make the best cream-based art', 'In this task the contestants are provided with some kind of cream and instructed to make a work of art using it.', '00227_make_the_best_squirty_cream_art.jpg', '00227_make_the_best_squirty_cream_art.jpg'),
(381, '|515|', 8, '|3|', 1, 'Leave the room', 'In this task the Taskmaster\'s assistant rushes out of the room before the contestant has a chance to read the task brief, pretending that they have forgotten something.|The contestant who leaves the room fastest - whether because they read the task brief, or just want to check what\'s happening - wins.', '00515_leave_the_room.jpg', '00515_leave_the_room.jpg'),
(382, '|1217|', 8, '|3|4|', 2, 'Join the video chat dressed as a famous figure', 'In this two-part homework task, the contestants are first given an old-fashioned mobile phone, and are instructed to hold onto it and await further instructions.|They later receive a text message, instructing them to join a video call dressed as a famous figure, such as Abe Lincoln, Santa Claus, or Henrik Ibsen.|The contestants receive scores based on how quickly they are able to join the call wearing the appropriate costume, but points may also be adjusted to reflect the quality of their costumes.', '01217_keep_the_phone_with_you_join_the_video_chat.jpg', '01217_keep_the_phone_with_you_join_the_video_chat.jpg'),
(383, '|1642|', 4, '|3|', 1, 'Put everything back in the bag hanging from the ceiling', 'In this task the contestants are instructed to pull on a string, which unfastens a bag hanging from the ceiling, spilling its contents all over the floor.|The contestants are then instructed to put all of the contents back into the bag, without removing it from the ceiling.', '01642_put_all_the_duplos_back_in_the_bag.jpg', '01642_put_all_the_duplos_back_in_the_bag.jpg'),
(384, '|1154|', 8, '|3|9|', 2, 'Long distance dental hygiene', 'In this task the contestants must attempt to brush the Taskmaster\'s assistant\'s teeth from as far away as possible.', '01154_brush_pauls_teeth_from_the_farthest_distance.jpg', '01154_brush_pauls_teeth_from_the_farthest_distance.jpg'),
(385, '|728|', 1, '|3|', 1, 'Catch the rat', 'In this task the contestants are instructed to capture a radio-controlled toy rat, which will run over a red mat in a given period of time.|The contestants must be at least 3 metres away from the rat when it is caught, and the most impressive or ingenious rat-catching technique wins.', '00728_catch_the_rat.jpg', '00728_catch_the_rat.jpg'),
(386, '|753|', 4, '|3|', 1, 'Move the party', 'In this task the contestants are instructed to move the party food from one table to another a short distance away, without crossing a barrier.', '00753_move_the_party_food_to_a_different_table.jpg', '00753_move_the_party_food_to_a_different_table.jpg'),
(387, '|1126|', 3, '|1|3|4|8|11|', 13, 'Be the Nth person to complete an action', 'In this task the contestants are instructed to attempt to be the Nth (e.g. 2nd, 3rd, 4th) person to complete a specific physical action.|This action may be to high-five the Taskmaster\'s assistant, or to touch another object (e.g. a fibreglass cow), or to burst out of a box.|Contestants may be disqualified or receive no points for completing the action first or last, with the remaining contestants earning points based on their relative times for completing the action.', '01126_high_five_david.jpg\r\n', '01126_high_five_david.jpg\r\n'),
(388, '|961|', 1, '|9|11|', 2, 'Shove your fish', 'In this live studio task the contestants have to shove a toy mechanical fish across the stage and onto a target using mops.|The person whose fish is furthest from the centre of the target each round is eliminated.', '00961_shove_your_fish.jpg', '00961_shove_your_fish.jpg'),
(389, '|1253|', 4, '|1|11|13|', 3, 'Record the highest number on a pedometer', 'In this task the contestants are instructed to record the highest number on a pedometer.|The contestants may be given a certain amount of time to prepare, and then a smaller amount of time to actually record the number, or they may be given a single time limit for their entire attempt.', '01253_make_the_pedometer_count_the_most_steps.jpg', '01253_make_the_pedometer_count_the_most_steps.jpg'),
(390, '|1938|', 3, '|1|', 1, 'Display your vocal range', 'In this task the contestants must display their vocal range by singing the first part of a statement in their lowest voice, and the second part in their highest voice.', '01938_display_your_vocal_range.jpg', '01938_display_your_vocal_range.jpg'),
(391, '|341|', 1, '|11|12|', 2, 'The best present for a doctor', 'In this prize task the contestants are instructed to bring in the best present for a doctor.', '00341_the_best_present_for_a_doctor.jpg', '00341_the_best_present_for_a_doctor.jpg'),
(392, '|33|', 1, '|11|12|13|', 3, 'The most satisfying item', 'In this prize task the contestants have to bring in the most satisfying item.', '00033_the_most_satisfying_item.jpg', '00033_the_most_satisfying_item.jpg'),
(393, '|512|', 8, '|11|', 1, 'The scariest thing', 'In this prize task the contestants are instructed to bring in the scariest thing.', '00512_the_thing_that_scares_you_the_most.jpg', '00512_the_thing_that_scares_you_the_most.jpg'),
(394, '|1229|', 8, '|1|4|9|', 3, 'Draw a life-size self portrait with your nose in the canvas', 'In this live studio task the contestants have to draw a life-size self portrait on a canvas while keeping their nose inserted through a hole in the canvas at all times.', '01229_draw_a_life_size_self_portrait.jpg', '01229_draw_a_life_size_self_portrait.jpg'),
(395, '|507|', 8, '|1|', 1, 'A family heirloom', 'In this prize task, the contestants are instructed to bring in a family heirloom.', '00507_the_most_beloved_family_heirloom.jpg', '00507_the_most_beloved_family_heirloom.jpg'),
(396, '|430|', 1, '|11|', 1, 'Select the shortest breadstick', 'In this live studio task the contestants must take it in turns to try to remove the shortest breadstick from the apron of one of their competitors.|Before they make their selection, the apron-wearer must point to one of their breadsticks, wink, and tell them that it is the shortest one.|If the shortest breadstick is selected, the contestant from whose apron it was removed is eliminated.|The winner is the last contestant remaining.', '00430_pull_the_shortest_breadstick.jpg', '00430_pull_the_shortest_breadstick.jpg'),
(397, '|355|', 1, '|9|', 1, 'Design an album cover', 'In this task the contestants must design an album cover for a fictional vinyl record.|As part of this, they must come up with an artist or band name, and a name for the album.|The best or most impressive album cover wins.', '00355_design_an_iconic_album_cover.jpg', '00355_design_an_iconic_album_cover.jpg'),
(398, '|1208|', 8, '|1|3|6|9|', 4, 'Mislead the Taskmaster about the contents of your case', 'In this live studio task the contestants must attempt to mislead the Taskmaster about what is contained within a briefcase or suitcase they carry across the stage.|The contestants\' options for the contents of the case mean that the case is either very heavy, or very light.', '01208_empty_briefcase_or_briefcase_full_of_onions.jpg', '01208_empty_briefcase_or_briefcase_full_of_onions.jpg'),
(399, '|338|', 1, '|4|11|', 2, 'Work out what the Taskmaster\'s assistant is wearing', 'In this task the contestants must figure out what the Taskmaster\'s assistant is wearing.|The assistant may only communicate with them by honking a horn.', '00338_work_out_what_alex_is_wearing.jpg', '00338_work_out_what_alex_is_wearing.jpg'),
(400, '|340|', 1, '|11|', 1, 'Get into two sleeping bags and complete other actions', 'In this live studio task the contestants must don one wearable sleeping bag, salute the Taskmaster for five seconds, get into a second sleeping bag, and then skip rope once.', '00340_get_into_two_sleeping_bags.jpg', '00340_get_into_two_sleeping_bags.jpg'),
(401, '|1783|', 4, '|3|6|8|9|', 4, 'Secure the container with the largest item or collection', 'In this live studio task, each of the contestants stands behind a container (e.g. a box or bucket).|Each container either contains one object of varying size (e.g. carrots), or a collection of objects which varies in number (e.g. rubber ducks).|The contestants must aim to end up with the container which contains either the largest version of the item (e.g. the largest carrot), or the largest collection of objects (e.g. the most rubber ducks).|Each contestant is given an opportunity to either keep their container, or risk swapping with someone else.|In some versions of the task, the contestants may get to peek at the contents of their new container, once they have swapped.', '01783_carrots_in_boxes.jpg', '01783_carrots_in_boxes.jpg'),
(402, '|2092|', 9, '|8|', 1, 'The best thing to take to a desert island', 'In this prize task the contestants are asked to bring in the best thing to take to - or have on - a desert island. ', '02092_the_best_thing_to_take_to_a_desert_island.jpg', '02092_the_best_thing_to_take_to_a_desert_island_thumb.jpg'),
(403, '|1577|', 4, '|9|', 1, 'Build the tallest structure with playing cards', 'In this task the contestants must build as tall a structure as possible using playing cards.|There may be additional requirements, such as balancing a specific object on top, or not damaging any of the cards.|The contestant who succeeds with the tallest structure wins.', '01577_build_a_house_of_cards.jpg', '01577_build_a_house_of_cards_thumb.jpg'),
(404, '|7|', 1, '|13|', 1, 'The most impressive item', 'In this prize task, the contestants must bring in the most impressive item.', 'https://taskmaster.info/images/tasks/00007_most_impressive_item.jpg', 'https://taskmaster.info/images/tasks/00007_most_impressive_item_thumb.jpg'),
(405, '|1327|', 2, '|13|', 1, 'The ugliest item', 'In this prize task, the contestants are instructed to bring in the ugliest item they own.', '01327_the_ugliest_item.jpg', '01327_the_ugliest_item_thumb.jpg'),
(406, '|1495|', 3, '|1|', 1, 'Get paper into a toilet from a balcony', 'In this task, the contestants must try to get as much paper into a toilet as possible from a balcony.|The paper may be sheets of A4 paper, or rolls of toilet paper.|The contestants may or may not be explicitly told not to move from their spot on the balcony.', '01495_fill_the_toilet_with_a4_paper.jpg', '01495_fill_the_toilet_with_a4_paper_thumb.jpg'),
(407, '|2187|', 1, '|4|6|13|', 3, 'Write a song or poem incorporating words you have chosen', 'In this two-part task, the contestants are first instructed to write or say five \'impressive\' or \'wonderful\' words.|In the second part of the task, they are then instructed to write a song, or a poem, incorporating the words they chose.', '02187_write_a_classic_song_incorporating_five_wonderful_words.jpg', '02187_write_a_classic_song_incorporating_five_wonderful_words_thumb.jpg'),
(408, '|1240|', 8, '|1|3|4|6|9|11|', 6, 'Hold the jugs above the microwaves', 'In this task, the contestants are initially advised against opening the task brief by the Taskmaster\'s assistant.|When they do open the task brief, they learn that they have to hold two large jugs (e.g. plastic bottles of milk, or coffee pots) over two microwaves in the room, for as long as possible, and that if they\'d listened to the Taskmaster\'s assistant\'s advice, they\'d probably have done much better.', '01240_hold_the_milk_bottles_above_the_microwaves.jpg', '01240_hold_the_milk_bottles_above_the_microwaves_thumb.jpg'),
(409, '|136|', 1, '|3|6|11|13|', 4, 'Wheelie bin obstacle course', 'In this team task, the contestants must navigate an obstacle course while one of them is within a wheelie bin, and the others are blindfolded.|An additional challenge is usually added through the requirement that  none of the contestants may speak in their native language (and sometimes, even another commonly spoken language), or that the individual in the bin may only say words beginning with a certain letter.', '00136_non_english_wheelie_bin_obstacle_course.jpg', '00136_non_english_wheelie_bin_obstacle_course_thumb.jpg'),
(410, '|2179|', 1, '|4|', 1, 'The thing you most want on a Sunday morning', 'In this prize task, the contestants must bring in the thing that they most want (or need) on a Sunday morning.', '02179_the_thing_you_most_want_on_a_sunday_morning.jpg', '02179_the_thing_you_most_want_on_a_sunday_morning_thumb.jpg'),
(411, '|479|', 1, '|6|11|', 2, 'Work out how many balls are in the basket', 'In this task the contestants must work out, or guess, how many balls are contained in a cuboid basket.|While the basket may, on first glance, appear to contain only balls of one size, it actually contains within it a smaller basket which contains smaller balls, and a small box within that which contains even smaller balls (plus the answer they are looking for).|The catch is that all the balls must be within the basket when the contestants make their guess.', '00479_work_out_how_many_balls_are_in_the_basket.jpg', '00479_work_out_how_many_balls_are_in_the_basket_thumb.jpg'),
(412, '|502|', 8, '|4|11|', 2, 'The best gift for an enemy', 'In this prize task, the contestants must bring in something that they would give to an enemy.', '00502_the_best_gift_for_an_enemy.jpg', '00502_the_best_gift_for_an_enemy_thumb.jpg'),
(413, '|1590|', 4, '|4|6|14|', 4, 'Something that one or more of the cast members can\'t identify', 'In this prize task, the contestants must bring in something that they think that one or more of the cast members will not be able to identify.|Sometimes, the cast member is specified in the brief, and sometimes it is the contestant\'s choice.|The task has also been adapted into a homework task/live game, in which points are assigned based on how many of the other contestants can identify each object.', '01590_something_with_which_atle_wont_be_familiar.jpg', '01590_something_with_which_atle_wont_be_familiar_thumb.jpg'),
(414, '|510|', 8, '|6|', 1, 'Do something impressive with no hands', 'In this task, the contestants must complete some kind of impressive action or performance without using their hands.', '00510_do_the_most_impressive_thing_hands_free.jpg', '00510_do_the_most_impressive_thing_hands_free_thumb.jpg'),
(415, '|521|', 8, '|3|6|', 2, 'Produce the third most impressive creation', 'In this live studio task, the contestants are asked to produce the third most impressive creation (e.g. a playdough dog, or poem to the Taskmaster).', '00521_sculpt_the_third_most_impressive_dog.jpg', '00521_sculpt_the_third_most_impressive_dog_thumb.jpg'),
(416, '|2271|', 1, '|1|', 2, 'Turn over the most beer mats', 'In this tie-breaker task, the contestants have just 30 seconds in which to attempt to turn over the most beer mats, which are lying face-down on a table.', '01929_turn_over_the_most_beer_mats.jpg', '01929_turn_over_the_most_beer_mats_thumb.jpg'),
(417, '|2273|', 8, '|1|3|6|8|', 4, 'Recite pi', 'In this task, the contestants have a limited time to try to memorise pi to as many decimal places as possible, and then have to recall what they have memorised.', '02060_recite_pi.jpg', '02060_recite_pi_thumb.jpg'),
(418, '|55|', 1, '|13|', 1, 'The coolest blue item', 'In this prize task, the contestants are instructed to bring in the coolest blue item.', '00055_the_coolest_blue_item.jpg', '00055_the_coolest_blue_item_thumb.jpg'),
(419, '|292|', 1, '|13|', 1, 'Make yourselves appear as large or small as possible', 'In this team task, the contestants are instructed to make themselves look as large or as small as possible, through the use of  forced perspective and/or camera trickery.', '00292_make_yourselves_appear_larger_or_smaller.jpg', '00292_make_yourselves_appear_larger_or_smaller_thumb.jpg'),
(420, '|1221|', 8, '|1|3|6|', 3, 'Eat the small food item', 'In this task, the contestants are locked into an escape room (usually the caravan), and have to find a way to escape and/or eat a small item of food (usually a grape, but it has also been an almond).', '01221_eat_the_grape.jpg', '01221_eat_the_grape_thumb.jpg'),
(421, '|477|', 1, '|6|', 1, 'Make a beer mat house while ringing the doorbell with increasing frequency', 'In this task the contestants are instructed to build the largest or best house out of beer mats, while also ringing the doorbell with increasing frequency, starting with a 60 second interval, which decreases by 2 seconds each time.', '00477_make_the_largest_beermat_house_while_ringing_the_doorbell.jpg', '00477_make_the_largest_beermat_house_while_ringing_the_doorbell_thumb.jpg'),
(422, '|457|', 1, '|6|', 1, 'Spend money in an uncharacteristic way', 'In this homework task, the contestants are given a fixed sum of money and instructed to spend it in an uncharacteristic way.', '00457_do_something_out_of_character_with_£20.jpg', '00457_do_something_out_of_character_with_£20_thumb.jpg'),
(423, '|1641|', 4, '|6|', 1, 'Draw the biggest bike', 'In this task, the contestants are instructed to draw the biggest bicycle they can.', '01641_draw_the_biggest_bike.jpg', '01641_draw_the_biggest_bike_thumb.jpg'),
(424, '|1218|', 8, '|3|6|', 2, 'Celebrity naming chain', 'In this live task, the contestants must take turns to name famous people, with each name beginning with the last letter of the previous contestant\'s celebrity\'s name.', '01218_celebrity_naming_chain.jpg', '01218_celebrity_naming_chain_thumb.jpg'),
(425, '|994|', 3, '|6|11|', 2, 'Listen to the music for as long as possible', 'In this task, one contestant is instructed to put on headphones and a blindfold, and sit listening to a repetitive piece of music for as long as possible.|It may be assigned as a split task, with the other contestants earning points by placing bets on how long they will last, or as a special task with no points being awarded.', '00994_wait_a_while.jpg', '00994_wait_a_while_thumb.jpg'),
(426, '|349|', 1, '|6|', 1, 'Make a realistic injury using food', 'In this task, the contestants are instructed to make a realistic-looking injury using only food items.', '00349_make_a_realistic_injury_using_food.jpg', '00349_make_a_realistic_injury_using_food_thumb.jpg'),
(427, '|964|', 1, '|6|', 1, 'Work out the weight of the Taskmaster\'s assistant\'s feet and head', 'In this task the contestants are instructed to work out the weight of the Taskmaster\'s assistant\'s head and feet.', '00964_scientifically_work_out_how_much_alexs_feet_and_head_weigh.jpg', '00964_scientifically_work_out_how_much_alexs_feet_and_head_weigh_thumb.jpg'),
(428, '|724|', 1, '|6|', 1, 'Build the lightest tower', 'In the task the contestants are instructed to build the lightest tower possible on a set of scales.|The tower must be the height of a wolf, and is built in front of an electric fan which is switched on for every other minute.', '00724_build_the_lightest_tower_on_a_set_of_scales.jpg', '00724_build_the_lightest_tower_on_a_set_of_scales_thumb.jpg'),
(429, '|1616|', 4, '|6|11|', 2, 'Find the tiny prize', 'In this task, the contestants are instructed to find a tiny prize (e.g. an almond or small rubber duck) hidden in a room in which there are multiple bowls full of some form of soft, wet food (e.g. risalamande or cake batter).|The task is based on festive traditions around the world in which small prizes are hidden inside of food (e.g. the hiding of an almond in rice porridge, or the hiding of a prize in a King cake).|The small prize may be hidden within the bowls as expected, or may be outside the bowls in plain sight, and clues may be provided to its location in the room.', '01616_find_the_almond.jpg', '01616_find_the_almond_thumb.jpg'),
(430, '|1865|', 3, '|6|14|', 2, 'Make your wish come true', 'In this task, the contestants are first instructed to make a wish, and are then given a very limited time to make their wish come true.', '01865_make_your_wish_come_true.jpg', '01865_make_your_wish_come_true_thumb.jpg'),
(431, '|772|', 4, '|3|', 1, 'Land an unbroken egg on the target', 'In this task, the contestants are instructed to land an egg as close as possible to the centre of a target without breaking it.|The contestants have to complete the task from an upper floor balcony, and the target is a short distance away from them on the ground.', '00772_land_eggs_on_a_target.jpg', '00772_land_eggs_on_a_target_thumb.jpg'),
(432, '|2079|', 8, '|3|11|', 3, 'Complete a specific number of laps while obeying the rules', 'In this (usually team-based) task, the contestants have to complete a certain number of laps of a track using a given mode of transport (e.g. a golf cart, or tandem bike), while obeying a set of additional rules.|In some versions, a new rule is added with each completed lap while, in others, a smaller set of rules apply throughout.|The rules for winning the task also vary: in some versions the fastest wins while, in others, the slowest team wins.', '02079_drive_11_laps_and_obey_all_the_rules.jpg', '02079_drive_11_laps_and_obey_all_the_rules_thumb.jpg'),
(433, '|1677|', 1, '|3|6|13|', 3, 'Drink all the vinegar', 'IN this task, the contestants are presented with a large number of shot glasses containing liquids, and are instructed to drink all of the vinegar.|There is normally only one shot glass containing vinegar present, so the challenge is in identifying which one that is.|Clues as to the location of the correct glass may be hidden around the room.', '01677_drink_all_the_vinegar.jpg', '01677_drink_all_the_vinegar_thumb.jpg'),
(434, '|2116|', 8, '|3|', 1, 'Do something while playing tag', 'In this live task, the contestants are instructed to complete an action (e.g. painting a self-portrait, or unwrapping and then donning a Santa suit) while playing a game of tag with one another.|The person who is \'it\' at any point during the game of tag must stop trying to complete the action, and instead crawl on their hands and knees to tag someone else.|Tag-backs are not permitted.', '02116_draw_a_self_portrait_while_playing_tag.jpg', '02116_draw_a_self_portrait_while_playing_tag_thumb.jpg'),
(435, '|746|', 4, '|1|15|', 2, 'The most surprising thing you own', 'In this prize task, the contestants are instructed to bring in the thing that the Taskmaster will be most surprised that they own.', '00746_most_surprising_thing_you_own.jpg', '00746_most_surprising_thing_you_own_thumb.jpg'),
(436, '|2102|', 8, '|1|3|6|9|', 4, 'Follow the Taskmaster\'s orders', 'In this live task, the contestants each wear a set of overalls or a trench-coat with multiple pockets, and each has a collection of small objects.|They must follow the Taskmaster\'s list of rapidly-read instructions about where to put each object as accurately as possible, so that they all end up in the correct places.|In some versions, further complication is added by the inclusion of \'Simon Says\'-style rules whereby only the instructions beginning with the Taskmaster\'s name should be followed.', '02102_follow_the_taskmasters_orders.jpg', '02102_follow_the_taskmasters_orders_thumb.jpg'),
(437, '|330|', 1, '|4|13|', 2, 'The best pair', 'In this prize task, the contestants are instructed to bring in the best pair of things.', '00330_the_best_pair_of_things.jpg', '00330_the_best_pair_of_things_thumb.jpg'),
(438, '|2163|', 1, '|3|4|6|9|13|', 5, 'Make the Taskmaster say your words', 'In this live team task, the contestants must ask the Taskmaster questions (or make statements) consisting of six words, with each contestant contributing two words at a time, with the aim of conveying a particular word to the Taskmaster.', '02163_make_the_taskmaster_say_your_words.jpg', '02163_make_the_taskmaster_say_your_words_thumb.jpg'),
(439, '|2120|', 8, '|4|', 1, 'Hide the body', 'In this task, the contestants are instructed to hide the body of a stuffed dummy or large teddy bear.|The Taskmaster\'s assistant then attempts to find it, and the winner of the task is the person whose \'body\' takes the longest to find.', '02120_hide_this_body.jpg', '02120_hide_this_body_thumb.jpg'),
(440, '|734|', 1, '|4|', 1, 'Make the house haunted', 'In this task, the contestants are instructed to either make the house haunted, or to document that it is haunted.', '00734_make_the_house_haunted.jpg', '00734_make_the_house_haunted_thumb.jpg'),
(441, '|1235|', 8, '|14|', 1, 'Recreate scenes from history', 'In this live team task, the contestants must recreate scenes from history, and are only allowed to speak in four-letter words.|The team for whom the Taskmaster correctly guesses the most scenes wins.', '01235_recreate_scenes_from_nz_history.jpg', '01235_recreate_scenes_from_nz_history_thumb.jpg'),
(442, '|1243|', 1, '|3|', 1, 'Hit the Taskmaster\'s assistant with a ball', 'In this task, the contestants are instructed to hit the Taskmaster\'s assistant with a ball as quickly as possible.|The contestants each wear a camera, and the assistant has a screen which allows them to see where the contestant is going.|However, the assistant may not break a walking pace, or intentionally hide from the contestants.', '01243_strike_alex_with_a_ball.jpg', '01243_strike_alex_with_a_ball_thumb.jpg'),
(443, NULL, 6, '|3|4|6|', 6, 'Predict how many portions of food will be eaten', 'In this task, the contestants enter a room to find a large number of small portions of a particular type of food (e.g. meatballs, medister cakes, Brussels sprouts, marshmallows, or bowls of sauerkarut).|The contestants are instructed to predict something about how many of the items the other contestants will eat (either as individuals, or collectively), and then eat a number of them themselves, in connection with their prediction.', '01613_eat_the_second_most_medister_cakes.jpg', '01613_eat_the_second_most_medister_cakes_thumb.jpg'),
(444, '|1350|', 1, '|3|6|', 2, 'Solve the riddle', 'In this team task, the contestants are situated in different locations, and may not leave those locations.|They are able to communicate with their team-mates via walkie-talkies, and will need to do so in order to solve a riddle.|The clues to the riddle are split between their locations, and usually include a coded message which must be solved by finding the key to the cipher.|The task may also involve awarding bonus points if one of the members of a team is able to get one of their team-mates to say a specific word without arousing suspicion.', '01350_solve_the_riddle.jpg', '01350_solve_the_riddle_thumb.jpg'),
(445, '|1871|', 1, '|3|4|6|13|', 4, 'Count to 13', 'In this live task, the contestants must count to 13 between them, and follow other rules relevant to the specific numbers they are saying.|If they make a mistake, they are eliminated, and an additional rule is added for the remaining contestants to adhere to.', '01871_count_to_13.jpg', '01871_count_to_13_thumb.jpg'),
(446, '|2182|', 1, '|3|', 1, 'Catch something', 'In this open-ended task, the contestants are simply instructed to catch something.|The most spectacular catch wins.', '02182_catch_something.jpg', '02182_catch_something_thumb.jpg'),
(447, '|2056|', 8, '|3|4|6|9|', 4, 'Build the tallest soap tower', 'In this live task, the contestants must construct a tower out of wet bars of soap, while also making the sounds that the previous contestant in line was instructed to perform.', '02056_construct_the_tallest_soap_skyscraper.jpg', '02056_construct_the_tallest_soap_skyscraper_thumb.jpg'),
(448, '|2088|', 8, '|3|9|', 2, 'Throw water the furthest', 'In this task, the contestants are instructed to throw some water as far as they can.', '02088_throw_water_the_furthest.jpg', '02088_throw_water_the_furthest_thumb.jpg'),
(449, '|1360|', 1, '|3|11|', 2, 'Prevent the Taskmaster\'s assistant from scoring a goal', 'In this task, the contestants must attempt to prevent the Taskmaster\'s assistant from scoring a goal with a football.', '01360_prevent_alex_from_scoring_a_goal.jpg', '01360_prevent_alex_from_scoring_a_goal_thumb.jpg'),
(450, '|2002|', 1, '|3|', 1, 'Predict how many cans you can fit in a bag', 'In this live task, the contestants must first predict how many cans they think they can fit into a bag.|They are then given a limited amount of time to fit exactly that number of cans into the bag.|The person who guesses the highest number and is able to fit exactly that many cans into their bag wins.', '02002_predict_how_many_cans_you_can_fit_in_a_bag.jpg', '02002_predict_how_many_cans_you_can_fit_in_a_bag_thumb.jpg'),
(451, '|211|', 1, '|3|8|11|', 3, 'Spin around and then get a ball into a goal', 'In this task, the contestants must spin around as many times as possible before getting a ball into a specific goal.|The spinning might be conducted while standing or on a rotating office chair, and the goal may be kicking a football into a caravan doorway, or at a caravan in its entirety, or throwing a basketball into a basketball hoop.|The task was originally used as a tie-breaker in season 6 of Taskmaster UK, but has since been adapted as a regular pre-filmed task on a couple of occasions, with one version switching out various details but essentially remaining the same.', '00211_spin_around_and_kick_a_football_at_the_caravan.jpg', '00211_spin_around_and_kick_a_football_at_the_caravan_thumb.jpg'),
(452, '|1963|', 1, '|1|3|', 3, 'Guess something about this person', 'In this live studio task, the contestants take it in turns to ask a stranger questions, to which they may only answer \'yes\' or \'no\', in order to identify something about them, such as their name, job, or age.', '01963_correctly_guess_the_persons_first_name.jpg', '01963_correctly_guess_the_persons_first_name_thumb.jpg'),
(453, '|1421|', 1, '|3|', 1, 'Play and commentate on a new sport', 'In this two-part team task, the contestants are first instructed to play one minute of an entirely new sport that they have created themselves.|In the second part of the task, they have to provide commentary for the footage of their sport.', '01421_play_and_commentate_on_a_socially_distanced_sport.jpg', '01421_play_and_commentate_on_a_socially_distanced_sport_thumb.jpg'),
(454, '|2081|', 8, '|3|', 1, 'Hide your toilet brush', 'In this live studio task, the contestants must choose to hide a toilet brush in a bag, or on their person.|The Taskmaster then attempts to guess where each of them have hidden it.|If the taskmaster guesses correctly, the contestant is eliminated.|The game is replayed until only one person remains.', '02081_hide_your_toilet_brush.jpg', '02081_hide_your_toilet_brush_thumb.jpg'),
(455, '|1696|', 9, '|3|', 1, 'Put on some trousers', 'In this task, the contestants must put on a pair of trousers.|The task is complicated by the fact that there are rules preventing them from using their hands.|These rules may be conditional to certain locations, and/or certain pairs of trousers.', '01696_put_the_trousers_on_correctly.jpg', '01696_put_the_trousers_on_correctly_thumb.jpg'),
(456, '|1944|', 1, '|3|11|', 2, 'Make a key difficult to retrieve', 'In this unscored task, which is carried out in preparation for a separate task shown later in the same episode, the contestants are instructed to make a key difficult, but not impossible, to retrieve.|The subsequent task of course necessitates that the contestants retrieve their key, in order to complete it, meaning that they have a great opportunity to make their own lives difficult.', '01944_make_a_key_difficult_to_retrieve.jpg', '01944_make_a_key_difficult_to_retrieve_thumb.jpg'),
(457, '|1896|', 1, '|3|6|9|', 3, 'Recreate a photo from your phone', 'In this two-part task, the contestants are first instructed to select a photo from their phone that meets a given criterion (e.g. coolest, or most powerful).|They are then instructed to accurately recreate that photo in a limited timeframe.', '01896_recreate_the_coolest_photo_from_your_phone.jpg', '01896_recreate_the_coolest_photo_from_your_phone_thumb.jpg'),
(458, '|2127|', 8, '|3|', 1, 'Scream the name of your crop', 'In this live studio task, the contestants must try to be the first to yell the name of a crop which is written on one of the tissues in a box in front of them.|To complicate matters, many of the other tissues in the box also have non-crop-related words written on them.', '02127_scream_the_name_of_your_crop.jpg', '02127_scream_the_name_of_your_crop_thumb.jpg'),
(459, '|837|', 1, '|6|9|11|13|', 4, 'Put the banana in the bottle', 'In this task, the contestants are instructed to get a banana into a bottle without breaking the bottle or removing it from the room.|This task is complicated by the fact that the banana is frozen, and the bottle is full of jelly.|The bottle also has a combination lock on its lid, but this is just a red herring, as the bottle is not locked.|The task may be complicated further by the fact that the bottle is smeared in vaseline.', '00837_get_all_of_the_banana_in_the_bottle.jpg', '00837_get_all_of_the_banana_in_the_bottle_thumb.jpg'),
(460, '|1152|', 8, '|3|6|', 2, 'Knock over all the pins without leaving the caravan', 'In this task, the contestants must knock over a rack of bowling pins without leaving a caravan.|The Taskmaster\'s assistant may not intentionally knock over the pins for them.', '01152_knock_over_all_the_pins_without_leaving_the_caravan.jpg', '01152_knock_over_all_the_pins_without_leaving_the_caravan_thumb.jpg'),
(461, '|1980|', 1, '|3|4|6|11|', 4, 'Have a conversation in a foreign language', 'In this task, the contestants are given a very limited time to prepare for a video chat conversation with someone who speaks a foreign language.|The contestants are provided with some tools to help them prepare, such as a translation dictionary, a computer or tablet, and pen and paper.|The task may be judged based on who best demonstrated their knowledge of the language, or on who had the \'nicest\' conversation.', '01980_learn_swedish.jpg', '01980_learn_swedish_thumb.jpg'),
(462, '|1948|', 1, '|3|', 1, 'Pop objects out of your hole', 'In this live studio task, the contestants must pop small spherical objects (e.g. tennis balls, or plastic eggs) out of holes in the front of bags they are wearing.|The goal is to be the first to pop a certain number of objects of a certain colour out.|Objects popped out which are not the desired colour lead to forfeits which must be performed by one or all of the contestants (e.g. screaming, or dancing).|There is also a single rubber-duck in each bag which, if popped out, leads to instant disqualification.', '01948_pop_balls_out_of_your_hole.jpg', '01948_pop_balls_out_of_your_hole_thumb.jpg'),
(463, '|2147|', 1, '|3|6|', 2, 'Don\'t pop the balloon', 'In this live studio task, the contestants must take it in turns to add specific items of clothing they are wearing to the box on the end of a see-saw, without being the one who overloads it, leading to a balloon being popped.', '02147_dont_pop_the_balloon.jpg', '02147_dont_pop_the_balloon_thumb.jpg'),
(464, '|1998|', 1, '|9|', 1, 'The best thing with a handle', 'In this prize task, the contestants must bring in the best thing with a handle.', '01998_the_best_object_with_a_handle.jpg', '01998_the_best_object_with_a_handle_thumb.jpg'),
(465, '|530|', 8, '|9|11|', 2, 'Completely colour a whiteboard', 'In this task, the contestants are presented with a dry-erase board and some dry-erase markers, and are instructed to completely colour the board.|The winner is the one who colours the board the fastest.', '00530_completely_colour_a_whiteboard.jpg', '00530_completely_colour_a_whiteboard_thumb.jpg'),
(466, '|1390|', 1, '|9|', 1, 'Make a cute toy for a cute dog', 'In this task, the contestants are provided with some dog-safe materials, and are instructed to create a cute toy for a dog.|The winner is the one whose toy most entertains the dog brought in later to test the toys.', '01390_make_a_cute_toy_for_a_cute_dog.jpg', '01390_make_a_cute_toy_for_a_cute_dog_thumb.jpg'),
(467, '|1982|', 1, '|3|11|', 2, 'Walk through the door wearing the longest shoes and biggest hat', 'In this task, the contestants must walk through a small door wearing the longest shoes and biggest hat.', '01982_walk_through_the_door_wearing_the_longest_shoes_and_biggest_hat.jpg', '01982_walk_through_the_door_wearing_the_longest_shoes_and_biggest_hat_thumb.jpg'),
(468, '|680|', 6, '|3|', 1, 'Take a picture from the farthest distance', 'In this task, the contestants are instructed to take a picture of themselves from the farthest distance.', '00680_take_a_picture_from_the_farthest_distance.jpg', '00680_take_a_picture_from_the_farthest_distance_thumb.jpg'),
(469, '|2061|', 8, '|3|4|', 2, 'Memorise the items on the poster', 'In this live studio task, the contestants are sent inside a small structure together  (e.g. a shed, tent, or outhouse), and are given a short amount of time to memorise the things depicted on a poster within (e.g. species of fish or birds, or objects from the house where tasks are performed).|The contestants must then take it in turns to correctly recall the names of the things depicted on the poster, and are eliminated if they name an incorrect item, repeat something already named, or can\'t think of one.', '02061_memorise_the_fish.jpg', '02061_memorise_the_fish_thumb.jpg'),
(470, '|2100|', 8, '|3|9|', 2, 'Become a superhero', 'In this task, the contestants are instructed to become an original superhero.|In some versions of the task, they are also instructed to save someone (e.g. the Taskmaster\'s assistant, or a baby doll).', '02100_become_a_superhero_and_save_paul.jpg', '02100_become_a_superhero_and_save_paul_thumb.jpg'),
(471, '|1935|', 3, '|1|6|11|', 3, 'Task bingo', 'In this task, the contestants are presented with a grid of tasks as a giant bingo card, and must complete enough tasks to make a line (or complete all four corners, in some versions).|In some versions of the task, they get to choose which tasks they do in which order whereas, in others, the order is chosen for them by chance, using a bingo machine.', '01935_task_bingo.jpg', '01935_task_bingo_thumb.jpg'),
(472, '|1389|', 1, '|3|11|', 2, 'Land the iron on the ironing board', 'In this task, the contestants are instructed to land an iron on an ironing board from as far away as possible.', '01389_land_the_iron_on_the_ironing_board.jpg', '01389_land_the_iron_on_the_ironing_board_thumb.jpg'),
(473, '|1456|', 1, '|3|11|', 2, 'Have the longest telephone conversation', 'In this task the contestants must try to have the longest phone conversation while completing a series of challenges chosen from a board at random.|If the person they\'re calling uses any of the predesignated keywords associated with the challenges, they have to hang up immediately.', '01456_have_the_longest_telephone_conversation.jpg', '01456_have_the_longest_telephone_conversation_thumb.jpg'),
(474, '|1366|', 4, '|3|', 1, 'Get the lowest number of \'yes\'s from the audience', 'In this live studio task, the contestants must pose questions to the audience, attempting to get the least affirmative responses.', '01366_get_the_lowest_number_of_yess_from_the_audience.jpg', '01366_get_the_lowest_number_of_yess_from_the_audience_thumb.jpg'),
(475, '|1908|', 1, '|3|6|9|11|13|', 5, 'Make all the things happen at the same time', 'In this task, the contestants are presented with a number of toys, and have to get them all to be active at the same time.', '01908_make_all_the_things_happen_at_the_same_time.jpg', '01908_make_all_the_things_happen_at_the_same_time_thumb.jpg'),
(476, '|2229|', 4, '|3|', 1, 'Taskmaster\'s Whac-a-Mole', 'In this live studio task, the Taskmaster is stood in the centre of a ring-shaped table, which is covered with fabric, and has five holes in it, through which the contestants (who are hidden beneath) can pop their heads.|The Taskmaster holds a soft club, with which they can bash the contestants on their heads.|The contestants are instructed to make a distinct animal noise, each time they pop up.|If they are hit, the contestants are eliminated.|The winner is the contestant who pops their head up the most times.', '02229_the_kings_whac_a_mole.jpg', '02229_the_kings_whac_a_mole_thumb.jpg'),
(477, '|1458|', 1, '|3|6|9|11|13|', 5, 'Get goosebumps', 'In this task, the contestants are instructed to give themselves goosebumps. The fastest to do so wins.', '01458_get_goosebumps.jpg', '01458_get_goosebumps_thumb.jpg'),
(478, '|2103|', 8, '|1|3|', 2, 'Pop something the furthest', 'In this task, the contestants must attempt to pop something the furthest - either shooting a cork from a champagne bottle, or popping a party popper as far as possible.', '02103_pop_the_champagne_cork.jpg', '02103_pop_the_champagne_cork_thumb.jpg'),
(479, '|2183|', 1, '|3|6|', 2, 'Play your sounds right', 'In this live studio task, the contestants must estimate whether the next sound to be made by the Taskmaster will be louder or quieter than the previous one.', '02183_play_your_sounds_right.jpg', '02183_play_your_sounds_right_thumb.jpg'),
(480, '|2186|', 1, '|3|11|', 2, 'Get the tarpaulin into one of the containers', 'In this task, the contestants must select a container, and then pack a large tarpaulin into that container, cleaning up any mess they make along the way.|Each container is at least partly full with other items already.', '02186_get_the_tarpaulin_into_one_of_the_containers.jpg', '02186_get_the_tarpaulin_into_one_of_the_containers_thumb.jpg'),
(481, '|1679|', 1, '|6|9|', 2, 'Turn a ball into a competitor\'s head', 'In this live studio task, the contestants are first instructed to select one of a variety of balls provided.|They are then told to make the ball look like one of the other contestants, and are provided with a variety of craft supplies to help them do this.|The best ball head wins.', '01679_turn_a_ball_into_a_competitors_head.jpg', '01679_turn_a_ball_into_a_competitors_head_thumb.jpg'),
(482, '|1678|', 1, '|3|4|6|', 3, 'Pass a long object through all the obstacles', 'In this task, the contestants must carry or pass a long object (e.g. an extendible pole, a flagpole, or a plank) through either an obstacle course, or a collection of objects, trying not to allow the long object to touch anything.|In some versions, the contestants get to choose the starting length of the object (either by extending it to the desire length, or by sawing off part of it), and then each time the object touches something, they lose part of its length (either the length is reduced at the end of the task, or they have to physically remove part of it, each time). In these versions, the winner of the task is the person who completes the challenge with the longest remaining length of the object.|In other versions, the contestants do not get to choose the starting length of the object, and the goal is to complete the task as quickly as possibly, with each incident of the item touching something incurring a time penalty instead.', '01678_navigate_the_course_with_the_pole.jpg', '01678_navigate_the_course_with_the_pole_thumb.jpg'),
(483, '|1926|', 1, '|3|11|', 2, 'Give the Taskmaster\'s assistant the best mini stag party', 'In this task, the contestants must organise and give the Taskmaster\'s assistant the best stag party, lasting a very short time (e.g. one minute, or 100 seconds).', '01926_give_alex_the_best_stag_minute.jpg', '01926_give_alex_the_best_stag_minute_thumb.jpg'),
(484, '|1925|', 1, '|3|6|11|', 3, 'Guess Shoe', 'In this task, the contestants must identify which shoe the Taskmaster\'s assistant is thinking of, from a room full of shoes.|The contestant may only ask the assistant \'yes\' or \'no\' questions, and must repeat a predesignated phrase, each time the assistant gives them an answer.|At the end of the task, the shoe identified must be presented in the room, with no other shoes visible.', '01925_guess_shoe.jpg', '01925_guess_shoe_thumb.jpg'),
(485, '|1869|', 1, '|3|11|', 2, 'Create a lipstick portrait', 'In this task, the contestants are provided with lipsticks in a variety of colours and a blank canvas, and must create a portrait of either the Taskmaster, or their assistant.|The contestants are only permitted to apply the lipstick to the canvas using their lips.|The best portrait wins.', '01869_create_a_lipstick_portrait_of_the_taskmaster.jpg', '01869_create_a_lipstick_portrait_of_the_taskmaster_thumb.jpg'),
(486, '|1867|', 1, '|9|', 1, 'The thing you\'d be most excited to find ', 'In this prize task, the contestants must bring in the thing that they\'d be most excited to find (e.g. in a skip, or on the street).', '01867_the_most_exciting_thing_to_be_found_in_a_skip.jpg', '01867_the_most_exciting_thing_to_be_found_in_a_skip_thumb.jpg'),
(487, '|735|', 1, '|9|', 1, 'Identify how applicable the statement is', 'In this live studio task, the contestants must determine how applicable a series of statements are to themselves and their fellow contestants.|They must then hold up a paddle to either indicate where they feel they rank, within the group, or which contestant they feel the statement is most applicable to.', '00735_correctly_guess_your_standing_in_the_group.jpg', '00735_correctly_guess_your_standing_in_the_group_thumb.jpg'),
(488, '|2399|', 4, '|9|', 1, 'The thing you most often lose', 'In this prize task, the contestants must bring in something that they often lose.', '02399_the_thing_you_most_often_lose.jpg', '02399_the_thing_you_most_often_lose_thumb.jpg'),
(489, '|498|', 8, '|9|', 1, 'Make this tree attractive', 'In this task, the contestants are instructed to make a tree as attractive, or sexy, as possible.', '00498_make_a_tree_sexy.jpg', '00498_make_a_tree_sexy_thumb.jpg'),
(490, '|1898|', 1, '|9|', 1, 'Draw the object under your table', 'IN this live task, the contestants are instructed to draw an unknown object placed beneath their table, using only their sense of touch to identify it.|In some versions, they are also instructed to write down some words to describe the object.|The contestants must also stare at the Taskmaster throughout the task.', '01898_draw_and_describe_the_object_under_your_table.jpg', '01898_draw_and_describe_the_object_under_your_table_thumb.jpg'),
(491, '|1364|', 4, '|6|9|', 2, 'Sort the coloured sweets', 'In this task, the contestants are provided with a large bowl full of multi-coloured sweets, and a number of smaller bowls which are colour-coded in line with the sweets, and are instructed to sort them \'correctly\'.|There is actually no correct interpretation of how they must be sorted, but the contestants\' solutions must work within whatever rule they have decided for themselves.|In some versions of the task, the contestants are given a second thing that they must think about while doing this, to complicate matters.', '01364_sort_the_coloured_sweets.jpg', '01364_sort_the_coloured_sweets_thumb.jpg'),
(492, '|1478|', 1, '|6|', 1, 'Propose to the Taskmaster\'s assistant', 'In this task, the contestants must propose to the Taskmaster\'s assistant in an irresistible way.', '01478_propose_to_alex.jpg', '01478_propose_to_alex_thumb.jpg'),
(493, '|1946|', 1, '|9|11|13|', 3, 'Raise the water level to the top of the fish tank', 'In this task, the contestants must add six items to a large fish tank containing water, in order to raise the water level to its brim.', '01946_raise_the_water_level_to_the_top_of_the_fish_tank.jpg', '01946_raise_the_water_level_to_the_top_of_the_fish_tank_thumb.jpg'),
(494, '|855|', 1, '|6|', 1, 'Make the best babushka meal', 'In this task, the contestants are instructed to make the best Make the best \'babushka meal\' (i.e. a meal consisting of nested elements, in the manner of a matryoshka doll) and serve it to the Taskmaster\'s assistant.', '00855_make_the_best_babushka_meal.jpg', '00855_make_the_best_babushka_meal_thumb.jpg'),
(495, '|448|', 1, '|3|6|', 2, 'Draw an object on a rotating canvas', 'In this live team task, the contestants must take it in turns to convey an object to their team-mates by drawing on a canvas while it is rotating on a turntable.', '00448_draw_an_object_on_a_rotating_canvas.jpg', '00448_draw_an_object_on_a_rotating_canvas_thumb.jpg'),
(496, '|2240|', 1, '|3|6|', 2, 'Blow a sphere off of the plinth', 'In this live studio task, the contestants are provided with a series of spherical objects, and a series of items which can be used to expel air, and are instructed to blow one of the spheres off of a plinth and onto a platform on the stage.|If the sphere ends up falling off the platform, the contestant is eliminated.|The contestant whose sphere ends up travelling the shortest distance may also be eliminated.', '02240_blow_an_item_onto_the_knappett.jpg', '02240_blow_an_item_onto_the_knappett_thumb.jpg'),
(497, '|1181|', 8, '|6|9|', 2, 'Transform the lab while the lights are out', 'In this task, the contestants have a very short amount of time in which to transform the lab as spectacularly, or unexpectedly, as possible, while the lights are out.', '01181_transform_the_lab_while_the_lights_are_out.jpg', '01181_transform_the_lab_while_the_lights_are_out_thumb.jpg'),
(498, '|851|', 1, '|6|11|', 2, 'Tie the string to the glasses and put them on', 'In this live studio task, the contestants have to open a toolbox, inside which there are a pair of glasses and a length of string inside a balloon.|The toolbox is secured using a combination lock, and the Taskmaster slowly reveals clues to the code needed to open it.|The winner of the task is the first person to tie the string to both arms of the glasses and put them on.', '00851_tie_the_string_and_put_on_the_glasses.jpg', '00851_tie_the_string_and_put_on_the_glasses_thumb.jpg'),
(499, '|1302|', 1, '|6|', 1, 'Build a sand bridge across the river', 'In this task the contestants are instructed to build a sand bridge across the river of a miniature model of a pastoral scene.|The bridge must be able to support the weight of an egg, and the egg must also be able to pass beneath the bridge.|There is a clue provided on the table which may lead the contestants to discovering some hidden building supplies within the table upon which the model itself sits. However, these building supplies are generally not actually that helpful.', '01302_make_a_sand_bridge_across_the_river.jpg', '01302_make_a_sand_bridge_across_the_river_thumb.jpg'),
(500, '|1306|', 4, '|6|', 1, 'Get the teddy bear from start to finish', 'In this task, the contestants are instructed to get a giant teddy bear from a start line to a nearby finish line, while remaining behind the start line themselves.|The contestant who is able to most quickly transport the bear from start to finish wins.', '01306_get_the_teddy_bear_from_start_to_finish.jpg', '01306_get_the_teddy_bear_from_start_to_finish_thumb.jpg'),
(501, '|2286|', 1, '|3|6|13|', 3, 'Get your towel into your bucket', 'In this live studio task, the contestants are first instructed to tie a towel around themselves as tightly as possible, and then put their hands on their heads.|They are then provided with a bucket each, and instructed to put the towel completely inside the bucket, while keeping their hands on their heads.|The contestant who completes the task fastest wins.', '02286_get_your_towel_in_your_bucket.jpg', '02286_get_your_towel_in_your_bucket_thumb.jpg'),
(502, '|1806|', 4, '|3|6|8|', 3, 'Convince the kid(s) that you’re the coolest', 'In this task, the contestants are instructed to convince one or more kids that they are the coolest contestant.|In some versions, they must impress a group of pre-teen kids, while in others there is a single teenager to convince.', '01806_convince_the_kids_that_youre_the_coolest.jpg', '01806_convince_the_kids_that_youre_the_coolest_thumb.jpg'),
(503, '|2209|', 1, '|3|6|9|11|', 4, 'Communicate animals by saying letters and doing impressions', 'In this live team task, one member of each team is first instructed to write a list of ten animals on a board.|A member of each team must then communicate the animals written by the opposing team to their own team members, by miming the animals, and saying the letter which comes before the first letter of that animal\'s name, in the alphabet.', '02209_communicate_animals_by_saying_letters_and_doing_impressions.jpg', '02209_communicate_animals_by_saying_letters_and_doing_impressions_thumb.jpg'),
(504, '|1122|', 3, '|8|', 1, 'Quickly follow the very first instruction', 'In this task, the contestants are presented with a very long task brief, which they may feel compelled to read the entirety of, but in which the essential instructions are within the first few words.|The contestant who spots the trick and obeys the first instruction fastest wins.', '01122_drop_the_letter.jpg', '01122_drop_the_letter_thumb.jpg'),
(505, '|1924|', 1, '|8|', 1, 'The best night-time thing', 'In this prize task, the contestants must bring in the best thing to have at night.', '01924_the_best_night_time_thing.jpg', '01924_the_best_night_time_thing_thumb.jpg'),
(506, '|2114|', 8, '|1|3|4|6|9|11|14|', 8, 'Find and complete the real task', 'In this task, the contestants are presented with an overwhelming number of task briefs, but only one of them has the instructions for the actual task they are trying to complete, while all the others have text indicating that they are not the correct one.|The task briefs may be written in a variety of different languages to confuse matters.|The actual task is something simple such as thanking the Taskmaster\'s assistant, or whistling, so it is possible for the contestants to successfully complete the task without knowing how.', '02114_say_thank_you_to_paul.jpg', '02114_say_thank_you_to_paul_thumb.jpg'),
(507, '|854|', 1, '|6|9|11|13|', 4, 'Complete the most tasks', 'In this task, the contestants must complete as many mini-tasks as possible within a given time.|The mini-tasks consist of simple verb-noun pairings which often begin with consecutive letters of the alphabet, and which are written on a large piece of paper, rather than the usual sealed task brief.|The mini-tasks each relate to an object which is presented nearby.|As the contestants start reading the brief, the assistant destroys the paper - either by lighting a fuse which burns the whole thing up after a short delay, or by turning on a shredder.|The challenge of the task is therefore to try to quickly memorise the mini-task briefs in a limited time.', '00854_complete_the_most_tasks.jpg', '00854_complete_the_most_tasks_thumb.jpg'),
(508, '|2122|', 8, '|1|3|', 2, 'Human war boats', 'In this live team task, which is clearly based on the popular board game Battleships, the teams must try to eliminate one another by throwing pillows over a tall screen to hit one another.|The rules of the game vary: in one version, all members of each team lie down in turn until the opposing team manage to hit all of them with their multiple pillows, and the winning team is the one which made the least throws; in another, only one member of each team lies down across three grid squares, and the teams then take turns in firing a single cushion over the screen, while their misses and hits are logged on chalkboards for them by Alex, with the winning team being the first to hit all three occupied grid squares.', '02122_human_war_boats.jpg', '02122_human_war_boats_thumb.jpg'),
(509, '|2071|', 9, '|4|', 1, 'Guess how many \'S\'s were in the task brief', 'In this live studio task, the contestants are first given a task brief which is actually not what they will be judged on, and are then asked to recall how many letter \'S\'s there were in that task brief.', '02071_guess_how_many_ss_were_in_the_task_brief.jpg', '02071_guess_how_many_ss_were_in_the_task_brief_thumb.jpg'),
(510, '|1626|', 4, '|6|', 1, 'Put the most balls in the tube', 'In this task, the contestants must try to get as many balls as possible into an open-bottomed tube which is suspended from the ceiling.', '01626_put_the_most_balls_in_the_tube.jpg', '01626_put_the_most_balls_in_the_tube_thumb.jpg'),
(511, '|532|', 8, '|1|3|6|', 3, 'Make a pleasant sausage', 'In this task, the contestants have to make a pleasant sausage using ingredients they have chosen with names that begin with the letters of the word \'sausage\' (or the equivalent in another language).', '00532_make_a_surprisingly_pleasant_sausage.jpg', '00532_make_a_surprisingly_pleasant_sausage_thumb.jpg'),
(512, '|536|', 8, '|4|11|', 2, 'Commit a crime', 'In this task, the contestants must commit a crime or break a rule. The best crime or clearest rule-breaking wins.', '00536_commit_a_crime_without_breaking_the_law.jpg', '00536_commit_a_crime_without_breaking_the_law_thumb.jpg'),
(513, '|300|', 1, '|13|', 1, 'The most exciting thing beginning with \'G\'', 'In this prize task, the contestants must bring in the most exciting thing beginning with \'G\'.', '00300_the_most_exciting_thing_beginning_with_g.jpg', '00300_the_most_exciting_thing_beginning_with_g_thumb.jpg'),
(514, '|321|', 1, '|13|', 1, 'Recreate a classic video game', 'In this task, the contestants are instructed to physically recreate a classic video game.', '00321_recreate_a_classic_video_game.jpg', '00321_recreate_a_classic_video_game_thumb.jpg'),
(515, '|458|', 1, '|11|13|', 2, 'Feed your team-mate(s) the most watermelon', 'In this team task, the contestants must feed one another the most watermelon in a limited timeframe.|In the original version of the task, the contestants were allowed to feed one another from close range using their hands. However, the second team to film that task had to do so under social distancing rules during the Covid-19 pandemic, and thus had to feed one another from a distance using litter-pickers. This adaptation subsequently became the standard set-up for the task, when it was re-used by other shows in the franchise.', '00458_feed_your_team_mate_the_most_watermelon.jpg', '00458_feed_your_team_mate_the_most_watermelon_thumb.jpg'),
(516, '|759|', 4, '|4|6|11|', 7, 'Say the most unique words', 'In this task, the contestants are given a limited period of time to say as many unique words as possible.|Sometimes, constraints are given about what types of words they should list, such as specifying that they should not contain a certain letter, or should be of a specific length.', '02227_say_the_most_unique_words.jpg', '02227_say_the_most_unique_words_thumb.jpg'),
(517, '|92|', 1, '|11|13|', 2, 'Do something that looks impressive in high speed or slow-motion', 'In this task, the contestants must do something that will look impressive when played back at high speed or in slow-motion.', '00092_create_an_impressive_time_lapse_or_slow_motion_film.jpg', '00092_create_an_impressive_time_lapse_or_slow_motion_film_thumb.jpg'),
(518, '|359|', 1, '|13|', 1, 'The best slippery thing', 'In this prize task, the contestants must bring in the best, or most slippery thing.', '00359_the_best_slippery_thing.jpg', '00359_the_best_slippery_thing_thumb.jpg'),
(519, '|2659|', 8, '|4|', 1, 'Complete an objective while keeping a balloon aloft', 'In this live studio task, the contestants are given an objective to complete while also keeping an inflated ball aloft, by bouncing it.', '02659_correctly_don_your_surgical_gear_while_keeping_a_balloon_aloft.jpg', '02659_correctly_don_your_surgical_gear_while_keeping_a_balloon_aloft_thumb.jpg'),
(520, '|272|', 1, '|13|', 1, 'Paint a blindfolded still life', 'In this team task, one of the contestants must paint a still life while blindfolded, guided by their team-mates, who may only use certain words to direct them.', '00272_paint_a_blindfolded_still_life.jpg', '00272_paint_a_blindfolded_still_life_thumb.jpg'),
(521, '|2461|', 1, '|11|13|', 2, 'Put a ball of string on the cushion', 'In this task, the contestants find instructions on the task brief telling them to unwind a ball of string as fast as possible. However, the instructions on the back of the task brief contradict this, telling them that the actual goal of the task is to place a neatly wound ball of string on a cushion as quickly as possible.', '02461_put_a_ball_of_string_on_the_cushion.jpg', '02461_put_a_ball_of_string_on_the_cushion_thumb.jpg'),
(522, '|1228|', 8, '|1|3|4|11|13|14|', 8, 'Work as a team / Sabotage your team', 'In this team task, the contestants must try to complete a physical task as a team (e.g. relocating balloons, sand, cans, or water from one place to another, constructing a bridge, recreating a landmark, or choreographing a synchronised dance).|This is sometimes complicated with the requirement that half of their hands must be placed on half of their hips at all times.|Usually, one contestant on any team of three is given a secret task to sabotage their team\'s attempt in some way. However, there have also been instances in which there is a saboteur on both teams, or where everyone, or all but one of the contestants, has secretly been tasked to sabotage their team\'s effort.|Usually, the saboteurs success comes at the cost of their team\'s success, but there have also been instances where the saboteur\'s success benefits their team.', '02180_put_the_most_sand_in_the_shopping_trolley.jpg', '02180_put_the_most_sand_in_the_shopping_trolley_thumb.jpg'),
(523, '|2237|', 1, '|3|4|6|11|', 4, 'Pop 99 red balloons', 'In this task, the contestants are first instructed to choose from a selection of predesignated weapons, and from a selection of predesignated locations in the Taskmaster house.|They are then instructed to burst exactly 99 balloons as quickly as possible.|Those who burst more or fewer than 99 balloons are either disqualified or earn a time penalty.', '02237_pop_99_red_balloons.jpg', '02237_pop_99_red_balloons_thumb.jpg'),
(524, '|2099|', 8, '|1|3|6|', 3, 'Complete the fortune trail', 'In this task, the contestants must complete a series of mini-tasks themed around luck and superstition, which ends with them trying to flip five consecutive heads with a coin.|Each of the mini tasks gives them an opportunity to find a \'lucky\' double-headed coin, which would make the final step very much easier.', '02099_complete_the_fortune_trail_and_flip_five_heads.jpg', '02099_complete_the_fortune_trail_and_flip_five_heads_thumb.jpg'),
(525, '|1232|', 8, '|6|', 1, 'Plant the umbrella in the right spot', 'In this task, the contestants are provided with a set of directions and distances they must travel, and they then have to plant an umbrella or parasol in the spot they arrive at.|The winner of the task is the person who plants their umbrella/parasol closest to the correct spot.|The trick of the task is that, if followed correctly, the directions will lead them back to the starting point.', '01232_plant_the_umbrella_in_the_right_spot.jpg', '01232_plant_the_umbrella_in_the_right_spot_thumb.jpg'),
(526, '|1476|', 1, '|6|9|11|13|', 4, 'Drink with your mouth open', 'In this task, the contestants are instructed to drink an entire pint of something (usually blackcurrant squash) while keeping their mouth open at all times.|The contestant who does so fastest wins.', '01476_drink_with_your_mouth_open.jpg', '01476_drink_with_your_mouth_open_thumb.jpg'),
(527, '|121|', 1, '|6|', 1, 'Do incompatible things with a bathtub', 'In this team task, the contestants are each given different and somewhat conflicting instructions as to what they need to achieve with a bathtub.|Typically, one must fill it with as many objects as possible, while another contestant has been instructed to cover it in plastic wrap.|Where there is a third member on the team, they are instructed to fill the bath with water.', '00121_do_incompatible_things_with_the_bathtub.jpg', '00121_do_incompatible_things_with_the_bathtub_thumb.jpg'),
(528, '|1928|', 1, '|6|', 1, 'Knock over your opponents’ dolls with a tyre', 'In this live task, the contestants must attempt to knock over inflatable dolls of their opponents by rolling bicycle tyres at them.', '01928_knock_over_your_opponents_dolls_with_a_tyre.jpg', '01928_knock_over_your_opponents_dolls_with_a_tyre_thumb.jpg'),
(529, '|2377|', 14, '|4|', 1, 'The thing you\'d most like to be buried with', 'In this prize task, the contestants must bring in the thing they most like to be buried with.', '02377_the_thing_youd_most_like_to_be_buried_with.jpg', '02377_the_thing_youd_most_like_to_be_buried_with_thumb.jpg'),
(530, '|1138|', 3, '|3|4|', 2, 'Identify who is wearing the costume', 'In this task, the contestants must attempt to identify which celebrity is wearing a costume (e.g. an Easter bunny costume, or Santa Claus costume), by asking \'yes\' or \'no\' questions.', '01138_identify_the_easter_bunny.jpg', '01138_identify_the_easter_bunny_thumb.jpg'),
(531, '|336|', 1, '|13|', 1, 'The most burstable/explosive thing', 'In this prize task, the contestants must bring in the most burstable or explosive thing.', '00336_the_best_burstable_thing.jpg', '00336_the_best_burstable_thing_thumb.jpg'),
(532, '|159|', 1, '|13|', 1, 'Make a coconut businessman', 'In this filmed task, the contestants must make a coconut into a businessman.', '00159_make_a_coconut_businessman.jpg', '00159_make_a_coconut_businessman_thumb.jpg'),
(533, '|144|', 1, '|1|3|6|7|9|11|14|', 8, 'Do something unexpected with a mundane item', 'In this task, the contestants are instructed to do something unexpected (though it may be worded as \'surprising\', \'preposterous\', \'shocking\', or \'breath-taking\') with a mundane item (such as a rubber duck, a chick pea, a doughnut, some lemons, or a root vegetable).', '00144_do_something_surprising_with_a_duck.jpg', '00144_do_something_surprising_with_a_duck_thumb.jpg'),
(534, '|460|', 1, '|13|', 1, 'The most narcissistic thing', 'In this prize task, the contestants must bring in the most narcissistic thing.', '00460_the_most_narcissistic_thing.jpg', '00460_the_most_narcissistic_thing_thumb.jpg'),
(535, '|838|', 1, '|11|13|', 2, 'Place the bag of salt on the table', 'In this team task, the contestants must transport a bag of salt to a table while tethered together with ropes.|The contestants have to restart their attempt if they move while holding the bag, touch the rope or belts, or if the bag or the bells suspended on the ropes touch the ground.|Also the bag they first see at the start of the task turns out to contain sugar, and not salt (the bag containing salt is hidden just out of view).', '00838_put_the_bag_of_salt_onto_that_table.jpg', '00838_put_the_bag_of_salt_onto_that_table_thumb.jpg'),
(536, '|475|', 1, '|13|', 1, 'Stare at your opponent without blinking', 'In this live studio task, the contestants must try to stare each other out while putting on an expression or acting out a scenario chosen by the Taskmaster.|The first contestant to blink loses each round.', '00475_do_not_blink_while_staring_at_your_opponent.jpg', '00475_do_not_blink_while_staring_at_your_opponent_thumb.jpg'),
(537, '|2421|', 14, '|3|', 1, 'Reinvent the wheel', 'In this task, the contestants are provided with a vehicle which is missing one wheel, and have to find a replacement for the wheel so that the vehicle can be driven to the end of the course.', '02421_reinvent_the_wheel.jpg', '02421_reinvent_the_wheel_thumb.jpg'),
(538, '|2405|', 14, '|3|9|', 2, 'Protect the popcorn', 'In this task, the contestants must protect a box of popcorn from the Taskmaster\'s assistant, without attacking or restraining them.', '02405_protect_the_popcorn.jpg', '02405_protect_the_popcorn_thumb.jpg'),
(539, '|2434|', 14, '|3|', 1, 'Dunk your biscuit', 'In this live task, the contestants must dunk a selected biscuit into a beverage as many times as possible without it falling apart.', '02434_dunk_your_biscuit.jpg', '02434_dunk_your_biscuit_thumb.jpg'),
(540, '|2594|', 1, '|3|', 1, 'Make these things the same colour', 'In this team task, the contestants must make two sets of fruits and vegetables match each other, by painting one or both sets of them.|Everyone must remain in the positions in which they start the task.|The paints are held by certain team members, where they must remain.', '02594_make_these_things_the_same_colour.jpg', '02594_make_these_things_the_same_colour_thumb.jpg'),
(541, '|2485|', 14, '|3|', 1, 'Stick a pickle to the bullseye', 'In this live task, the contestants must attempt to stick a slice of pickle to the bullseye of a target by throwing it.|They have to perform forfeits each time they miss the bullseye, depending on which ring of the target the pickle lands within.', '02485_stick_a_pickle_to_the_bullseye.jpg', '02485_stick_a_pickle_to_the_bullseye_thumb.jpg'),
(542, '|1248|', 4, '|1|3|', 3, 'Get something onto someone from a distance', 'In this task, the contestants are instructed to get something (e.g. a hat or a ring) onto part of someone (e.g. their head or finger) from as far away as possible.|The target may be the Taskmaster\'s assistant, or even a statue of the Taskmaster themself.', '01248_get_a_hat_on_ollis_head.jpg', '01248_get_a_hat_on_ollis_head_thumb.jpg'),
(543, '|1730|', 8, '|1|6|11|', 3, 'Do something stupid', 'In this task, the contestants are instructed to do the stupidest thing.', NULL, NULL),
(544, '|1285|', 4, '|6|8|', 2, 'Put these things in order', 'In this task, the contestants are presented with a seemingly random collection of objects, and must determine the correct order in which they should be arranged.|The correct order for the objects is based on association and/or plays on words.|In some versions, the objects are chosen because they either start with - or sound like they start with - the numbers one through five, and the correct order is thus numerical, based on their names.|In other versions, the objects are chosen to represent the planets of the solar system, and the correct order is the order of those planets.', '01285_put_these_things_in_order.jpg', '01285_put_these_things_in_order_thumb.jpg'),
(545, '|1249|', 4, '|3|', 1, 'Consume one of the five delicacies', 'In this task, the contestants are presented with five \'delicacies\', and must choose to consume one of them in its entirety.|Whoever consumes the item that the fewest other contestants have eaten wins.', '01249_eat_or_drink_one_of_the_five_delicacies.jpg', '01249_eat_or_drink_one_of_the_five_delicacies_thumb.jpg'),
(546, '|514|', 8, '|3|', 1, 'Transfer soup from one pot to another', 'In this two-part team task, the contestants must first gather equipment to use in the second part of the task, with no idea what it will involve.|In the second part of the task, they must use that equipment to transport soup from one vat to another, through their own designated areas.', '00514_transfer_soup_from_one_vat_to_another.jpg', '00514_transfer_soup_from_one_vat_to_another_thumb.jpg'),
(547, '|2260|', 1, '|3|', 1, 'Guess the lengths of the extendable items', 'In this live studio task, the contestants must estimate how far a series of extendable objects will extend across the stage.', '02260_guess_the_length_of_the_extendible_item.jpg', '02260_guess_the_length_of_the_extendible_item_thumb.jpg'),
(548, '|1226|', 8, '|6|', 1, 'Build a tower using onions', 'In this task, the contestants must try to build the tallest tower using just onions.|The contestant who delivers the most moving speech during the process earns a height bonus for their tower.', '01226_build_a_tower_using_onions.jpg', '01226_build_a_tower_using_onions_thumb.jpg'),
(549, '|1550|', 3, '|6|', 1, 'Create the biggest cream explosion', 'In this task, the contestants are provided with a pot of cream (e.g. crème fraiche or sour cream), and must try to create the biggest explosion with it.', '01550_create_the_biggest_creme_fraiche_explosion.jpg', '01550_create_the_biggest_creme_fraiche_explosion_thumb.jpg'),
(550, '|1868|', 1, '|3|6|11|', 3, 'Find all the items in the lab', 'In this filmed task, the contestants are instructed to find as many of a specific item (e.g. ducks or socks) in the apparently empty lab as possible.|The items are cleverly hidden around the lab, in and under the table, on the Taskmaster\'s assistant, and even on the contestants themselves.', '01868_find_all_ten_ducks_in_the_lab.jpg', '01868_find_all_ten_ducks_in_the_lab_thumb.jpg'),
(552, '|2549|', 1, '|3|6|', 2, 'Fake something', 'In this task, the contestants are instructed to fake something.', '02549_fake_something.jpg', '02549_fake_something_thumb.jpg'),
(553, '|506|', 8, '|3|', 1, 'Write an anonymous poem to the Taskmaster', 'In this live task, the contestants must write an anonymous poem for the Taskmaster.', '00506_wrote_the_taskmaster_an_anonymous_poem.jpg', '00506_wrote_the_taskmaster_an_anonymous_poem_thumb.jpg'),
(554, '|2520|', 1, '|3|', 1, 'Make the fastest egg boat', 'In this task, the contestants must make a boat for an egg using five items they have chosen, which all begin with the same letter.|The boats are then released together in a stream, and points are assigned based on how the order in which they cross a finish line.', '02520_make_the_fastest_egg_boat.jpg', '02520_make_the_fastest_egg_boat_thumb.jpg'),
(555, '|1210|', 8, '|3|6|', 2, 'Spill the beans', 'In this task, the contestants must spill the beans from a tin can of beans, hidden among a large number of other cans which do not contain beans.|Clues to the correct can may be provided, such as by having the bottom of some cans coloured to form an arrow, visible from beneath, through the glass table surface.', '01210_spill_the_beans.jpg', '01210_spill_the_beans_thumb.jpg'),
(556, '|2297|', 1, '|3|', 1, 'Land a balloon near the Taskmaster', 'In this live studio task, the contestants have long inflated balloons attached to a belt worn around their waist, and must take turns attempting to release them so that they land as close to the Taskmaster\'s chair as possible.|If they hit the Taskmaster with a balloon, or their balloon lands the furthest away from the chair, they are eliminated from the round. The last contestant standing wins.', '02297_land_a_balloon_near_the_taskmaster.jpg', '02297_land_a_balloon_near_the_taskmaster_thumb.jpg'),
(557, '|2600|', 1, '|3|11|', 2, 'Do what the Taskmaster\'s assistant does', 'In this task, the contestants must repeat a series of actions performed by the Taskmaster\'s assistant, after they complete each one.|For each action they do not complete, 10 seconds are added to their time.|The winner of the task is the one whose ending time is the closest to that of the Taskmaster\'s assistant.', '02600_do_what_alex_does.jpg', '02600_do_what_alex_does_thumb.jpg'),
(558, '|2124|', 8, '|1|3|', 2, 'Create a new game show', 'In this team task, the contestants must come up with a format for a new game show. In some versions, they must incorporate an object selected at random as the sponsor of the show.', '02124_make_an_electrifying_new_game_show.jpg', '02124_make_an_electrifying_new_game_show_thumb.jpg'),
(559, NULL, 1, '|3|6|', 2, 'Deliver compliments to the Taskmaster', 'In this live studio task, the contestants must try to deliver compliments to the Taskmaster by writing them on eggs, and transporting them to the Taskmaster using radio-controlled toy cars.', '02685_deliver_three_compliments_to_the_taskmaster.jpg', '02685_deliver_three_compliments_to_the_taskmaster_thumb.jpg'),
(560, '|2383|', 4, '|3|', 1, 'Place the most weight on some eggs', 'In this task, the contestants have to place as much weight as possible on some eggs.|Each egg that breaks leads to 10kg being subtracted from their total weight.', '02383_place_the_most_weight_on_the_eggs.jpg', '02383_place_the_most_weight_on_the_eggs_thumb.jpg'),
(561, '|2188|', 1, '|3|11|', 2, 'Egg and spoon throw', 'In this live studio task, the contestants must throw eggs and spoons, and try to land them as close together as possible on a runway extension to the stage.|The contestant whose egg and spoon are furthest apart in each round is eliminated.|Contestants are also eliminated if their egg or spoon falls off of the runway.', '02188_egg_and_spoon_throw.jpg', '02188_egg_and_spoon_throw_thumb.jpg'),
(562, '|2709|', 1, '|3|4|6|9|11|13|', 6, 'Build a tower of cans in the lab', 'In this task, the contestants are instructed to build a tower of tin cans in the lab.|They are then blindfolded and led into the lab, where a huge tower of tin cans has already been pre-constructed.|The winner is the person who leaves behind the tallest tower of cans in the lab (whether they constructed it themselves or merely avoided knocking down the existing one).', '02709_build_a_tower_of_cans_in_the_lab.jpg', '02709_build_a_tower_of_cans_in_the_lab_thumb.jpg'),
(563, '|1919|', 3, '|1|4|11|', 3, 'Remotely direct your blindfolded teammate', 'In this team task, one team member is blindfolded, but has a camera attached to them, so their teammate(s) can guide them remotely to complete an objective which involves locating someone or something.', '01919_shake_hands_with_your_teammate.jpg', '01919_shake_hands_with_your_teammate_thumb.jpg'),
(564, '|2481|', 14, '|3|', 1, 'Spear an aubergine with a writing implement', 'In this task, the contestants must spear an aubergine (eggplant) with a pen or pencil from the greatest distance.', '02481_stick_a_pencil_in_this_aubergine.jpg', '02481_stick_a_pencil_in_this_aubergine_thumb.jpg'),
(565, '|2661|', 8, '|3|', 1, 'Construct something while always making toast', 'In this team task, the contestants must construct something (e.g. a windmill, or tower) using supplied materials (e.g. lollipop sticks, or crispbread), while also always ensuring that at least one piece of bread is toasting.|To complicate things further, the contestants must take it in turns to push slices of bread down into the toaster(s).', '02661_make_the_most_impressive_windmill_while_toasting_bread.jpg', '02661_make_the_most_impressive_windmill_while_toasting_bread_thumb.jpg'),
(566, '|2602|', 1, '|3|6|11|', 3, 'Ice bath bluff', 'In this live studio task, the contestants must fool the Taskmaster into thinking that they are standing in a tray of ice water when they are not, or that they are not standing in the ice water when they actually are.', '02602_standing_in_ice_or_not_standing_in_ice.jpg', '02602_standing_in_ice_or_not_standing_in_ice_thumb.jpg'),
(567, '|2785|', 1, '|4|', 1, 'Retrieve and sip your drink', 'In this live studio task, the contestants must attempt to retrieve and sip a drink from a glass which has been placed at the end of an unrolled toilet roll.|They must keep all parts of their body behind a line on the stage while pulling on the toilet roll.|This task is very similar to the \'Roll a toilet roll, and then use it to retrieve something\' task (particularly <a href=\"/task.php?id=2723\">the version used on Le Maître du Jeu</a>, where the contestants had to retrieve glasses of water, rather than shoes), except the contestants do not have to roll their toilet rolls first.|There may be multiple rounds of the task, using different types of drinking glasses, or a single round in which the contestants blindly choose the starting location of their glass, and how much drink it contains.', '02785_retrieve_and_sip_your_drink.jpg', '02785_retrieve_and_sip_your_drink_thumb.jpg'),
(568, '|2510|', 1, '|3|11|', 2, 'Perform a slow-motion scene', 'In this team task, the contestants are instructed to choreograph and perform a slow-motion scene, which will be played back at a faster speed.', '02510_perform_a_slow_motion_fight_scene.jpg', '02510_perform_a_slow_motion_fight_scene_thumb.jpg'),
(569, '|1795|', 4, '|3|', 1, 'Recreate a sound', 'In this live studio task, the contestants must choose between a range of objects on offer, and then accurately recreate the sound it makes.', '01795_recreate_a_sound.jpg', '01795_recreate_a_sound_thumb.jpg'),
(570, '|2451|', 14, '|3|', 1, 'Transform your face into a national icon', 'In this live studio task, the contestants must use the contents of a suitcase to transform their own face into a national icon.|The suitcases typically contain supplies such as fruit, pasta, stationery, craft supplies, and make-up.', '02451_transform_your_face_into_an_australian_icon.jpg', '02451_transform_your_face_into_an_australian_icon_thumb.jpg'),
(571, '|2407|', 14, '|3|', 1, 'Move a large animal to water', 'In this team task, the contestants must move a large fibreglass animal (e.g. a giraffe or cow) to a container of water (e.g. a bathtub or paddling pool), without touching the ground, or the animal, and without the animal touching the ground.|To help them achieve this, they are provided with a clothes rack from which are hung some bathrobes and towels.', '02407_get_the_giraffe_in_the_bath.jpg', '02407_get_the_giraffe_in_the_bath_thumb.jpg'),
(572, '|2424|', 14, '|1|3|4|', 3, 'Make your picture...', 'In this live studio task, the contestants must make multiple consecutive alterations to a simple outline drawing to make it meet adjective criteria set by the Taskmaster, such as \'meaner\', \'more terrifying\', \'cuter\', \'more powerful\', \'more prestigious\', or \'sexier\'.|In each round, the contestant whose drawing least well matches the designated adjective is eliminated.', '02424_make_your_monster.jpg', '02424_make_your_monster_thumb.jpg'),
(573, '|2408|', 14, '|3|', 1, 'Spell the name of the show with your shadows', 'In this live team task, the contestants must collectively use the silhouettes cast by their bodies by a spotlight behind a projection screen to spell out the name of the show, one letter at a time.', '02408_spell_taskmaster_with_your_shadows.jpg', '02408_spell_taskmaster_with_your_shadows_thumb.jpg'),
(574, '|2381|', 14, '|3|4|9|', 3, 'Convince the Taskmaster that you deserve 5 points', 'In this live studio task, the contestants must take it in turns to convince the Taskmaster to award them the 5 points.|In each round, they must select a paddle from a board which instructs them on how they must make their appeal for the points.|The Taskmaster eliminates the least convincing contestant in each round, until only one remains standing.', '02381_convince_the_taskmaster_that_you_deserve_5_points.jpg', '02381_convince_the_taskmaster_that_you_deserve_5_points_thumb.jpg'),
(575, '|1416|', 4, '|6|', 1, 'Put the bead in the glass', 'In this task, the contestants are simply instructed to place a bead inside a drinking glass and say a given phrase.|The task is designed to be so simple that the contestants can\'t trust that they\'ve actually understood it, causing them to dither and search for a deeper meaning or instructions they have missed.|The contestant who places the bead inside the glass and says the given phrase fastest wins.', '01416_put_the_pearl_in_the_glass.jpg', '01416_put_the_pearl_in_the_glass_thumb.jpg'),
(576, '|1255|', 4, '|3|', 1, 'Make the watermelon end up furthest from the Taskmaster’s assistant', 'In this task, the contestants have a short amount of time to prepare before the Taskmaster\'s assistant drops a watermelon.|The aim is to get the watermelon as far away from the assistant as possible, without touching or otherwise interfering with it after it has been dropped.', '01255_make_the_watermelon_end_up_furthest_from_olli.jpg', '01255_make_the_watermelon_end_up_furthest_from_olli_thumb.jpg'),
(577, '|2185|', 1, '|3|6|13|', 3, 'Turn on the party device', 'In this task, the contestants have to figure out how to turn on a party device (e.g. a bubble machine or disco light) without moving from the spot they are standing on.|The device requires a certain number of batteries to operate, which are hidden around the space in which the task takes place.|There may also be a hidden power cord for the device which, if found, eliminates the need to hunt for batteries altogether.', '02185_turn_on_the_bubble_machine.jpg', '02185_turn_on_the_bubble_machine_thumb.jpg'),
(578, '|1567|', 4, '|3|', 1, 'Perform a horse show', 'In this task, the contestants must perform a horse-jumping or dressage show within a given arena.|In team versions of the task, some of the team members must play the part of the horse.', '01567_create_an_impressive_show_jumping_show.jpg', '01567_create_an_impressive_show_jumping_show_thumb.jpg'),
(579, '|2370|', 14, '|3|', 1, 'De-pineapple your pizzas', 'In this live studio task, the contestants must collect as many pineapple chunks as possible from some pizzas.|The contestants must wear oven mitts with chopsticks attached to them at all times during the tasks, and must attempt to request additional pizzas in Italian.|The contestant whose collected pineapple chunks produce the most juice at the end of the task wins.', '02370_de_pineapple_the_pizzas.jpg', '02370_de_pineapple_the_pizzas_thumb.jpg'),
(580, '|2318|', 6, '|3|', 1, 'Solve the fruit and vegetable tasks', 'In this task, the contestants are provided with a number of fruits and vegetables, and a matching number of mini task briefs, and must solve the latter using the former.|Each fruit or vegetable may only be used once.|The contestant who most quickly completes all of the mini-tasks wins.', '02318_solve_the_11_tasks_with_fruits_and_vegetables.jpg', '02318_solve_the_11_tasks_with_fruits_and_vegetables_thumb.jpg'),
(581, '|2293|', 1, '|1|3|11|15|16|', 8, 'Set the parameters for your own task', 'In this task, the contestants unwittingly set their own parameters for the task by responding to a series of questions or prompts beforehand.|Their answers are then either incorporated directly into a skeleton task brief, which is later presented to them as a personalised challenge, or determine the equipment available to them in a later task.', '02293_order_three_things_for_your_final_task.jpg', '02293_order_three_things_for_your_final_task_thumb.jpg'),
(582, '|2417|', 4, '|3|6|11|', 3, 'Complete the tasks with increasing rapidity', 'In this task, the contestants must complete a series of mini-tasks with increasing rapidity.|If they fail to complete a mini-task in less time than the previous one, they must start over from the beginning.|The winner is the person who completes all of the tasks in the least time overall.', '02417_complete_the_tasks_as_quickly_as_possible.jpg', '02417_complete_the_tasks_as_quickly_as_possible_thumb.jpg'),
(583, '|419|', 1, '|3|8|13|', 3, 'Supply a soundtrack for a film', 'In this task, the contestants must provide the soundtrack for a silent film.', '00419_supply_a_soundtrack_for_a_film.jpg', '00419_supply_a_soundtrack_for_a_film_thumb.jpg'),
(584, '|2265|', 4, '|3|9|', 2, 'Write the same word as someone else', 'In this live studio task, the contestants must try to write down the same word as one or more of the other contestants, within given categories.|If they fail to write down the same word as someone else, they are eliminated.|The last player standing wins.', '02265_write_the_same_word_as_someone_else.jpg', '02265_write_the_same_word_as_someone_else_thumb.jpg'),
(585, '|733|', 1, '|6|11|', 2, 'Have an argument', 'In this team task, the contestants must take it in turns to argue with one another, while looking at one another and wagging their fingers.|Each contestant\'s turn in the argument may consists of no more than 10 words, and the last word must consist of four letters.|The argument ends when there are 10 seconds of silence or someone looks away.|The team who manages the longest argument wins.', '00733_have_an_argument.jpg', '00733_have_an_argument_thumb.jpg'),
(586, '|1894|', 1, '|11|', 1, 'The object you would most like to show to an alien', 'In this prize task, the contestants must bring in the object they would most like to show to an alien.', '01894_the_object_you_would_most_like_to_show_to_an_alien.jpg', '01894_the_object_you_would_most_like_to_show_to_an_alien_thumb.jpg'),
(587, '|1407|', 1, '|11|', 1, 'Pass everything through the pipe and the pipe through everything', 'In this task, the contestants are provided with a large pipe and a box full of items, and must either pass everything through the pipe and then the pipe through everything, or pass the pipe through everything and then everything through the pipe.', '01407_pass_everything_through_the_pipe_and_the_pipe_through_everything.jpg', '01407_pass_everything_through_the_pipe_and_the_pipe_through_everything_thumb.jpg'),
(588, '|853|', 1, '|11|', 1, 'The best thing to hang on a wall that wouldn’t normally hang on a wall', 'In this prize task, the contestants must bring in the best thing to hang on a wall that wouldn’t normally hang on a wall.', '00853_best_thing_to_hang_on_a_wall.jpg', '00853_best_thing_to_hang_on_a_wall_thumb.jpg'),
(589, '|127|', 1, '|11|', 1, 'Score a goal with a plastic bag', 'In this task, the contestants must score a goal with a plastic bag using the fewest kicks possible, and without touching the bag with their hands.', '00127_score_a_goal_with_a_shopping_bag.jpg', '00127_score_a_goal_with_a_shopping_bag_thumb.jpg'),
(590, '|1349|', 1, '|6|', 1, 'Spread something on bread in a really cool way', 'In this task, the contestants are instructed to spread something (e.g. jam or liver pâté) onto toast or bread in a really cool way.', '01349_spread_jam_on_toast_in_a_really_cool_way.jpg', '01349_spread_jam_on_toast_in_a_really_cool_way_thumb.jpg'),
(591, '|1529|', 3, '|6|', 1, 'Travel as far as possible without touching the ground', 'The contestants begin this task standing on a pile of unassembled cardboard boxes, and must travel as far as possible without touching the ground.|In some versions, they must assemble boxes at the start and end of their journey.', '01529_travel_as_far_as_possible_without_touching_the_ground.jpg', '01529_travel_as_far_as_possible_without_touching_the_ground_thumb.jpg'),
(592, '|1392|', 1, '|4|6|8|11|14|15|', 6, 'Make and throw paper aeroplanes', 'In this task, the contestants are instructed to make and then throw paper aeroplanes.|In some versions, they are first instructed to choose what type of paper (e.g. toilet paper, wrapping paper, origami paper, regular paper), or how much paper they want to use (i.e. sheets of paper, or a quantity of wrapping paper).|In some versions, the amount of paper they choose affects the starting balance of a score which they may then affect in the second part of the task.|They are then instructed to fold the paper into one or more paper aeroplanes in a limited time.|The paper aeroplane(s) must be thrown from a certain location (e.g. the stage, or a window), either into one or more receptacles to score points, or just as far as possible.|The winner of the task is either the contestant with the most points, or the one whose plane flies the furthest, depending on the specifics of the adaptation.', '01392_make_paper_aeroplanes.jpg', '01392_make_paper_aeroplanes_thumb.jpg'),
(593, '|2087|', 8, '|9|', 1, 'The worst investment', 'In this prize task, the contestants are instructed to bring in the worst investment.', '02087_the_worst_investment.jpg', '02087_the_worst_investment_thumb.jpg'),
(594, '|1205|', 8, '|9|', 1, 'Get the exercise ball into the kayak', 'In this task, the contestants must attempt to get an exercise ball into a kayak which is anchored a short distance away in a body of water, without getting wet.', '01205_get_the_swiss_ball_into_the_kayak.jpg', '01205_get_the_swiss_ball_into_the_kayak_thumb.jpg'),
(595, '|1192|', 3, '|6|', 1, 'Complete as many tasks as possible', 'In this task, the contestants walk into a room to find a grid of 50 task briefs laid out in a grid on the floor, and they must attempt to complete as many of them as possible in a short period of time.|The time does not begin until they open one of the briefs.', '01192_complete_as_many_tasks_as_possible.jpg', '01192_complete_as_many_tasks_as_possible_thumb.jpg'),
(596, '|1530|', 3, '|6|', 1, 'Break as many raw eggs as possible', 'In this task, the contestants are presented with a tray full of eggs (all but one of which are raw) and a small hammer or mallet, and are instructed to break as many raw eggs as possible in a given amount of time.|If the contestants break the boiled egg, they are automatically disqualified from the task.|As an aid, the contestants may ask the Taskmaster\'s assistant two \'yes\' or \'no\' questions, and they will answer them honestly.', '01530_break_as_many_eggs_as_possible.jpg', '01530_break_as_many_eggs_as_possible_thumb.jpg'),
(597, '|1983|', 1, '|6|', 1, 'Write down things that fit the category', 'In this live team task, the contestants are instructed to write down five words which fit given categories.|The aim is for them to match as many of their team-mates words as possible, without matching the words written by the opposing team.', '01983_write_down_things_that_fit_the_category.jpg', '01983_write_down_things_that_fit_the_category_thumb.jpg'),
(598, '|2031|', 1, '|11|', 1, 'The thing that makes everyone exclaim that it really is the best thing', 'In this prize task, the contestants must bring in something which will prompt everyone to make a specific, surprised exclamation.', '02031_the_thing_that_makes_everyone_go_wow_that_really_is_the_greatest_thing.jpg', '02031_the_thing_that_makes_everyone_go_wow_that_really_is_the_greatest_thing_thumb.jpg'),
(599, '|2052|', 8, '|9|', 1, 'The best thing that weighs exactly a given weight', 'In this prize task, the contestants are instructed to bring in something which weighs exactly a given weight.', '02052_the_best_thing_that_weighs_exactly_10kg.jpg', '02052_the_best_thing_that_weighs_exactly_10kg_thumb.jpg'),
(600, '|365|', 1, '|9|', 1, 'Create a sand portrait of a former contestant', 'In this task, the contestants are provided with a range of air-blowing tools, and a small sandpit, and are instructed to create a portrait of a previous contestant using only air to move the sand.|They are instructed to choose their air-blowing item by rolling a provided die.', '00365_make_a_portrait_of_a_former_contestant_in_sand.jpg', '00365_make_a_portrait_of_a_former_contestant_in_sand_thumb.jpg'),
(601, '|459|', 1, '|11|', 1, 'List words of a certain length without hesitating', 'IN this live studio task, the contestants must take it in turns to list as many different words of a give length as they can without hesitating.|The contestant who lists the fewest words in each round is eliminated.|The length of the words to be listed changes with each round.', '00459_list_words_of_a_certain_length.jpg', '00459_list_words_of_a_certain_length_thumb.jpg'),
(602, '|736|', 4, '|9|', 1, 'Something you’ve borrowed, but never returned', 'In this prize task, the contestants must bring in something they’ve borrowed, but never returned.', '00736_something_borrowed_never_returned.jpg', '00736_something_borrowed_never_returned_thumb.jpg'),
(603, '|2595|', 1, '|6|9|', 2, 'Deliver an impromptu lecture', 'In this task, the contestants are instructed to deliver an impromptu lecture or presentation on a topic which is somehow randomly assigned.', '02595_deliver_a_one_minute_history_lecture.jpg', '02595_deliver_a_one_minute_history_lecture_thumb.jpg'),
(604, '|508|', 8, '|9|', 1, 'Blow an egg the furthest from the table', 'In this task, the contestants must attempt to blow an egg the furthest from a table.', '00508_blow_an_egg_the_furthest_from_a_table.jpg', '00508_blow_an_egg_the_furthest_from_a_table_thumb.jpg'),
(605, '|472|', 1, '|6|11|13|', 3, 'Fill the cup to overflowing', 'In this task, the contestants must attempt to fill a cup mounted on top of a long flexible pole to overflowing with some kind of liquid.|Nothing may touch the circular red mat around the pole except liquid.', '00472_fill_the_cup_to_overflowing_without_touching_the_red_green.jpg', '00472_fill_the_cup_to_overflowing_without_touching_the_red_green_thumb.jpg'),
(606, '|2359|', 14, '|1|3|11|', 3, 'Juice some oranges using only the items supplied', 'In this task, the contestants are provided with a pile of oranges, a vessel to squeeze them into, and an assortment of items which are the only things with which they may touch the oranges.|In some versions of the task, the contestants have unknowingly selected the available equipment for themselves beforehand.', '02359_fill_the_glass_with_orange_juice.jpg', '02359_fill_the_glass_with_orange_juice_thumb.jpg'),
(607, '|2518|', 1, '|9|11|16|', 3, 'The best headwear that isn’t a hat', 'In this prize task, the contestants must bring in the best item of headwear that isn’t a hat.', '02518_the_most_fun_non-headwear_to_wear_on_your_head.jpg', '02518_the_most_fun_non-headwear_to_wear_on_your_head_thumb.jpg'),
(608, '|1153|', 8, '|11|', 1, 'Fly', 'In this task, the contestants are simply instructed to \'fly\', with the best flight winning.', '01153_fly.jpg', '01153_fly_thumb.jpg'),
(609, '|1685|', 9, '|11|', 1, 'The best souvenir', 'In this prize task, the contestants are instructed to bring in th best souvenir, memento, or keepsake.', '01685_the_best_souvenir.jpg', '01685_the_best_souvenir_thumb.jpg'),
(610, '|484|', 1, '|11|', 1, 'Neatly hang all the mannequin’s clothes on a rail', 'In this task, the contestants must remove all of the clothing from a mannequin and neatly hang it all on a clothes rail which is out of their reach, without crossing a line.', '00484_neatly_hang_all_the_clothes_on_a_rail.jpg', '00484_neatly_hang_all_the_clothes_on_a_rail_thumb.jpg'),
(611, '|2562|', 1, '|9|11|', 2, 'Story-time chairs', 'In this live studio task, the contestants must listen to the Taskmaster reading a story, and attempt to take a seat when words matching defined rules are read.|It is essentially a game of musical chairs, with the contestant who is unable to find a seat being eliminated in each round.|Contestants are also eliminated if they sit down before they are meant to.|The rules for the words to listen out for change with each round.', '02562_story_time_chairs.jpg', '02562_story_time_chairs_thumb.jpg'),
(612, '|463|', 1, '|11|', 1, 'Transfer the most water from barrel A to barrel B', 'In this task, the contestants must attempt to transfer as much water as possible from one barrel to another, while water is leaking out of the first barrel.|They are not permitted to move either barrel during the first five minutes of the task.', '00463_transfer_the_water_from_one_barrel_to_another.jpg', '00463_transfer_the_water_from_one_barrel_to_another_thumb.jpg'),
(613, '|2509|', 1, '|11|', 1, 'Catch the potatoes in the potato hat', 'In this task, the contestants must sit on a stool beneath the end of a conveyor belt, with their back to it, and attempt to catch as many potatoes as possible in a pair of top hats stuck top-to-top, which they are wearing on their head.|Any items caught in the hat which are not potatoes are deducted from their total.|The contestants are also instructed not to touch \'anything\' during the task.', '02509_catch_the_potatoes_in_the_potato_hat.jpg', '02509_catch_the_potatoes_in_the_potato_hat_thumb.jpg'),
(614, '|2508|', 1, '|6|11|', 2, 'Exit the Taskmaster’s assistant’s residence after exactly 20 minutes', 'In this task, the contestants must leave the Taskmaster’s assistant’s residence (i.e. caravan or outbuilding) as close to 20 minutes after entering it as possible.|As a distraction to their time-keeping attempts while inside the residence, they must also make a list of 40 different words, each of which must be the same length or shorter than the previous one.', '02508_exit_the_caravan_after_exactly_20_minutes.jpg', '02508_exit_the_caravan_after_exactly_20_minutes_thumb.jpg'),
(615, '|2463|', 1, '|6|11|', 2, 'Throw your items into your bucket', 'In this live studio task, the contestants must in each round attempt to throw one of five provided items into a bucket balanced on top of a pole.|If they knock the bucket off the pole, they are disqualified.|The winner is the person with the most items in their bucket at the end of the task.', '02463_throw_your_items_into_your_bucket.jpg', '02463_throw_your_items_into_your_bucket_thumb.jpg'),
(616, '|1247|', 4, '|11|', 2, 'Something that doesn’t get the respect it deserves', 'In this prize task, the contestants must bring in something that doesn’t get the respect it deserves.', '01247_something_that_does_not_get_the_respect_it_deserves.jpg', '01247_something_that_does_not_get_the_respect_it_deserves_thumb.jpg'),
(617, '|344|', 1, '|3|11|', 2, 'Put the most weight in the hammock', 'In this task, the contestants must attempt to load as much weight into a hammock as possible.|If anything falls out of the hammock, they are disqualified.|This is usually a team task.', '00344_get_the_most_weight_into_a_hammock.jpg', '00344_get_the_most_weight_into_a_hammock_thumb.jpg'),
(618, '|1947|', 1, '|11|', 1, 'Answer the Taskmaster’s assistant’s phone call', 'In this task, the contestants must find a phone and answer the incoming call as fast as possible.|This task is complicated by the use of decoys which sound like a phone ringing, and by the requirements that the contestants must continue to carry with them any cuddly toys they see along the way, and must be making a noise over 50 decibels for at least 50% of the time.|A further complication is that this task usually takes place after the \'Make a key difficult to retrieve\' task, and the same key they hid then is required to open a locked box containing the phone.', '01947_answer_alexs_phone_call.jpg', '01947_answer_alexs_phone_call_thumb.jpg'),
(619, '|2560|', 1, '|11|', 1, 'Efficiently shell an egg', 'In this task, the contestants are presented with five eggs, and are instructed to efficiently shell just one of them without touching any eggs with their hands.|Just one of the eggs is raw, while the others are hard-boiled. A clue is provided on the edge of the table to help them identify this.|The winner is the person who removes the shell from an egg in the least pieces.', '02560_efficiently_shell_an_egg.jpg', '02560_efficiently_shell_an_egg_thumb.jpg'),
(620, '|1485|', 4, '|11|', 1, 'Something you wish did not exist', 'In this prize task, the contestants must bring in something they wish did not exist.', '01485_something_you_wish_did_not_exist.jpg', '01485_something_you_wish_did_not_exist_thumb.jpg'),
(621, '|2599|', 1, '|3|11|', 3, 'Get liquid into a glass from a distance', 'In this task, the contestants are instructed to get some liquid (e.g. water or soda) into a drinking glass from as far away as possible.|In some versions of the task, they must fill the glass up to a line for it to count.|In some versions of the task, if two or more people decide to use a hose to achieve their goal, they are all disqualified.|In one version of the task, the contestants must also carry a plush toy around with them at all times.', '02599_fill_the_glass_up_to_the_line.jpg', '02599_fill_the_glass_up_to_the_line_thumb.jpg'),
(622, '|1391|', 1, '|11|', 1, 'Sit on the red chair in the secret room', 'In this task, the contestants must take a red chair to a specific room and sit on it.|This task is complicated by the fact that they may only step on circular marker spots. They may only step on each red spot once, but may step on a black spot twice (but not twice in a row).|The contestants are also instructed to shred the task brief during the first minute of their attempt, meaning they cannot refer back to the complicated instructions.|If the contestant makes anyu mistakes, they must restart the task from the beginning.|The winner is the one who completes the task fastest.', '01391_sit_on_the_red_chair_in_the_secret_tower.jpg', '01391_sit_on_the_red_chair_in_the_secret_tower_thumb.jpg'),
(623, '|2282|', 1, '|3|6|11|', 3, 'Snort, raspberry, whistle', 'In this task, the contestants must snort, blow a raspberry, and then whistle as many times as possible in a given time period.|The contestant who completes the most sequences wins.', '02282_snort_raspberry_whistle.jpg', '02282_snort_raspberry_whistle_thumb.jpg'),
(624, '|2559|', 1, '|11|', 1, 'Perform a touching domestic scene with an imaginary friend', 'In this task, the contestants must create an imaginary friend for themselves, and then complete a household chore with their friend.|The imaginary friend must be either much taller or much shorter than the contestant.|the winner is the one who performs the most poignant or touching scene with their friend.', '02559_perform_a_poignant_domestic_scene_with_an_imaginary_companion.jpg', '02559_perform_a_poignant_domestic_scene_with_an_imaginary_companion_thumb.jpg'),
(625, '|432|', 1, '|11|', 1, 'The best thing to put in your mouth', 'In this prize task, the contestants must bring in the best or nicest thing to put in your mouth.', '00432_the_nicest_thing_to_put_in_your_mouth.jpg', '00432_the_nicest_thing_to_put_in_your_mouth_thumb.jpg'),
(626, '|1348|', 1, '|3|11|', 2, 'Complete the course as slowly as possible', 'In this task, the contestants must ride a bike through an obstacle course as slowly as possible.|Each time they place their foot on the ground, leave the course, or miss an obstacle, the clock is stopped until they resume, and their total time is halved.|The contestant with the longest completion time wins.', '01348_complete_the_course_as_slowly_as_possible.jpg', '01348_complete_the_course_as_slowly_as_possible_thumb.jpg'),
(627, '|1242|', 1, '|11|', 1, 'The nicest thing to sit on', 'In this prize task, the contestants must bring in the nicest thing to sit on, if put inside a bag or suitcase.', '01242_the_nicest_thing_to_sit_on.jpg', '01242_the_nicest_thing_to_sit_on_thumb.jpg'),
(628, '|370|', 1, '|11|13|', 2, 'Get a ball into a bin with the most bounces', 'In this task, the contestants must attempt to get a ball into a waste paper bin after the most bounces.|They must use whichever ball they touch first, and may not touch it again after releasing it.', '00370_get_a_ball_into_a_bin_with_the_most_bounces.jpg', '00370_get_a_ball_into_a_bin_with_the_most_bounces_thumb.jpg'),
(629, '|1981|', 1, '|11|', 1, 'Stick your tongue out for the longest time', 'In this task, the contestants must keep their tongue stuck out for as long as possible while alternately licking sour, dry, and cold things, and putting their tongue in front of an electric fan.', '01981_poke_your_tongue_out_for_the_longest_time.jpg', '01981_poke_your_tongue_out_for_the_longest_time_thumb.jpg'),
(630, '|222|', 1, '|11|', 1, 'Catch the most socks', 'In this live studio task, the contestants must attempt to catch socks dropped from above them, but avoid catching the underpants.', '00222_catch_the_most_socks.jpg', '00222_catch_the_most_socks_thumb.jpg'),
(631, '|2162|', 1, '|11|', 1, 'Sort the ducks and the socks', 'In this task, the contestants must collect ducks in a bucket on their front, and socks in a bucket on their back.|The ducks and socks have to travel along a pair of treadmills first.|The winner is the one who collects the most ducks and socks in the right buckets.', '02162_sort_the_ducks_and_the_socks.jpg', '02162_sort_the_ducks_and_the_socks_thumb.jpg'),
(632, '|2161|', 1, '|3|6|11|', 3, 'Put five small edible items in the little bowl', 'In this task, the contestants must place five small edible items (e.g. grapes or peppernut cookies) in a small bowl while wearing flippers on their hands.|The relevant small edible items are hidden inside a pile of flour on a plate.|The winner is the person who leaves the most flour on the plate at the end of the task.|In some versions of the task, there are additional small edible items hidden elsewhere in the room, as a workaround.', '02161_put_five_grapes_in_the_little_bowl.jpg', '02161_put_five_grapes_in_the_little_bowl_thumb.jpg'),
(633, '|146|', 1, '|11|', 1, 'The most excellent noise', 'In this prize task, the contestants must bring in the most excellent noise or superb sound.', '00146_the_most_excellent_noise.jpg', '00146_the_most_excellent_noise_thumb.jpg'),
(634, '|254|', 1, '|9|', 1, 'The best cat-sized thing', 'In this prize task, the contestants must bring in the best cat-sized thing.', '00254_the_most_pleasing_cat_sized_thing.jpg', '00254_the_most_pleasing_cat_sized_thing_thumb.jpg'),
(635, '|1244|', 1, '|9|11|', 2, 'Paint a flattering picture of the Taskmaster while lying on your back', 'In this task, the contestants must paint a flattering portrait of the Taskmaster while lying on their backs.|Before doing so, they get to choose whether they want the canvas to be very close to them, or very far away.', '01244_paint_a_flattering_picture_of_the_taskmaster_in_action.jpg', '01244_paint_a_flattering_picture_of_the_taskmaster_in_action_thumb.jpg'),
(636, '|437|', 1, '|11|13|', 2, 'The best thing with loads of holes', 'In this prize task, the contestants must bring in the best thing with loads of holes.', '00437_the_best_thing_with_loads_of_holes_in_it.jpg', '00437_the_best_thing_with_loads_of_holes_in_it_thumb.jpg'),
(637, '|288|', 1, '|11|', 1, 'The worst gift from a named relative', 'In this prize task, the contestants must bring in the worst gift from a named relative.', '00288_the_worst_gift_from_a_relative.jpg', '00288_the_worst_gift_from_a_relative_thumb.jpg'),
(638, '|198|', 1, '|11|', 1, 'Perform a miracle', 'In this task, the contestants must attempt to perform a miracle.', '00198_perform_a_miracle.jpg', '00198_perform_a_miracle_thumb.jpg'),
(639, '|2014|', 1, '|6|11|', 2, 'Get the most ducks in the Taskmaster’s assistant’s basket', 'In this task, the contestants must add the most ducks to a basket on a bicycle being ridden by the Taskmaster’s assistant.|The contestants may only hold one duck at a time, and must move backwards if the Taskmaster’s assistant rings their bell.|The Taskmaster’s assistant will rest for 10 seconds each time the contestant says one of the magic words, which are written on the bottoms of the ducks.', '02014_get_the_most_ducks_in_alexs_basket.jpg', '02014_get_the_most_ducks_in_alexs_basket_thumb.jpg'),
(640, '|406|', 1, '|11|', 1, 'The thing you’d be happiest to find in a field', 'In this prize task, the contestants must bring in the thing they’d be happiest to find in a field.', '00406_the_thing_youd_be_most_pleased_to_find_in_a_field.jpg', '00406_the_thing_youd_be_most_pleased_to_find_in_a_field_thumb.jpg'),
(641, '|2034|', 1, '|9|11|15|16|', 4, 'Get the animal into a receptacle from behind a rope', 'In this task, the contestants must get an animal (e.g. a rubber duck or cloth fish) into a receptacle (e.g. a pond, paddling pool, bucket, or fishbowl) from behind a rope.|The task may be scored based on how quickly they get the animal to the receptacle, or how far they get it to travel before landing in the receptacle, or on the quality of the animal\'s trip.|They may also be required to say a specific phrase before the animal begins its trip, and there may be a restriction on the animal touching the ground.', '02034_get_the_duck_into_the_pond.jpg', '02034_get_the_duck_into_the_pond_thumb.jpg'),
(642, '|2717|', 4, '|3|', 1, 'Choose the least-chosen option', 'In this live studio task, the contestants are presented with two choices over a series of rounds, and earn points each time they opt for the least-chosen option.', '02717_choose_the_least_chosen_option.jpg', '02717_choose_the_least_chosen_option_thumb.jpg'),
(643, '|2368|', 14, '|3|6|', 2, 'Make a family member hang up on you', 'In this filmed task, the contestants must call a member of their actual or chosen family, and get that person to hang up on them the fastest, without them suspecting that this is the goal.', '02368_make_an_older_family_member_hang_up_on_you.jpg', '02368_make_an_older_family_member_hang_up_on_you_thumb.jpg'),
(644, '|2303|', 13, '|14|', 1, 'The most useful item', 'In this prize task, the contestants are instructed to bring in the most useful item or thing.', '02303_the_most_useful_item.jpg', '02303_the_most_useful_item_thumb.jpg'),
(645, '|1406|', 1, '|14|', 1, 'Write and perform a jingle', 'In this filmed task, the contestants must write and perform a short jingle for something which has been selected at random (e.g. an object or business).|In some versions, the musical instrument they must use for their jingle is also selected at random.', '01406_write_and_perform_a_30_second_jingle.jpg', '01406_write_and_perform_a_30_second_jingle_thumb.jpg'),
(646, '|1177|', 3, '|1|8|9|', 3, 'Create an instrument and play a tune on it', 'In this task, the contestants are instructed to perform a tune on something which is not an existing musical instrument.|Sometimes they are instructed to perform a specific tune, but sometimes it is a tune of their choice, from within a specific genre (e.g. a children\'s music, or classical music).', '01177_invent_an_instrument.jpg', '01177_invent_an_instrument_thumb.jpg'),
(647, '|1519|', 3, '|9|', 1, 'Walk a specific number of steps with the Taskmaster’s assistant', 'In this task, the contestants are instructed to walk a specific number of steps while maintaining a conversation with the Taskmaster\'s assistant.|This task was also adapted as a format for the contestant interviews in <a href=\"/season.php?id=48\">series 13</a> of Taskmaster UK.', '01519_walk_589_steps_with_david.jpg', '01519_walk_589_steps_with_david_thumb.jpg'),
(648, '|1904|', 3, '|9|', 1, 'Take something cumbersome on an adventure', 'In this task, the contestants are instructed to take something cumbersome (e.g. a large stuffed toy bear, or a life-sized clothes mannequin) on an adventure.', '01904_take_the_bear_on_an_adventure.jpg', '01904_take_the_bear_on_an_adventure_thumb.jpg'),
(649, '|2053|', 8, '|9|', 1, 'Retrieve the eggs from the top of the pole', 'In this task, the contestants are instructed to retrieve a dozen eggs from the top of a very tall pole.|The winner is the one who retrieves the most eggs intact.|There is usually a rule about keeping one or both feet on the ground during the retrieval process.', '02053_retrieve_the_eggs_from_the_top_of_the_pole.jpg', '02053_retrieve_the_eggs_from_the_top_of_the_pole_thumb.jpg'),
(650, '|3243|', 13, '|9|', 1, 'Quickly open a gift, then re-wrap it', 'In this task, the contestants are first instructed to open a wrapped gift as quickly as possible.|They are then instructed to rewrap the gift to its original condition.|Sometimes, wrapping supplies are provided in a non-obvious location for them to use, and sometimes a roll of tape (or some form of alternative) is provided within the gift box itself.', '03243_quickly_open_a_gift_then_re_wrap_it.jpg', '03243_quickly_open_a_gift_then_re_wrap_it_thumb.jpg'),
(651, '|1927|', 1, '|6|', 1, 'Write something using bunting', 'In this task, the contestants enter a room to find bunting strung across the room, featuring seemingly random letters, and are instructed to compose a message about something using the letters.|Some of the letters on a specific colour of the bunting flags has been arranged to tell the contestants to look under the table.|If they look under the table, they will find a tablet on which there is a video, featuring the Taskmaster speaking a message which just happens to use all of the available letters.', '01927_make_a_stirring_speech_out_of_the_bunting.jpg', '01927_make_a_stirring_speech_out_of_the_bunting_thumb.jpg'),
(652, '|2924|', 1, '|3|6|9|', 3, 'Don’t say the Taskmaster’s favourite thing', 'In this live task, the contestants must take it in turns to list things belonging to specific categories, without hesitating or repetition.|If they hesitate, repeat, or say the Taskmaster\'s favourite thing within the category, they are eliminated.|The last remaining contestant wins.', '02924_dont_say_the_taskmasters_favourite_thing.jpg', '02924_dont_say_the_taskmasters_favourite_thing_thumb.jpg'),
(653, '|1500|', 3, '|9|', 1, 'Make a root vegetable fall', 'In this task, the contestants are presented with a variety of root vegetables, and are instructed to make one of them fall for as long as possible.|In some versions, the contestants are disqualified if they choose the same vegetable.', '01500_make_a_root_vegetable_fall.jpg', '01500_make_a_root_vegetable_fall_thumb.jpg'),
(654, '|1271|', 6, '|1|8|', 2, 'Teach someone a lesson', 'In this task, the contestants are instructed to teach someone (e.g. a child, or the Taskmaster\'s assistant) something.', '01271_teach_a_child_something_remarkable.jpg', '01271_teach_a_child_something_remarkable_thumb.jpg'),
(655, '|1428|', 4, '|8|', 1, 'Make a silent film', 'In this task, the contestants are instructed to make a short silent film.', '01428_make_the_best_silent_film.jpg', '01428_make_the_best_silent_film_thumb.jpg'),
(656, '|2782|', 1, '|3|11|13|', 3, 'Burst the water balloon without looking at it', 'In this task, the contestants must attempt to burst a water balloon from the greatest distance while not looking at it.', '02782_burst_the_balloon_without_looking_at_it.jpg', '02782_burst_the_balloon_without_looking_at_it_thumb.jpg'),
(657, '|3027|', 4, '|3|', 1, 'Remove the Taskmaster’s assistant from a location', 'In this task the contestants must attempt to remove the Taskmaster\'s assistant from a location as quickly as possible without touching them.', '03027_evict_olli_from_the_caravan.jpg', '03027_evict_olli_from_the_caravan_thumb.jpg'),
(658, '|1827|', 4, '|3|', 1, 'Tell a story in a specific amount of time', 'In this live task, the contestants must aim to tell a short story and then hit a bell as close to a specific target time as possible.', '01827_tell_a_baffling_story_in_16_55_seconds.jpg', '01827_tell_a_baffling_story_in_16_55_seconds_thumb.jpg'),
(659, '|2125|', 8, '|3|', 1, 'Trick or treat the Taskmaster’s assistant', 'In this task, the contestants must choose to either trick or treat the Taskmaster\'s assistant.', '02125_trick_or_treat_paul.jpg', '02125_trick_or_treat_paul_thumb.jpg'),
(660, '|1778|', 4, '|3|', 1, 'Carry the most boxes through the obstacles', 'In this live task, the contestants must attempt to carry as many cardboard boxes as possible through an obstacle course.', '01778_carry_the_most_boxes_through_the_obstacles.jpg', '01778_carry_the_most_boxes_through_the_obstacles_thumb.jpg'),
(661, '|2694|', 8, '|3|', 1, 'Invent new exercise equipment', 'In this task, the contestants are instructed to invent some new exercise equipment and then burn some calories while using it.', '02694_invent_a_new_exercise_machine.jpg', '02694_invent_a_new_exercise_machine_thumb.jpg'),
(662, '|2131|', 4, '|3|', 1, 'Slow down the assistant’s trip from A to B', 'In this task, the contestants must aim to slow down the Taskmaster\'s assistant\'s trip from point \'A\' to point \'B\' without touching them or the letters.', '02131_slow_down_ollis_trip_from_a_to_b.jpg', '02131_slow_down_ollis_trip_from_a_to_b_thumb.jpg'),
(663, '|2958|', 4, '|3|', 1, 'Set the table, then remove the tablecloth', 'In this task, the contestants must first set a table, and then remove the tablecloth from the table.|Variations of the task have been used as both live and pre-filmed tasks.', '02958_set_your_table_remove_the_tablecloth.jpg', '02958_set_your_table_remove_the_tablecloth_thumb.jpg'),
(664, '|2808|', 1, '|3|6|', 2, 'Play with these switches, then balance some items', 'In this task, the contestants are first presented with a switchboard, and given five minutes to do whatever they like with the switches.|They must then balance some small items (e.g. golf tees, or boardgame pieces) on some thin shelves during another five minute period, during which time their actions in the first part of the task affect what happens around them.', '02808_play_with_these_switches_balance_the_most_golf_tees.jpg', '02808_play_with_these_switches_balance_the_most_golf_tees_thumb.jpg'),
(665, '|1910|', 1, '|3|', 1, 'Face leg, or different leg?', 'In this live team task, the contestants must attempt to fool the Taskmaster about whether a face and a leg poked through holes in a wall belong to the same person or not.', '01910_face_leg_or_other_leg.jpg', '01910_face_leg_or_other_leg_thumb.jpg'),
(666, '|2707|', 8, '|3|', 1, 'Disguise your silhouette from the Taskmaster', 'In this live task, the contestants must attempt to prevent the Taskmaster from identifying them as they walk behind a backlit screen by using a variety of props and costumes to disguise their silhouette.', '02707_disguise_your_silhouette_from_the_taskmaster.jpg', '02707_disguise_your_silhouette_from_the_taskmaster_thumb.jpg'),
(667, '|2292|', 1, '|9|', 1, 'The thing the Taskmaster would most like to own', 'In this prize task, the contestants are instructed to bring in the thing of theirs that they believe the Taskmaster would most like to own.', '02292_the_thing_the_taskmaster_would_most_like_to_own.jpg', '02292_the_thing_the_taskmaster_would_most_like_to_own_thumb.jpg'),
(668, '|1358|', 1, '|9|', 1, 'Sit on a cake', 'In this task, the contestants are instructed to sit on a cake as quickly as possible.|There may be bonus points on offer for the best cake.', '01358_sit_on_a_cake.jpg', '01358_sit_on_a_cake_thumb.jpg'),
(669, '|424|', 1, '|9|', 1, 'Celebrity joints', 'In this task, the contestants are instructed to turn one or more knees or elbows into a single celebrity or pair of celebrities.|Depending on the specifics of the task, it might be the contestants\' own joints, or the Taskmaster\'s assistant\'s joints, which must be transformed.', '00424_make_a_famous_couple_using_knees_and_or_elbows.jpg', '00424_make_a_famous_couple_using_knees_and_or_elbows_thumb.jpg'),
(670, '|2349|', 1, '|3|6|', 2, 'Collect pet food in a fishbowl', 'In this task, the contestants are instructed to collect as much pet food (e.g. fish pellets, or cat kibbles) in a fishbowl, while not bending any joints from their waist down.|The pet food to be collected is found in tin cans in various locations, but all of them are booby-trapped in some manner to make it likely the food will be spilled on the floor.', '02349_collect_carp_pellets_in_a_fish_bowl.jpg', '02349_collect_carp_pellets_in_a_fish_bowl_thumb.jpg'),
(671, '|2406|', 14, '|3|', 1, 'Deliver roses to the Taskmaster’s assistant', 'In this task, the contestants must collect and deliver a series of roses to the Taskmaster\'s assistant.|There is a rose for every letter in the alphabet used by the country in which the show is produced.|Each rose requires a valid password to be uttered by the contestant before they can pick it up.|The secret is that each password must begin with a different letter of the alphabet.', '02406_deliver_26_roses_to_toms_vase.jpg', '02406_deliver_26_roses_to_toms_vase_thumb.jpg'),
(672, '|2811|', 1, '|3|', 1, 'Get three balls on your hat using litter pickers', 'In this live task, the contestants must pick up balls using litter-pickers, and place them on their mortarboard hats, which have been modified so that they have low walls around the edges.|Each time they place a ball on their hat, they must shout \'Ball!\'.|The winner is the first person to  get three balls onto their hat.', '02811_get_three_balls_on_your_hat_using_litter_pickers.jpg', '02811_get_three_balls_on_your_hat_using_litter_pickers_thumb.jpg'),
(673, '|2190|', 4, '|3|', 1, 'Record a livestream highlight reel', 'In this task, the contestants are provided with a camera and microphone, and are instructed to record a livestream highlight reel.|A service bell is provided for them to ring to indicate when the film should be cut and then resume, between scenes.', '02190_make_the_best_livestream_highlight_reel.jpg', '02190_make_the_best_livestream_highlight_reel_thumb.jpg'),
(674, '|2493|', 1, '|3|', 1, 'Build a bridge for a vegetable', 'In this team task, the contestants are instructed to build as high a bridge as possible to elevate a vegetable (e.g. potato or swede) above a designated mat or platform.|If anything touches the mat or platform, they must clear everything away and begin again from a position designated as \'the drawing board\'.', '02493_build_a_bridge_over_the_red_green_for_this_potato.jpg', '02493_build_a_bridge_over_the_red_green_for_this_potato_thumb.jpg'),
(675, '|2386|', 4, '|3|', 1, 'Service bell helmet tag', 'In this live studio task, the contestants are all blindfolded and wearing helmets, on top of which service bells have been mounted.|The objective is to eliminate one another by ringing the service bell on the other contestants\' helmets.|The game takes place within a roped-off arena on stage.|The contestants may be provided with safety equipment, such as boxing gloves, and knee and elbow pads.', '02386_service_bell_helmet_tag.jpg', '02386_service_bell_helmet_tag_thumb.jpg'),
(676, '|3488|', 8, '|1|', 1, 'Recreate a famous work of art', 'In this task, the contestants are instructed to bring a famous piece of art to life.', '03488_bring_a_classic_artwork_to_life.jpg', '03488_bring_a_classic_artwork_to_life_thumb.jpg'),
(677, '|1513|', 3, '|4|', 1, 'Don\'t get fruit on the pizza', 'In this live studio task, the contestants must take turns throwing fruit at a target on the stage floor, in the centre of which there is a pizza.|The aim of the task is to land the fruit on the target, but not on the pizza itself.|In some versions, the contestant whose fruit lands closest to the pizza in each round is eliminated, while, in others, the contestant whose fruit lands furthest from the pizza is eliminated.', '01513_dont_get_fruit_on_the_pizza.jpg', '01513_dont_get_fruit_on_the_pizza_thumb.jpg'),
(678, '|2425|', 4, '|1|', 1, 'Something which prompts a specific exclamation from the Taskmaster', 'In this prize task, the contestants are instructed to bring in something which will prompt the Taskmaster to utter a specific exclamation.', '02425_something_that_makes_b%C3%A5rd_exclaim_oi_oi_oi_you_big_alpaca.jpg', '02425_something_that_makes_b%C3%A5rd_exclaim_oi_oi_oi_you_big_alpaca_thumb.jpg'),
(679, '|1088|', 3, '|4|14|', 2, 'Invent a new two-player sport', 'In this task, the contestants are instructed to create a new sport and compete against the Taskmaster\'s assistant in it.', '01088_invent_a_new_olympic_sport.jpg', '01088_invent_a_new_olympic_sport_thumb.jpg'),
(680, '|2809|', 1, '|13|', 1, 'Pie the air-dancer in the face', 'In this task, the contestants are instructed to pie an air-dancer in the face using a plate full of shaving cream.|The contestants are not permitted to touch the air-dancer, nor step foot on the circular mat on which it is positioned.|Every time the contestant misses the air-dancer\'s face with a pie, they must imitate its dance moves for 10 seconds.', '02809_pie_the_air_dancer_in_the_face.jpg', '02809_pie_the_air_dancer_in_the_face_thumb.jpg'),
(681, '|444|', 1, '|13|', 1, 'The best thing with springs in it', 'In this prize task, the contestants are instructed to bring in the best thing which probably, or actually, contains one or more springs.', '00444_the_best_thing_that_probably_has_a_spring.jpg', '00444_the_best_thing_that_probably_has_a_spring_thumb.jpg'),
(682, '|238|', 1, '|11|13|', 2, 'Knock over the ducks without leaving the carpet', 'In this team task, the contestants must knock over as many rubber ducks as possible without leaving a circular red carpet.|They begin the task with onlya  watermelon.', '00238_knock_over_the_ducks_without_leaving_the_carpet.jpg', '00238_knock_over_the_ducks_without_leaving_the_carpet_thumb.jpg'),
(683, '|3272|', 14, '|4|', 1, 'Share a childhood memory via an auto-tuned microphone', 'In this live studio task, the contestants must share childhood stories via an autotuned microphone without the Taskmaster identifying them.|The last contestant standing wins.', '03272_share_a_beautiful_childhood_memory_via_an_auto_tuned_microphone.jpg', '03272_share_a_beautiful_childhood_memory_via_an_auto_tuned_microphone_thumb.jpg'),
(684, '|841|', 1, '|13|', 1, 'The best thing you can operate with a hand', 'In this prize task, the contestants must bring in the best thing you can operate with a hand.', '00841_the_best_thing_you_can_operate_with_your_hand.jpg', '00841_the_best_thing_you_can_operate_with_your_hand_thumb.jpg'),
(685, '|2711|', 1, '|13|', 1, 'Move the giant duck through the course', 'In this task, the contestants must move a giant inflatable duck through an obstacle course without touching its beak or hitting any of the obstacles.|Each obstacle they hit adds another minute to their completion time, and the fastest contestant wins.', '02711_get_the_duck_into_the_lake.jpg', '02711_get_the_duck_into_the_lake_thumb.jpg'),
(686, '|2784|', 1, '|6|11|13|', 3, 'Get all of the water into the vase', 'In this task, the contestants must transfer all of the water on a plate into a vase without spilling a drop.|The most effective solution to the task is a well-known science-based trick, which had previously been used by Katherine Ryan as <a href=\"/attempt.php?id=955\">one of her ‘miracles’</a> during the first Champion of Champions special. Clues and equipment for this solution are provided in the room.', '02784_get_all_of_the_water_into_the_vase.jpg', '02784_get_all_of_the_water_into_the_vase_thumb.jpg'),
(687, '|2109|', 8, '|6|14|', 2, 'Win the collaborative debate', 'In this live team task, the contestants must argue for or against moots collaboratively as a team, by alternately saying lines or words of their arguments.|This may be complicated further by rules stating that each second line must rhyme with the one before it, or that each word must be spoken into a shared microphone (while the contestants are fastened together, back-to-back).|The teams may have a certain number of lines, or a certain time limit, within which they must make their arguments.|The team which wins the most debates wins the task.', '02109_the_rhyming_debate.jpg', '02109_the_rhyming_debate_thumb.jpg'),
(688, '|1620|', 4, '|4|', 1, 'Something you shouldn’t have', 'In this prize task, the contestants must bring in something they shouldn\'t own.', '01620_something_you_have_but_should_not.jpg', '01620_something_you_have_but_should_not_thumb.jpg'),
(689, '|2096|', 9, '|4|', 1, 'The secret task brief', 'In this special task, a task brief is hidden somewhere for one of the contestants to find during filming. If found, the contestant who finds it earns a potentially game-changing number of extra points.', '02096_the_secret_task_brief.jpg', '02096_the_secret_task_brief_thumb.jpg'),
(690, '|1884|', 9, '|1|13|', 2, 'The most underrated item', 'In this prize task, the contestants must bring in the most underrated or underestimated item', '01884_the_most_undervalued_item.jpg', '01884_the_most_undervalued_item_thumb.jpg'),
(691, '|399|', 1, '|11|13|', 2, 'Fill a tray with things beginning with the letter you chose', 'In this task, the contestants are first instructed to choose a letter of the alphabet, and must then fill a tray held by the Taskmaster\'s assistant with as many items which start with that letter as possible.', '00399_fill_a_tray_with_things_beginning_with_a_letter.jpg', '00399_fill_a_tray_with_things_beginning_with_a_letter_thumb.jpg'),
(692, '|2952|', 3, '|4|', 1, 'Create a chain reaction to pop the balloon', 'In this task, the contestants must create a chain reaction to pop a balloon.|The winner is the contestant whose chain reaction contains the most steps.|They may be required to use a specific piece of equipment in the chain reaction, or there may be bonus points on offer if they incorporate a specific piece of equipment.', '02952_create_a_chain_reaction_to_pop_the_balloon.jpg', '02952_create_a_chain_reaction_to_pop_the_balloon_thumb.jpg'),
(693, '|2672|', 8, '|14|', 1, 'Improve the Taskmaster’s assistant', 'In this task, the contestants are instructed to improve the Taskmaster\'s assistant in some way.', '02672_improve_paul.jpg', '02672_improve_paul_thumb.jpg'),
(694, '|3154|', 1, '|14|', 1, 'Identify the contents of the gloves', 'In this task, the contestants must attempt to identify the contents of a series of washing-up gloves by shaking hands with them.|They may or may not be permitted to cut the fingers off of some of the gloves.|They may or may not be required to then identify the name of an individual, based on the first letters of the contents they have identified.|Clues to the contents of the gloves may or may not be provided in the task location.', '03154_work_out_who_you_are_shaking_hands_with.jpg', '03154_work_out_who_you_are_shaking_hands_with_thumb.jpg'),
(695, '|2353|', 4, '|3|15|', 2, 'Get the most stuff through a sieve', 'In this task, the contestants must try to get as much stuff as possible through a sieve.|The stuff provided may be a variety of objects and foodstuffs, or a large quantity of just one thing (e.g. digestive or gingerbread biscuits).', '02353_get_as_much_weight_as_possible_into_the_glass_cylinder.jpg', '02353_get_as_much_weight_as_possible_into_the_glass_cylinder_thumb.jpg'),
(696, '|89|', 1, '|13|', 1, 'The most attractive family member', 'In this prize task, the contestants must bring in their most attractive family member (or, at least, a photo of them).', '00089_the_most_handsome_relative.jpg', '00089_the_most_handsome_relative_thumb.jpg'),
(697, '|2205|', 1, '|13|', 1, 'The most useless thing that cost over a certain amount', 'In this prize task, the contestants must bring in the most useless thing that cost over a certain amount of money.', '02205_the_most_useless_thing_that_cost_over_%C2%A320.jpg', '02205_the_most_useless_thing_that_cost_over_%C2%A320_thumb.jpg'),
(698, '|333|', 1, '|13|', 1, 'Convey an object using limited means of communication', 'In this team task, one of the contestants must convey the contents of a chest to their team-mates, using limited means of communication.|The means of communication available to them change throughout the task, as the minutes pass, and typically include: making facial expressions, making sounds, shouting adjectives, and whispering verbs.', '00333_convey_the_hidden_object.jpg', '00333_convey_the_hidden_object_thumb.jpg'),
(699, '|379|', 1, '|13|', 1, 'Retrieve your duck while wearing inversion goggles', 'In this live studio task, the contestants must attempt to retrieve a rubber duck by hooking it on a long pole, while wearing inversion goggles.', '00379_hook_a_duck_while_wearing_inversion_goggles.jpg', '00379_hook_a_duck_while_wearing_inversion_goggles_thumb.jpg'),
(700, '|1267|', 2, '|1|2|14|15|', 7, 'Guess a value or quantity', 'In this live tie-breaker task, the contestants must guess a value or quantity, and the winner is the one who guesses closest to the correct answer.', '01267_guess_how_much_it_costs_to_rescue_a_cat.jpg', '01267_guess_how_much_it_costs_to_rescue_a_cat_thumb.jpg'),
(701, '|2738|', 1, '|3|', 1, 'Choose a new nickname', 'In this task, the contestants are instructed to choose a new nickname for themselves, based on something they do during the time allotted for the task.', '02738_choose_a_new_nickname.jpg', '02738_choose_a_new_nickname_thumb.jpg'),
(702, '|1241|', 8, '|3|', 1, 'Prepare and then un-prepare some food', 'In this live task, the contestants are provided with some ingredients and instructed to make a dish of some description (e.g. a salad or cake) for the Taskmaster.|After they\'ve finished their culinary creations, the Taskmaster decides that they don\'t want the dish after all, and the contestants are then instructed to return all of the ingredients to their original spots on the table.|A possibly helpful trick, if spotted, is that all of the ingredients are arranged on the table in alphabetical order.', '01241_prepare_your_salad_unprepare_your_salad.jpg', '01241_prepare_your_salad_unprepare_your_salad_thumb.jpg'),
(703, '|2357|', 14, '|3|', 1, 'Remove the balloon from the caravan', 'In this task, the contestants must remove a helium balloon from inside a caravan without entering or touching the caravan.', '02357_remove_the_balloon_from_the_caravan.jpg', '02357_remove_the_balloon_from_the_caravan_thumb.jpg'),
(704, '|2705|', 8, '|3|', 1, 'Roll an egg from the desk to another location', 'In this task, the contestants must roll an egg from a desk to another location, but are not permitted to move while the egg itself is moving.|The winner is the person who achieves the goal with the least total egg touches.', '02705_roll_an_egg_from_the_desk_to_your_locker.jpg', '02705_roll_an_egg_from_the_desk_to_your_locker_thumb.jpg'),
(705, '|2575|', 1, '|3|6|', 2, 'Work out a number based on the flavours of some sweets', 'In this task, the contestants must identify a number by tasting a series of custom-flavoured sweets.|The potential flavours of the sweets are listed on a menu in the room, and the first letters of those flavours correspond to chemical elements. The correct number is then based on the atomic weights of the relevant elements.|In team versions of the task, the contestants must use the numbers identified to unlock some combination locks, free themselves from some handcuffs and chains, and then have a team hug. The key for the contestants\' handcuffs is usually hidden in plain sight in the room, but is small enough that it is easy to miss.|In solo versions of the task, the goal may simply be to arrive at a correct number, using basic arithmetic.', '02575_free_yourselves_and_have_a_team_hug.jpg', '02575_free_yourselves_and_have_a_team_hug_thumb.jpg'),
(706, '|2921|', 1, '|3|6|9|', 5, 'Choose your own disadvantage', 'In this task, the contestants must choose a disadvantage for themselves, either in the task at hand, or in the next task they are assigned.|It may be a completely free choice, or a choice of one or more predefined disadvantages.|In the case where they are selecting from a pre-existing list of disadvantages, their result in the actual task to be completed may benefit from them selecting more than one of the options, as a multiplier may be applied.', '02921_disadvantage_yourself_in_the_next_task.jpg', '02921_disadvantage_yourself_in_the_next_task_thumb.jpg'),
(707, '|2369|', 14, '|3|', 1, 'Do the bravest thing with a given item', 'In this task, the contestants are instructed to do the bravest thing with a given item.|The item might be preselected for them, or they might be given a choice between two or more options.', '02369_do_the_bravest_thing_with_a_ream_of_paper.jpg', '02369_do_the_bravest_thing_with_a_ream_of_paper_thumb.jpg'),
(708, '|2511|', 1, '|3|', 1, 'Know the most facts about sausages', 'In this task, the contestants are instructed to learn as much about sausages as possible from a provided fact sheet or pamphlet.|They are then asked questions about sausages and must either try to answer the most questions correctly, or be the first to answer a given number of them correctly.|This task has been used as both a live task with a very brief study window, and as a homework task in which the contestants had 100 days to learn about sausages before being quizzed in the studio.', '02511_know_the_most_facts_about_sausages.jpg', '02511_know_the_most_facts_about_sausages_thumb.jpg'),
(709, '|2757|', 1, '|3|11|', 2, 'Complete all the tasks as a team', 'In this team task, the contestants have to complete a series of mini-tasks together as a team as quickly as possible.|The task briefs have been attached to the outfits they are wearing, and they must begin and end the task wearing a bucket on their heads.|The task is complicated by the fact that one of the contestants must always be looking at one of their team-mates, one must constantly smile and shake their head, and one must shout anything they say.', '02757_complete_all_the_tasks_as_a_team.jpg', '02757_complete_all_the_tasks_as_a_team_thumb.jpg'),
(710, '|2899|', 1, '|3|', 1, 'Throw a ball into a bathtub full of balls', 'In this live studio task, the contestants must take turns at throwing chosen balls into a bathtub which is already full to the brim with balls.|The contestants are eliminated if any balls end up on the floor, with the winner being the last one standing.', '02899_throw_a_ball_into_a_bathtub_full_of_balls.jpg', '02899_throw_a_ball_into_a_bathtub_full_of_balls_thumb.jpg'),
(711, '|2432|', 14, '|3|', 1, 'Do a once-in-a-lifetime thing', 'In this task, the contestants are instructed to complete a once-in-a-lifetime feat.', '02432_do_an_incredible_once_in_a_lifetime_thing.jpg', '02432_do_an_incredible_once_in_a_lifetime_thing_thumb.jpg'),
(712, '|2790|', 1, '|3|', 1, 'Pineapple bluff', 'In this live studio task, the contestants must try to fool the Taskmaster into believing that they are hiding a pineapple when they are not, or not hiding a pineapple when they are.', '02790_pineapple_bluff.jpg', '02790_pineapple_bluff_thumb.jpg'),
(713, '|2712|', 1, '|3|6|', 2, 'Heavier or lighter?', 'In this live studio task, the contestants must attempt to correctly guess which of two given items is the heaviest.', '02712_heavier_or_lighter.jpg', '02712_heavier_or_lighter_thumb.jpg'),
(714, '|3449|', 8, '|4|', 1, 'Something another contestants would like', 'In this prize task, the contestants are instructed to bring in something they think that one of the other contestants would like.', '03449_the_best_thing_that_another_contestant_will_really_want.jpg', '03449_the_best_thing_that_another_contestant_will_really_want_thumb.jpg'),
(715, '|3232|', 14, '|4|', 1, 'Dance in the silent disco', 'In this live studio task, the contestants must attempt to fool the Taskmaster into believing that they can hear music when they can\'t, or can\'t hear music when they can, by dancing in silent disco.', '03232_dance_in_the_silent_disco.jpg', '03232_dance_in_the_silent_disco_thumb.jpg'),
(716, '|3059|', 1, '|3|4|', 2, 'Do the riskiest thing with this egg', 'In this task, the contestants must do the riskiest thing with a raw egg without breaking it.', '03059_do_the_riskiest_thing_with_this_egg.jpg', '03059_do_the_riskiest_thing_with_this_egg_thumb.jpg'),
(717, '|2484|', 14, '|3|', 1, 'Open the golden present', 'In this task, the contestants must find and open a golden present.|Clues are provided inside five other wrapped presents to lead them to the location of the golden present.|The contestants must remember to sing a song of a specific type (e.g. Christmas carol or birthday song) before opening each present.', '02484_open_the_golden_present.jpg', '02484_open_the_golden_present_thumb.jpg'),
(718, '|2691|', 8, '|3|', 1, 'Incorporate keywords into acceptance speeches', 'In this live task, the contestants must choose a trophy and then make an acceptance speech which incorporates a word written on the bottom of the trophy.|If the Taskmaster correctly identifies their designated keyword, they are eliminated from the game.', '02691_incorporate_keywords_into_acceptance_speeches.jpg', '02691_incorporate_keywords_into_acceptance_speeches_thumb.jpg'),
(719, '|1200|', 8, '|3|', 1, 'Build something out of dry edible building blocks', 'In this team task, the contestants must build something (e.g. a castle, or a replica of the Taskmaster\'s trophy) out of some form of dry, edible building block (e.g. wheat biscuits or crispbread).|The contestants begin the task with a limited number of dry building blocks, but can earn more every time they eat a whole one.', '01200_build_a_castle_out_of_wheat_biscuits.jpg', '01200_build_a_castle_out_of_wheat_biscuits_thumb.jpg'),
(720, '|1840|', 4, '|3|', 1, 'Get something into a receptacle from a chosen line', 'In this live task, the contestants must choose a box and a starting position, and then try to throw the contents of the box into one or more target receptacles on stage.|The contestants stand to earn more points by throwing their item(s) from as far away as possible, but risk being disqualified if they hit one or either of the hosts.', '01840_get_something_into_a_target_from_a_selected_line.jpg', '01840_get_something_into_a_target_from_a_selected_line_thumb.jpg'),
(721, '|2689|', 8, '|3|6|', 2, 'Win a point against the Taskmaster\'s assistant in a game of table tennis', 'In this task, the contestants must attempt to win a point against the Taskmaster\'s assistant in a game of table tennis.|Each time they lose a point, they must either put on another jacket, swap their racket out for one of a limited array of options, or make the assistant a sandwich. They may not use the same penalty twice in a row.', '02689_win_a_point_against_paul_in_table_tennis.jpg', '02689_win_a_point_against_paul_in_table_tennis_thumb.jpg'),
(722, '|2678|', 8, '|3|', 1, 'Become another contestant', 'In this task, the contestants must impersonate one of their fellow contestants. If they choose to portray the same contestant as another person, they will lose points.', '02678_become_another_contestant.jpg', '02678_become_another_contestant_thumb.jpg'),
(723, '|2283|', 1, '|6|', 1, 'Write a one-minute, one-person play', 'In this task, the contestants are given a short time to write a one-minute, one-person play.|The play is then typically performed by one of the other contestants in a follow-up task.', '02283_write_a_one_minute_one_person_play.jpg', '02283_write_a_one_minute_one_person_play_thumb.jpg'),
(724, '|2284|', 1, '|6|', 1, 'Perform a one-minute, one-person play', 'In this task, the contestants are presented with the script for a one-minute, one-person play which was written by one of the other contestants, and they must stage and perform it themselves.', '02284_perform_a_one_minute_one_person_play.jpg', '02284_perform_a_one_minute_one_person_play_thumb.jpg'),
(725, '|2259|', 1, '|6|', 1, 'Find your hand', 'In this task, the contestants enter a room where the walls are covered with thousands of photos of other people\'s hands, and must attempt to find the one image of their own hand in the fewest guesses.|They may eliminate entire boards full of images by adding 100 guesses to their total for each board, to narrow the odds.|A laser pointer is also provided in the room which, if slotted into a provided holder at ceiling level, will bounce off of two mounted mirrors and highlight the correct image.', '02259_find_the_back_of_your_hand.jpg', '02259_find_the_back_of_your_hand_thumb.jpg'),
(727, '|1943|', 1, '|9|13|', 2, 'The most surprising item from your wardrobe', 'In this prize task, the contestants must bring in the most surprising thing from their wardrobe or closet.', '01943_the_most_surprising_thing_from_your_wardrobe.jpg', '01943_the_most_surprising_thing_from_your_wardrobe_thumb.jpg'),
(728, '|2710|', 1, '|13|', 1, 'Cross the finish line while connected to your team', 'In this team task, the contestants are first instructed to attach as many parts of their bodies together as possible.|The actual aim of the task, though, is to pass through a finish line while attached together, as quickly as possible.', '02710_cross_the_finish_line_while_connected_to_your_team.jpg', '02710_cross_the_finish_line_while_connected_to_your_team_thumb.jpg'),
(729, '|2206|', 1, '|6|', 1, 'Get the most pleasure from these rubber chutes', 'In this task, the contestants are presented with a set of large rubber chutes (as are used to remove refuse from the upper floors of a building during construction), and are instructed to derive the most pleasure from them as possible.', '02206_get_the_most_pleasure_from_these_rubber_chutes.jpg', '02206_get_the_most_pleasure_from_these_rubber_chutes_thumb.jpg'),
(730, '|2126|', 8, '|6|', 1, 'Move the water from this bathtub to that bathtub', 'In this task, the contestants are instructed to move as much water as possible from one bathtub to another.|The contestants must wear a belt throughout the task, through the loop of which a chain connecting both bathtubs\' plugs passes.', '02126_move_the_water_from_this_bathtub_to_that_bathtub.jpg', '02126_move_the_water_from_this_bathtub_to_that_bathtub_thumb.jpg'),
(731, '|2759|', 1, '|6|', 1, 'Roll your animal die', 'In this live studio task, the contestants are provided with a large blank-faced die each, and must write the name of a species of animal on each face.|The Taskmaster then reads out a series of categories, and the contestants must roll their dice.|The taskmaster then decides which of the rolled animal species best matches the given category, and the contestant who rolled that die is eliminated from the game.', '02759_roll_your_animal_die.jpg', '02759_roll_your_animal_die_thumb.jpg'),
(732, '|2078|', 8, '|6|', 1, 'Prove that you’re the smartest', 'In this task, the contestants must somehow prove that they are smarter than all of their competitors.', '02078_prove_that_youre_the_smartest.jpg', '02078_prove_that_youre_the_smartest_thumb.jpg'),
(733, '|2242|', 4, '|6|', 1, 'Give the Taskmaster’s assistant the Nth longest hug', 'In this task, the contestants must aim to give the Taskmaster’s assistant the Nth longest hug (e.g. second or third longest).|Those who give the shortest and longest hugs may be disqualified.|Bonus points may be offered to those who are able to correctly predict which contestants give the longest and shortest hugs.', '02242_give_olli_the_third_longest_hug.jpg', '02242_give_olli_the_third_longest_hug_thumb.jpg'),
(734, '|2460|', 1, '|13|', 1, 'Have the best first wedding dance with the Taskmaster\'s assistant', 'In this task, the contestants must perform the best first wedding dance with the Taskmaster\'s assistant, while both of them listen to music of their choice on headphones.', '02460_have_the_best_first_wedding_dance_with_alex.jpg', '02460_have_the_best_first_wedding_dance_with_alex_thumb.jpg'),
(735, '|2669|', 8, '|6|', 1, 'Collect table tennis balls on your helmet plate', 'In this live studio task, the contestants must collect the most table tennis balls on the plate attached to their helmet.|This is complicated by the requirement to place their hands on their hips whenever some green lights are turned on, with the person who does this last being required to bow deeply to the Taskmaster, thus losing any balls they have collected.', '02669_collect_table_tennis_balls_on_your_helmet_plate.jpg', '02669_collect_table_tennis_balls_on_your_helmet_plate_thumb.jpg'),
(736, '|721|', 1, '|11|13|', 2, 'The best thing to bring to a party', 'In this prize task, the contestants must bring in the best thing to bring to a party.', '00721_the_best_thing_to_bring_to_a_party.jpg', '00721_the_best_thing_to_bring_to_a_party_thumb.jpg'),
(737, '|2054|', 8, '|6|', 1, 'Crack the crème brûlée', 'In this task, the contestants must attempt to crack a crème brûlée in the most satisfying way.', '02054_crack_the_creme_brulee.jpg', '02054_crack_the_creme_brulee_thumb.jpg'),
(738, '|179|', 1, '|6|', 1, 'Create a portfolio of photos of a specific object in good company', 'In this special homework task, one contestant is given a specific, slightly cumbersome object (e.g. a golden pineapple, or a cardboard cut-out of the Taskmaster), and is instructed to create a portfolio of photos of the object in good company.', '00179_the_golden_pineapple_portfolio.jpg', '00179_the_golden_pineapple_portfolio_thumb.jpg'),
(739, '|2277|', 13, '|6|', 1, 'Photograph a life-sized cut-out of the Taskmaster', 'In this homework task, the contestants are given a life-sized cardboard cut-out of the Taskmaster, and are instructed to photograph it in an unusual location.', '02277_photograph_a_life_sized_cut_out_in_an_unusual_location.jpg', '02277_photograph_a_life_sized_cut_out_in_an_unusual_location_thumb.jpg'),
(740, '|2080|', 8, '|6|', 1, 'Pull the rope to drop a specific object', 'In this task, the contestants are presented with an array of ropes attached to buckets, and must aim to pull the rope to drop a specific object (e.g. a rubber duck, or a potato) in as few pulls as possible.|The smart solution to the task is to identify that the objects in the buckets are arranged alphabetically.', '02080_pull_the_rope_to_drop_the_duck.jpg', '02080_pull_the_rope_to_drop_the_duck_thumb.jpg'),
(741, '|1574|', 3, '|6|', 1, 'Rock, paper, scissors', 'In this tie-breaker task, the winner of the episode is decided through a game of \'Rock, paper, scissors\' - either best of three games, or sudden death.', '01574_rock_paper_scissors.jpg', '01574_rock_paper_scissors_thumb.jpg'),
(742, '|1238|', 8, '|13|', 1, 'Untie the shoelaces', 'In this special task, one contestant is instructed to untie a bunch of shoelaces, which may or may not actually be attached to shoes.', '01238_untie_the_shoelaces.jpg', '01238_untie_the_shoelaces_thumb.jpg'),
(743, '|2577|', 1, '|6|', 1, 'The imitation game', 'In this live studio task, the contestants must take turns at imitating regional accents or dialects.|In one case, they are also instructed to imitate the walks of their competitors.|In cases where the win condition for the game is earning the most points, each correct guess by the Taskmaster about what/who the contestant is imitating earns them an in-game point.|In cases where the winner is the last one standing, an incorrect guess by the Taskmaster eliminates the contestant from the game.', '02577_imitate_accents_walks.jpg', '02577_imitate_accents_walks_thumb.jpg'),
(744, '|2108|', 8, '|6|', 1, 'Film a scene from a movie', 'In this task, the contestants are instructed to film a scene from a movie, in which they will all play the same character.|Each contestant is instructed to begin and end their scene with a specific action, so that the scenes may then be edited together into a single exquisite corpse of a continuous short film.', '02108_the_presidential_blockbuster.jpg', '02108_the_presidential_blockbuster_thumb.jpg'),
(745, '|1960|', 1, '|6|', 1, 'Use a cement mixer', 'In this task, the contestants are instructed to find a use for a cement mixer other than mixing cement.', '01960_use_a_cement_mixer.jpg', '01960_use_a_cement_mixer_thumb.jpg'),
(746, '|3684|', 15, '|4|16|', 2, 'Deliver food or drink to someone without stepping on something', 'In this task, the contestants are instructed to deliver a drink or some food to either the Taskmaster\'s assistant\'s friend (who happens to be an anthropomorphic inanimate object, such as a mannequin or scarecrow), or to the Taskmaster\'s assistant themselves, without stepping on grass or within a designated area.', '03684_deliver_a_medium_mocha_to_mikes_mate_mark.jpg', '03684_deliver_a_medium_mocha_to_mikes_mate_mark_thumb.jpg'),
(747, '|3764|', 15, '|16|', 1, 'Throw a feather as far as possible', 'In this task, the contestants are instructed to throw a feather as far as possible.|When used as a tie-breaker, the contestants may be restricted to throwing the feather from a specific location, and with no additional equipment.', '03764_throw_a_feather.jpg', '03764_throw_a_feather_thumb.jpg'),
(748, '|3665|', 15, '|16|', 1, 'Complete a series of actions while estimating time', 'In this live studio task, the contestants are instructed to perform a series of actions while mentally keeping track of time.', '03665_sit_wave_and_swim_for_30_seconds.jpg', '03665_sit_wave_and_swim_for_30_seconds_thumb.jpg'),
(749, '|1151|', 8, '|16|', 1, 'The best green thing', 'In this prize task, the contestants must bring in the best or most impressive green thing.', '01151_the_best_green_thing.jpg', '01151_the_best_green_thing_thumb.jpg'),
(750, '|3662|', 15, '|16|', 1, 'Get the most different things in The Taskmaster\'s assistant\'s hat', 'In this task, the contestants must attempt to get as many different things as possible into the Taskmaster\'s assistant\'s hat.|The Taskmaster\'s assistant is sat on a rotating turntable in the centre of an area of the ground within which the contestants may not step, and is wearing a very tall stovepipe hat with no top.', '03662_get_the_most_different_things_in_mikes_hat.jpg', '03662_get_the_most_different_things_in_mikes_hat_thumb.jpg'),
(751, '|3778|', 15, '|16|', 1, 'Write a poem about your idol', 'In this task, the contestants must write and perform a poem about their celebrity idol.|In one version of the task, they are also required to spin a hula hoop while performing their poem.', '03778_write_a_poem_about_your_favourite_celebrity.jpg', '03778_write_a_poem_about_your_favourite_celebrity_thumb.jpg'),
(752, '|3700|', 15, '|16|', 1, 'Recall the 15 words you said at the beginning', 'In this task, the contestants are first instructed to list 15 very different words in a short period.|They are then distracted with some additional completely irrelevant activities (typically, covering their face in shaving foam, and then catching petals on their faces as they are blown across the room) before being asked to recall of the words they had listed.|The winner is the one who can correctly recall the most words.', '03700_recall_the_15_words_you_said_at_the_beginning.jpg', '03700_recall_the_15_words_you_said_at_the_beginning_thumb.jpg'),
(753, '|3102|', 1, '|16|', 1, 'The best thing to turn upside-down', 'In this prize task, the contestants are instructed to bring in the \'most fun\', or \'most interesting\' thing to turn upside-down.', '03102_the_most_fun_thing_to_turn_upside_down.jpg', '03102_the_most_fun_thing_to_turn_upside_down_thumb.jpg'),
(754, '|2343|', 3, '|11|', 1, 'Count the occurrences of a sound or letter in a song', 'In this live task, the contestants are instructed to count the occurrences of a particular sound or letter in a song which is being performed live in the studio.', '02343_count_the_bas.jpg', '02343_count_the_bas_thumb.jpg'),
(755, '|2684|', 8, '|6|', 1, 'Find a new use for a roll of tape', 'In this task, the contestants are instructed to come up with a new use for a roll of tape.|They may be instructed to find the most brilliant new use for the tape, or to decide between coming up with the most or least ingenious use.', '02684_use_a_roll_of_tape_in_a_brilliant_way.jpg', '02684_use_a_roll_of_tape_in_a_brilliant_way_thumb.jpg'),
(756, '|3511|', 1, '|6|11|', 2, 'Knock down a specific number of cans', 'In this task, the contestants are instructed to knock over a specific number of cans from a series of stacks a short distance away.|The contestants must remain on their marker spot throughout the task, but may throw a number of different types of ball at the cans, and pull on one rope attached to the stacks.', '03511_knock_over_exactly_100_cans.jpg', '03511_knock_over_exactly_100_cans_thumb.jpg'),
(757, '|3454|', 8, '|3|6|', 2, 'Pinch, protect, or plunder', 'In this live studio task, each contestant begins with three objects (e.g. balls or potatoes) in front of them, representing points.|Over a number of rounds, they must then decide whether to pinch one object from another contestant, protect their own objects, or plunder all of the objects from someone.|If they choose to protect their objects, they cannot be plundered, but other contestants may still pinch a single object from them.|The winner is the contestant with the most objects left at the end of the task.', '03454_pinch_protect_or_plunder.jpg', '03454_pinch_protect_or_plunder_thumb.jpg'),
(758, '|1676|', 1, '|6|9|', 2, 'Daringly put an egg in an eggcup', 'In this task, the contestants must attempt to put an egg into an eggcup in the most daring way without breaking it.', '01676_daringly_put_the_egg_in_the_eggcup.jpg', '01676_daringly_put_the_egg_in_the_eggcup_thumb.jpg'),
(759, '|963|', 1, '|6|', 1, 'Make art with a photocopier', 'In this task, the contestants are instructed to create an image of something (e.g. a dinosaur, or a Santa Claus) using just a photocopier.', '00963_make_the_best_picture_of_a_big_scary_dinosaur.jpg', '00963_make_the_best_picture_of_a_big_scary_dinosaur_thumb.jpg'),
(760, '|3133|', 1, '|3|', 1, 'Catch the most monsters in your boxes', 'In this live studio task, the contestants must attempt to catch the most spring-loaded pop-up monster toys in a variety of containers attached to parts of their body, each of which is worth a different number.', '03133_catch_the_most_monsters_in_your_boxes.jpg', '03133_catch_the_most_monsters_in_your_boxes_thumb.jpg'),
(762, '|3057|', 4, '|3|', 1, 'Blindly reach and press the red button', 'In this live studio task, the contestants are led to believe that they will need to traverse an obstacle course on stage while blindfolded, to reach and press a red button.|Once they put on their blindfolds, all of the obstacles are removed, leaving the contestants to crawl unnecessarily around the stage until they find the button.', '03057_blindly_reach_and_press_the_red_button.jpg', '03057_blindly_reach_and_press_the_red_button_thumb.jpg'),
(763, '|764|', 4, '|3|', 1, 'Make two toddlers laugh at the same time', 'In this task, the contestants must attempt to make two toddlers laugh at the same time.', '00764_make_two_toddlers_laugh_at_the_same_time.jpg', '00764_make_two_toddlers_laugh_at_the_same_time_thumb.jpg'),
(764, '|2967|', 4, '|3|', 1, 'Hide the rubber duck / Find the rubber duck', 'In this task, the contestants are first instructed to hide a rubber duck from a contestant within a specific room.|They are then instructed to find a rubber duck hidden by a contestant.|The wording of the task brief is intentionally ambiguous to lead the contestant to believe that another contestant has already hidden a rubber duck in the room for them to find, when, in fact, they simply need to retrieve the duck which they themselves have hidden.|If they were to think about the task with a clear mind, they might realise that there’s no way it could be filmed so that every contestant is looking for a duck hidden by another, since there would not be a duck for the first contestant filming the task to find.', '02967_hide_the_rubber_duck_find_the_rubber_duck.jpg', '02967_hide_the_rubber_duck_find_the_rubber_duck_thumb.jpg'),
(765, '|2879|', 1, '|3|', 1, 'Will it fit through the hole?', 'In this live studio task, the contestants must predict whether a series of objects will fit through a series of holes cut into some panels.', '02879_will_it_fit_through_the_hole.jpg', '02879_will_it_fit_through_the_hole_thumb.jpg'),
(766, '|3104|', 1, '|3|', 1, 'Do something epic using green-screen', 'In this task, the contestants are instructed to do something \'epic\' or \'cool\' using green-screen.|It may be presented as either a team or solo task.|The contestants may have free reign over the amount of green-screen they use, or may be limited to just a green-screen body suit worn by the Taskmaster\'s assistant.', '03104_do_something_epic_using_green_screen.jpg', '03104_do_something_epic_using_green_screen_thumb.jpg'),
(767, '|3206|', 1, '|3|6|', 2, 'Write answers to the Taskmaster\'s questions based on the letter you’ve chosen', 'In this live studio task, the contestants are first instructed to write down a letter of the alphabet.|They must the come up with answers to the Taskmaster\'s questions which start with the correct letter, which is a given offset (forwards or backwards) from the letter they chose.|The alphabet is considered to wrap around, for the purposes of this task.|The slowest to come up with a valid answer in each round is eliminated.', '03206_write_answers_to_gregs_questions_based_on_the_letter_you_have_chosen.jpg', '03206_write_answers_to_gregs_questions_based_on_the_letter_you_have_chosen_thumb.jpg'),
(768, '|2683|', 8, '|3|', 1, 'Direct your team-mate through the maze', 'In this team task, one team member is blindfolded, and their team-mate(s) must guide them through a rope maze without repeating any words in their instructions.|Any time a word is repeated or a rope is touched, the team must start again from the beginning.', '02683_direct_your_team_mate_through_the_maze.jpg', '02683_direct_your_team_mate_through_the_maze_thumb.jpg'),
(769, '|3256|', 1, '|3|6|', 2, 'Pop up from behind the wall', 'In this live studio task, the contestants must hide behind a wall, in one of five sections, and the Taskmaster then has to guess which section they are hidden in.|Each time the Taskmaster guesses correctly, that contestant is eliminated.', '03256_pop_up_from_behind_the_wall.jpg', '03256_pop_up_from_behind_the_wall_thumb.jpg'),
(770, '|3579|', 1, '|4|', 1, 'Direct the robot to its charging station', 'In this task, the contestants must direct a person wearing a robot costume to a charging station.|They either must, or may only, provide instructions to the robot on a regular schedule (e.g. every 10 or 15 seconds).|The robot may ignore instructions which contain certain letters.', '03579_direct_the_robot_to_its_charging_station.jpg', '03579_direct_the_robot_to_its_charging_station_thumb.jpg'),
(771, '|3015|', 4, '|3|', 1, 'Do the most different things in a limited time', 'In this task, the contestants must first write down on a chalkboard as many different actions as they believe they can complete within a limited period of time (e.g. 70 or 100 seconds).|They must then attempt to complete all of those actions in the given time window.|The contestants earn an in-task point for every action completed, but lose 5 in-task points for every action not completed.|In some versions, the contestants may also not earn points for completing any actions that were also completed by another contestant.|The winner is the person with the most in-task points.', '03015_do_the_most_different_things_in_70_seconds.jpg', '03015_do_the_most_different_things_in_70_seconds_thumb.jpg'),
(772, '|3438|', 8, '|3|', 1, 'Fan out your flame', 'In this live studio task, the contestants are provided with a limited range of supplies, and must attempt to extinguish a candle in front of them as quickly as possible without leaving their marker spot or knocking the candle off its plinth.', '03438_fan_out_your_flame.jpg', '03438_fan_out_your_flame_thumb.jpg'),
(773, '|2696|', 8, '|3|', 1, 'Record a mildly interesting podcast', 'In this team task, the contestants must first choose a topic in which all of the members of the team are equally mildly interested.|They are then instructed to record a 20 minute podcast on that topic, with virtually no preparation time.', '02696_record_a_vaguely_interesting_podcast.jpg', '02696_record_a_vaguely_interesting_podcast_thumb.jpg'),
(774, '|3491|', 8, '|3|', 1, 'Multitask while remaining photogenic', 'In this live studio task, the contestants must eat a plate of pasta, while keeping a balloon up in the air, while participating in a quiz, and while attempting to remain photogenic throughout.|A camera set up in front of them takes their photo at a random point during the task, and the one who appears most photogenic wins.|There are also bonus points available to the contestants who eat the most pasta, and correctly answer the most questions.|Anyone who drops their balloon loses a point.', '03491_multitask_while_remaining_photogenic.jpg', '03491_multitask_while_remaining_photogenic_thumb.jpg'),
(775, '|3520|', 1, '|4|', 1, 'Wear a costume during a task to double your points', 'In this season-long task, the contestants are given the opportunity to don a specific costume before attempting any task, in order to double the points they earn during that task.', '03520_wear_the_hot_dog_outfit_in_a_future_task.jpg', '03520_wear_the_hot_dog_outfit_in_a_future_task_thumb.jpg'),
(776, '|3266|', 14, '|4|', 1, 'Draw a portrait of someone who drops by', 'In this task, filming is interrupted for some reason by a visitor to the room.|The contestants are then instructed to draw a portrait of the visitor, who is usually wearing some distinctive clothing or accessories.', '03266_draw_a_portrait_of_the_guy_with_the_ladder.jpg', '03266_draw_a_portrait_of_the_guy_with_the_ladder_thumb.jpg'),
(777, '|632|', 6, '|3|6|', 2, 'Invent something', 'In this task, usually presented as a homework task, the contestants must come up with and then reveal a new invention.', '00632_make_the_best_invention.jpg', '00632_make_the_best_invention_thumb.jpg'),
(778, '|3434|', 8, '|3|', 1, 'Legally distinct wooden block game', 'In this task, the contestants must remove blocks from a tower constructed of them, and follow the instructions written on each block, until the time runs out or the tower falls over.', '03434_legally_distinct_wooden_block_game.jpg', '03434_legally_distinct_wooden_block_game_thumb.jpg'),
(779, '|3462|', 8, '|3|', 1, 'Follow the Taskmaster\'s assistant\'s phonetic alphabet instructions', 'In this task, the taskmaster\'s assistant reads out the task brief over a radio, one letter at a time, using a phonetic radio alphabet.|The contestant who completes the instructions fastest loses, so the task is mostly about seeing who has the patience to sit and wait for the full instructions to be relayed to them.', '03462_follow_pauls_instructions.jpg', '03462_follow_pauls_instructions_thumb.jpg'),
(780, '|453|', 1, '|3|', 1, 'Roll an edible sphere across the finish line', 'In this live studio task, the contestants must roll edible spheres (i.e. round fruits, vegetables, or other foodstuffs) along a length of guttering as slowly as possible, without allowing them to stop, and while also keeping them moving fast enough to cross a finish line on the floor.|Any contestant whose spehere stops moving before crossing the finish line in a round is eliminated.|The contestant whose sphere crosses the finish line first in each round is also eliminated (though this may be waived if someone else\'s sphere stopped moving).', '00453_roll_an_edible_sphere_across_a_line_as_slowly_as_possible.jpg', '00453_roll_an_edible_sphere_across_a_line_as_slowly_as_possible_thumb.jpg'),
(781, '|3446|', 8, '|4|', 1, 'Build the tallest cardboard box tower while performing impressions', 'In this team task, the contestants must perform impressions of the people named on a series of cardboard boxes in order to then use those boxes in the construction of a tower.|The team with the tallest tower wins.', '03446_build_the_tallest_cardboard_box_tower_while_performing_impressions.jpg', '03446_build_the_tallest_cardboard_box_tower_while_performing_impressions_thumb.jpg'),
(782, '|189|', 1, '|11|', 1, 'The most awkward item to take home', 'In this prize task, the contestants must bring in the most awkward item to take home with them.', '00189_the_most_awkward_item_to_take_home.jpg', '00189_the_most_awkward_item_to_take_home_thumb.jpg'),
(783, '|442|', 1, '|3|', 1, 'Guess what is making the noises', 'In this live studio task, the contestants must guess what two items are being bashed together to create a series of noises.|The winner is the one who correctly guesses the most items.', '00442_guess_what_is_making_the_noises.jpg', '00442_guess_what_is_making_the_noises_thumb.jpg'),
(784, '|1361|', 1, '|3|', 1, 'Pop the balloons with your darts', 'In this live studio task, the contestants must take turns in trying to pop balloons with their darts, while not bursting the \'bad\' ones (which contain some sort of powder).|The goal of the task may be either to pop the most balloons, or to pop the last one.|There may or may not be requirements on how many darts must be thrown in each round, and how many balloons must be popped in each round.', '01361_pop_the_most_balloons.jpg', '01361_pop_the_most_balloons_thumb.jpg'),
(785, '|2112|', 8, '|3|', 1, 'Turn a dummy into your best friend', 'In this task, the contestants are instructed to turn a plain dummy into their best friend.|The task is usually followed by one or more tasks which utilise their best friend in other ways, such as \'<a href=\"/mastertask.php?id=787\">Throw weapons at your best friend</a>\'.', '02112_turn_a_dummy_into_your_best_friend.jpg', '02112_turn_a_dummy_into_your_best_friend_thumb.jpg'),
(786, '|3237|', 1, '|3|', 1, 'Bounce balls on a board', 'In this live studio task, the contestants must aim to bounce balls on a board a specific number of times, which increases with each round.|The contestants typically get two attempts to pass each round, before being eliminated.', '03237_bounce_a_ball_on_the_bar.jpg', '03237_bounce_a_ball_on_the_bar_thumb.jpg'),
(787, '|2115|', 8, '|3|', 1, 'Throw weapons at your best friend', 'In this follow-up task to the \'<a href=\"/mastertask.php?id=785\">Turn a dummy into your best friend</a>\' task, the contestants are forced to throw weapons at their best friend dummies in order to achieve a goal (e.g. knocking an apple off their head, or bursting some balloons).|The contestant who achieves the goal with the fewest attempts wins.', '02115_knock_the_apple_off_your_best_friends_head.jpg', '02115_knock_the_apple_off_your_best_friends_head_thumb.jpg'),
(788, '|2849|', 1, '|3|', 1, 'Pass the parade exam', 'In this live studio task, the Taskmaster\'s assistant performs on stage, involving several costume changes, while the Taskmaster narrates.|The contestants are then asked to answer a series of questions about what they\'ve just witnessed, with the winner being the one who correctly answers the most questions.', '02849_pass_the_parade_exam.jpg', '02849_pass_the_parade_exam_thumb.jpg'),
(789, '|1237|', 8, '|3|', 1, 'Locate the real Taskmaster\'s assistant', 'In this task, the contestants must find and then interact in some way with the Taskmaster\'s assistant (e.g. filming them, or throwing a ball at them).|The task is complicated by the fact that there are multiple other individuals in the area who are dressed exactly like the assistant.', '01237_get_the_most_footage_of_paul.jpg', '01237_get_the_most_footage_of_paul_thumb.jpg'),
(790, '|653|', 6, '|4|', 1, 'Give something fragile a good experience', 'In this homework task, the contestants are provided with something fragile (e.g. an egg, or porcelain figurine), and are instructed to photographically document the object having a good experience.', '00653_give_the_egg_the_best_holiday.jpg', '00653_give_the_egg_the_best_holiday_thumb.jpg'),
(791, '|2951|', 3, '|3|', 1, 'Run the Babben-race', 'In this task, the contestants must complete a race on a very short, straight track.|The task is complicated by additional rules, which may or may not be revealed to the contestants.', '02951_lose_the_babben_race.jpg', '02951_lose_the_babben_race_thumb.jpg'),
(792, '|3175|', 1, '|3|', 1, 'Completely cover your team-mate with rubber rings ', 'In this team live studio task, the contestants must attempt to completely cover one of their team-mates by throwing inflated rubber rings over them.', '03175_completely_cover_your_team_mate_in_rubber_rings.jpg', '03175_completely_cover_your_team_mate_in_rubber_rings_thumb.jpg'),
(793, '|3283|', 9, '|14|', 1, 'The most misunderstood thing', 'In this prize task, the contestants are instructed to bring in the most misunderstood thing.', '03283_the_most_misunderstood_object.jpg', '03283_the_most_misunderstood_object_thumb.jpg'),
(794, '|2944|', 4, '|3|6|9|', 3, 'Save the eggs from the blender', 'In this task, the contestants have a very limited time to rescue some raw eggs from a food blender, before it is turned on.|The contestants may not touch the eggs with their hands, or remove the blender from the room.|The time only passes while the contestants are standing inside the lab.|The winner is the person with the most intact eggs, at the end of the task.', '02944_save_the_eggs_from_the_blender.jpg', '02944_save_the_eggs_from_the_blender_thumb.jpg'),
(795, '|3572|', 4, '|3|6|', 2, 'Questions and lies', 'In this live studio task, the contestants must incorrectly answer the questions they are asked.|If they hesitate for too long or answer the questions correctly, they are eliminated.|The winner is the last person standing.', '03572_questions_and_lies.jpg', '03572_questions_and_lies_thumb.jpg'),
(796, '|3389|', 14, '|3|', 1, 'Break a dozen eggs from the furthest distance', 'In this task, the contestants are instructed to break a dozen eggs at the same time from the furthest distance.|For each egg which does not break, their distance is halved.|The task ends as soon as one or more eggs are broken.', '03389_break_a_dozen_eggs_from_the_furthest_distance.jpg', '03389_break_a_dozen_eggs_from_the_furthest_distance_thumb.jpg'),
(797, '|3431|', 8, '|3|', 1, 'Complete all the tasks on the roof', 'In this task, the contestants are instructed to complete all of the tasks on the roof, while standing in a room where there are multiple task briefs strung from the ceiling.|To further misdirect them into unnecessarily completing all of the task hanging from the ceiling, they are told that they can only touch the tasks using two long sticks, or pool cues.|The actual task to be completed is written on a large sheet attached to the roof of the house.', '03431_complete_all_the_tasks_on_the_roof.jpg', '03431_complete_all_the_tasks_on_the_roof_thumb.jpg'),
(798, '|2945|', 4, '|3|9|', 2, 'Make the bookcases identical', 'In this task, the contestants are first instructed to choose a handicap for the task: wearing a blindfold; not using their hands (being handcuffed); or not entering the room where the task must be completed.|They are then instructed to make two bookcases identical. One of the bookcases is stocked with a variety of items, duplicates of which are available to the contestants, while the other is completely empty.', '02945_make_the_bookcases_identical.jpg', '02945_make_the_bookcases_identical_thumb.jpg'),
(799, '|3496|', 8, '|3|', 1, 'Balance items on the table', 'In this live studio task, the contestants must take it in turns to choose an object from a pile on stage, and balance it on a small table.|If the contestants cause any items to fall from the pile on the table, they are eliminated from the task.|The last contestant standing wins.|Sometimes, a smaller table is introduced after the first couple of rounds, to increase the difficulty.', '03496_balance_items_on_the_table.jpg', '03496_balance_items_on_the_table_thumb.jpg'),
(800, '|3509|', 1, '|4|', 1, 'Something that’s been inside you', 'In this prize task, the contestants are instructed to bring in something that has been inside of them.', '03509_the_best_thing_that_has_been_inside_you.jpg', '03509_the_best_thing_that_has_been_inside_you_thumb.jpg'),
(801, '|3261|', 14, '|4|', 1, 'Move balls from one jar to another', 'In this task, the contestants must attempt to move balls from one large water cooler bottle to another, without touching them with their hands.|The task is complicated by the fact that either one or both of the bottles have had holes cut into their bases, meaning that the balls will spill out if the bottles are lifted.|The contestants are usually provided with a selection of questionably useful tools, to aid them in the task.', '03261_get_the_balls_from_this_jar_into_that_jar.jpg', '03261_get_the_balls_from_this_jar_into_that_jar_thumb.jpg'),
(802, '|2223|', 1, '|11|', 1, 'Strike the bullseye with your paint', 'In this task, the contestants are wearing a helmet with a full cup of paint on top of it, and must attempt to spill that paint on a target on the ground some distance away.|To reach the target, the contestants must only step on circular markers on the ground, which take them through a series of obstacles.|The contestants must also keep their hands below their waist at all times, and must step on all of the markers, which is complicated by the fact that some markers  have been placed within a nearby structure, and are therefore easy to miss.|The task is complicated further by a break in the path of markers, which forces the contestants to collect and re-use previous markers in order to reach the target.', '02223_strike_the_bullseye_with_your_paint.jpg', '02223_strike_the_bullseye_with_your_paint_thumb.jpg'),
(803, '|1282|', 1, '|11|', 1, 'Put on the medallion', 'In this live studio task, the contestants must extract a medallion from within a locked toolbox, and place it around their necks.|Unlocking the toolbox, and then another locked box within the toolbox, requires finding keys among the various items in the pockets of the long coats they are wearing.|The contestants are not allowed to remove the coats or damage the toolboxes.', '01282_put_on_the_medallion.jpg', '01282_put_on_the_medallion_thumb.jpg'),
(804, '|2875|', 1, '|11|', 1, 'The best thing to bring into a room full of strangers', 'In this prize task, the contestants are instructed to bring in the most fun - or best - thing to carry - or bring - into a room full of strangers.', '02875_the_most_fun_thing_to_carry_into_a_room_full_of_strangers.jpg', '02875_the_most_fun_thing_to_carry_into_a_room_full_of_strangers_thumb.jpg'),
(806, '|857|', 1, '|11|', 1, 'Make your rubber gloves and rubber boots as heavy as possible', 'In this live studio task, the contestants are instructed to make the rubber gloves and boots they are wearing as heavy as possible, while wearing them.|The contestants are each provided with a bucket full of cutlery and marbles (plus a roll of duct tape) to assist them in the task.', '00857_make_your_rubber_gloves_and_wellies_as_heavy_as_possible.jpg', '00857_make_your_rubber_gloves_and_wellies_as_heavy_as_possible_thumb.jpg'),
(807, '|3058|', 1, '|11|', 1, 'The most glorious thing that sounds like the Taskmaster’s name, when mumbled', 'In this prize task, the contestants must bring in the most glorious thing that sounds like the Taskmaster’s name, when mumbled.', '03058_the_most_glorious_thing_that_sounds_a_bit_like_greg_davies_if_you_mumble_it.jpg', '03058_the_most_glorious_thing_that_sounds_a_bit_like_greg_davies_if_you_mumble_it_thumb.jpg'),
(808, '|2288|', 4, '|11|', 1, 'Find the item that makes a sound', 'In this task, the contestants must locate the object that makes a sound when a button is pressed, and deliver it to the Taskmaster\'s assistant.', '02288_find_the_item_that_makes_the_sound.jpg', '02288_find_the_item_that_makes_the_sound_thumb.jpg'),
(809, '|2466|', 4, '|11|', 1, 'Write the longest sentence with these tiles', 'In this task, the contestants are presented with a collection of square tiles with letters on them, and are instructed to create the longest sentence out of them as possible.|The tiles may or may not have been chosen to provide the exact letters required to spell out a specific sentence.', '02466_write_the_longest_sentence_with_these_tiles.jpg', '02466_write_the_longest_sentence_with_these_tiles_thumb.jpg'),
(810, '|1227|', 8, '|11|', 1, 'Time-travel', 'In this task, the contestants are instructed to time-travel.', '01227_time_travel.jpg', '01227_time_travel_thumb.jpg'),
(811, '|120|', 1, '|11|', 1, 'Don the diving gear while maintaining eye contact and making small talk', 'In this task, the contestants must don some diving gear while maintaining eye contact and making small talk with a foreigner on a video call.', '00120_don_the_diving_gear_while_maintaining_small_talk.jpg', '00120_don_the_diving_gear_while_maintaining_small_talk_thumb.jpg'),
(812, '|3252|', 1, '|11|', 1, 'The thing that gives you the most hope for the future of humanity', 'In this prize task, the contestants must bring in the thing that gives them the most hope for the future of humanity.', '03252_the_thing_that_gives_the_most_hope_for_the_future_of_the_human_race.jpg', '03252_the_thing_that_gives_the_most_hope_for_the_future_of_the_human_race_thumb.jpg'),
(813, '|2657|', 8, '|6|11|', 2, 'Do the most unpredictable thing', 'In this task, the contestants are instructed to do the most unpredictable thing at the end of a 500 second countdown.', '02657_do_the_most_unpredictable_thing.jpg', '02657_do_the_most_unpredictable_thing_thumb.jpg'),
(814, '|1279|', 1, '|11|', 1, 'Scale the mountain', 'In this team task, the contestants must perform the scaling of a mountain, which takes the form of a large triangular tarpaulin or canvas laid out on the ground.|The contestants must perform their climb knowing that the footage will be played back at a greater speed.|The most thrilling ascent wins.', '01279_scale_the_mountain.jpg', '01279_scale_the_mountain_thumb.jpg'),
(815, '|503|', 8, '|11|', 1, 'Hide a vegetable completely inside another', 'In this task, the contestants are presented with a range of vegetables, and instructed to completely hide one of them inside another one.|Any contestants who use the same combination of vegetables are disqualified.|Scoring is based on the best combination of vegetables and/or how quickly they complete the task.', '00503_hide_a_vegetable_completely_inside_another.jpg', '00503_hide_a_vegetable_completely_inside_another_thumb.jpg'),
(816, '|3166|', 1, '|11|', 1, 'Be the most impressive load-bearer', 'In this task, the contestants must be the most impress load-bearer while standing in a specific spot, waving one hand, and doing a thumbs-up with the other hand.|The load they are bearing may only touch their body.', '03166_be_the_most_impressive_load_bearer.jpg', '03166_be_the_most_impressive_load_bearer_thumb.jpg'),
(817, '|3254|', 1, '|11|', 1, 'Hug your special friend', 'In this task, the contestants must find and hug their \'special friend\', which takes the form of a mannequin (which they may or may not have customised during a previous task).|Clues to the location of the mannequin are provided via a grid of cards featuring letters, many of which have additional clues and tools hidden beneath them, to send them in the correct direction and distance.|The contestants who hugs their \'special friend\' the fastest wins.', '03254_hug_your_special_friend.jpg', '03254_hug_your_special_friend_thumb.jpg'),
(818, '|1012|', 1, '|14|', 1, 'Skim something', 'In this task, the contestants must skim something (e.g. a biscuit or stone) across a body of water, with the winner being the one whose item skims across the surface the most times.|The contestants may have one or multiple attempts, depending on the situation.', NULL, NULL),
(819, '|2169|', 13, '|11|', 1, 'The strangest item you own', 'In this prize task, the contestants must bring in the strangest thing they own.', '02169_the_strangest_item_you_own.jpg', '02169_the_strangest_item_you_own_thumb.jpg'),
(820, '|1909|', 1, '|11|', 1, 'Enable the Taskmaster\'s assistant to bite his duck', 'In this task, the contestants must enable the Taskmaster\'s assistant to bite a duck which is in a bucket on their lap.|The assistant is tied to a chair, and the contestants may not step foot on the platform on which they are sat.|A bonus point is available to the contestant who gets the assistant the least wet during the process.', '01909_enable_alex_to_bite_his_duck.jpg', '01909_enable_alex_to_bite_his_duck_thumb.jpg'),
(821, '|2057|', 8, '|11|', 1, 'The best thing for all five of the senses', 'In this prize task, the contestants must bring in the best thing that delights all five of the senses.', '02057_the_best_thing_that_delights_all_five_of_the_senses.jpg', '02057_the_best_thing_that_delights_all_five_of_the_senses_thumb.jpg'),
(822, '|2968|', 4, '|6|9|11|', 3, 'Call someone and get them to say a word of your choice', 'In this task, the contestants are first instructed to write down a word that they like.|They are then told to call someone and get that person to say the chosen word as many times as possible, without saying the word themselves, or giving away the fact that they are completing a task.', '02968_call_someone_and_get_them_to_say_a_word_of_your_choice.jpg', '02968_call_someone_and_get_them_to_say_a_word_of_your_choice_thumb.jpg'),
(823, '|3105|', 1, '|11|', 1, 'Stick the heaviest thing to the board', 'In this task, the contestants must attempt to stick the heaviest thing to a whiteboard using three of the items or substances provided for the purposes.', '03105_stick_the_heaviest_thing_to_the_board.jpg', '03105_stick_the_heaviest_thing_to_the_board_thumb.jpg'),
(824, '|952|', 1, '|11|', 1, 'The most satisfying wobbly thing', 'In this prize task, the contestants are instructed to bring in the most satisfying wobbly thing.', '00952_the_most_satisfying_wobbly_thing.jpg', '00952_the_most_satisfying_wobbly_thing_thumb.jpg'),
(825, '|2732|', 4, '|9|', 1, 'Draw the most red cards from the deck', 'In this task, the contestants must attempt to draw the most consecutive red cards from a deck.|The deck of cards is not a standard deck, consisting either entirely, or almost entirely, of red-suited cards, making the task a game of holding one\'s nerve as long as possible, rather than one of luck.', '02732_draw_the_most_red_cards_from_the_deck.jpg', '02732_draw_the_most_red_cards_from_the_deck_thumb.jpg'),
(826, '|3405|', 14, '|1|', 1, 'Create an authentic family home video', 'In this team task, the contestants must film an authentic family home video.', '03405_create_an_authentic_family_home_video.jpg', '03405_create_an_authentic_family_home_video_thumb.jpg'),
(827, '|3240|', 13, '|9|', 1, 'Gift-wrap yourself', 'In this task, the contestants are instructed to gift-wrap themselves in preparation for the Taskmaster\'s assistant\'s arrival.|The contestant who presents themselves in the best or most surprising way wins.', '03240_present_yourself_as_a_gift.jpg', '03240_present_yourself_as_a_gift_thumb.jpg'),
(828, '|2495|', 1, '|9|', 1, 'Create a picture of an animal on the back of your T-shirt', 'In this live studio task, the contestants must create a recognisable image of an animal of their choice on the back of a plain T-shirt they are wearing, using the provided craft supplies.|Choosing a unique animal is encouraged either through the threat of disqualification for not doing so, or through the promise of a bonus point for doing so.', '02495_create_a_picture_of_an_animal_on_the_back_of_your_t_shirt.jpg', '02495_create_a_picture_of_an_animal_on_the_back_of_your_t_shirt_thumb.jpg'),
(829, '|3131|', 1, '|11|', 1, 'Complete the jobstacle course', 'In this task, the contestants must complete a series of chores while carrying a bucket of water in a baby carrier.|The winner is the person who spills the least of their \'baby\'.', '03131_complete_the_jobstacle_course.jpg', '03131_complete_the_jobstacle_course_thumb.jpg'),
(830, '|2151|', 4, '|11|', 1, 'Remove all the balls from the bin', 'In this task, the contestants are instructed to remove all of the balls from a large bin as quickly as possible.|In some versions, they are then instructed to replace all of the balls they have removed.', '02151_remove_all_the_balls_from_the_bin.jpg', '02151_remove_all_the_balls_from_the_bin_thumb.jpg'),
(831, '|3129|', 1, '|11|', 1, 'The best thing for a person that is meant for an animal', 'In this prize task, the contestants must bring in the best thing for a person that is actually meant for an animal.', '03129_the_best_thing_for_a_person_that_is_meant_for_an_animal.jpg', '03129_the_best_thing_for_a_person_that_is_meant_for_an_animal_thumb.jpg'),
(832, '|2347|', 1, '|6|11|', 2, 'Count all the dots', 'In this task, the contestants must attempt to count all of the dots on a card while being regularly interrupted by the delivery of additional instructions.|Each time the contestant responds to a doorbell ring to collect their latest instructions, the taskmaster\'s assistant turns over the card, which has dots on both sides (black on white on one side, and white on black on the other).', '02347_count_all_the_dots.jpg', '02347_count_all_the_dots_thumb.jpg'),
(833, '|2143|', 1, '|9|', 1, 'The most jaw-dropping item', 'In this prize task, the contestants must bring in the most jaw-dropping item.', '02143_the_most_jaw_dropping_item.jpg', '02143_the_most_jaw_dropping_item_thumb.jpg'),
(834, '|2748|', 4, '|9|', 1, 'List your wishes, then make them come true', 'In this task, the contestants are first instructed to list all the wishes that they would like granted.|They are then instructed to make as many of their own wishes come true as possible.', '02748_list_your_wishes_then_make_them_come_true.jpg', '02748_list_your_wishes_then_make_them_come_true_thumb.jpg'),
(835, '|2667|', 8, '|6|', 1, 'Follow the scattered audio instructions', 'In this task, the contestants must work out what the objective of the task is by piecing together fragments of the task brief which are split across multiple audio cassette tapes.|Each cassette tape usually has a picture of a different type of fish on the cover, and may contain an audio clue pointing them to the next tape they should listen to, by referring to the type of fish on the cover.|A fish poster featuring all of the species on the tapes is usually provided somewhere within the grounds of the house, as a reference.|A full version of the task brief is usually also provided on a CD.|Some of the other cassette tapes usually feature audio from previous contestants\' musical task attempts, as Easter eggs.|The actual task to be solved is usually something very simple, such as snapping a pencil, or drawing a fish.', '02667_snap_the_pencil.jpg', '02667_snap_the_pencil_thumb.jpg'),
(836, NULL, 6, '|6|9|', 2, 'Create as many new identities as possible', 'In this task, the contestants must greet the Taskmaster\'s assistant with a new name and occupation each time a sound is made (e.g. when the assistant rings a bell, or whenever a beep is heard).', '02617_sort_the_coloured_sweets_and_greet_mark_as_different_professions.jpg', '02617_sort_the_coloured_sweets_and_greet_mark_as_different_professions_thumb.jpg'),
(837, '|2073|', 9, '|9|', 1, 'Make someone look like the Taskmaster’s assistant', 'In this task, the contestants must make either themselves or someone else resemble the Taskmaster\'s assistant.|Both pre-filmed and live versions of the task have been used.', '02073_make_yourself_a_pilvi.jpg', '02073_make_yourself_a_pilvi_thumb.jpg'),
(838, '|388|', 1, '|1|', 1, 'Choose your own adventure', 'In this task, the contestants are given a series of choices while they attempt to discover and the complete the actual objective.|Each choice send them to a different location, where they must complete a mini-task before moving on.|The task is set up and maintained in such a way that it\'s possible to visit the same location multiple times, and even to get stuck in a loop of actions.', '00388_say_the_word_demeaning.jpg', '00388_say_the_word_demeaning_thumb.jpg'),
(839, '|3638|', 1, '|6|', 1, 'Say the same word at the same time', 'In this team-based live studio task, the contestants are given a category, and then two members of each team must attempt to say the same word belonging to that category at the same time.|The team whose members are most in-sync during the game wins.', '03638_say_the_same_word_at_the_same_time.jpg', '03638_say_the_same_word_at_the_same_time_thumb.jpg'),
(840, '|362|', 1, '|9|', 1, 'Do something powerful with your little finger', 'In this task, the contestants are instructed to do something powerful with their little finger.', '00362_do_something_powerful_with_your_little_finger.jpg', '00362_do_something_powerful_with_your_little_finger_thumb.jpg'),
(841, '|2956|', 4, '|9|', 1, 'Put a thing inside a box, or a box inside a thing', 'In this task, the contestants are presented with a choice between two task briefs, which are labelled \'Easy\' and \'Difficult\'.|The \'Easy\' task brief instructs them to place an object (e.g. a biscuit or sock) inside a box, while the \'Difficult\' one instructs them to place the box inside the object.', '02956_put_the_biscuit_in_the_box_or_the_box_in_the_biscuit.jpg', '02956_put_the_biscuit_in_the_box_or_the_box_in_the_biscuit_thumb.jpg'),
(842, '|2362|', 4, '|9|', 1, 'Transport something you can lift as far as possible', 'In this task, the contestants are first instructed to find something they can lift.|They are then instructed to transport that thing as far as possible in a limited amount of time.', '02362_transport_something_you_can_lift_as_far_as_possible.jpg', '02362_transport_something_you_can_lift_as_far_as_possible_thumb.jpg'),
(843, '|2494|', 1, '|9|', 1, 'Achieve an impressive action with a single breath', 'In this task, the contestants are instructed to achieve an impressive action with a single breath.', '02494_achieve_an_impressive_effect_with_a_single_breath.jpg', '02494_achieve_an_impressive_effect_with_a_single_breath_thumb.jpg'),
(844, '|2516|', 3, '|3|6|', 2, 'Save the child', 'In this task, the contestants are instructed to rescue a child (represented by a doll) from a dangerous situation in the best way.|The contestants may be disqualified for allowing the child to be damaged or destroyed.', '02516_become_a_superhero_and_save_the_child.jpg', '02516_become_a_superhero_and_save_the_child_thumb.jpg'),
(845, '|3459|', 8, '|6|', 1, 'Move forward when you hear your note', 'In this live studio task, the contestants must listen out for their assigned note, and take a step forward each time they hear it.|If they step forward when someone else\'s note is played, they must take two steps backwards.|The winner is the person who has taken the most steps forward, once everyone\'s notes have been played several times.', '03459_move_forward_when_you_hear_your_note.jpg', '03459_move_forward_when_you_hear_your_note_thumb.jpg'),
(846, '|2586|', 1, '|9|', 1, 'Put the most stuff on top of a jelly', 'In this task, the contestants are instructed to place as much weight as possible on a jelly without breaking it.|If anything other than jelly touches a rubber duck which has been suspended inside the jelly, they are disqualified.', '02586_put_the_most_stuff_on_top_of_a_jelly.jpg', '02586_put_the_most_stuff_on_top_of_a_jelly_thumb.jpg'),
(847, '|2725|', 1, '|6|', 1, 'Pull the sword from the stone', 'In this task, the contestants must work out the password needed to release a sword from a stone.|The password is usually the name of a former champion of the show, a variety of clues to which are provided around the area in which the task takes place.', '02725_pull_the_sword_from_the_stone.jpg', '02725_pull_the_sword_from_the_stone_thumb.jpg'),
(848, '|846|', 1, '|11|', 1, 'The most annoying thing', 'In this prize task, the contestants must bring in the most annoying thing.', '00846_the_most_annoying_thing.jpg', '00846_the_most_annoying_thing_thumb.jpg'),
(849, '|3246|', 3, '|6|', 1, 'Try to break a world record', 'In this task, the contestants are instructed to attempt to break a world record.', '03246_try_to_break_a_world_record.jpg', '03246_try_to_break_a_world_record_thumb.jpg'),
(850, '|708|', 6, '|6|', 1, 'Have an argument with yourself', 'In this task, the contestants are instructed to have an argument with themselves.', '00708_have_a_quarrel_with_yourself.jpg', '00708_have_a_quarrel_with_yourself_thumb.jpg'),
(851, '|3010|', 4, '|6|', 1, 'Perform a split-screen scene with yourself', 'In this task, the contestants are instructed to perform a split-screen scene with themselves, filming each part of the scene on either side of a line taped across the middle of the room.', '03010_perform_a_moving_scene_with_yourself.jpg', '03010_perform_a_moving_scene_with_yourself_thumb.jpg'),
(852, '|2561|', 1, '|6|', 1, 'Bash the big bell with the bowling ball', 'In this task, the contestants must attempt to ring a large bell with a bowling ball.|The bell is set up a distance away from them across some grass, and the contestants are prohibited from stepping on the grass unless they are wearing golden shoes.|The Taskmaster\'s assistant is wearing such a pair of shoes, but will only give them to the contestant in exchange for cash, a soft-boiled egg, or if they physically remove them.|An alternate pair of golden shoes is usually also provided somewhere in plain view on the property.|Spray paints are usually also provided, which the contestants may use to paint some shoes themselves, but the caps of the paints have usually been swapped to trick them into using the wrong colour.', '02561_bash_the_big_bell_with_the_bowling_ball.jpg', '02561_bash_the_big_bell_with_the_bowling_ball_thumb.jpg'),
(853, '|517|', 8, '|11|', 1, 'The worst thing to show the Taskmaster', 'In this prize task, the contestants must bring in the worst thing to show the Taskmaster.', '00517_the_worst_thing_to_show_the_taskmaster.jpg', '00517_the_worst_thing_to_show_the_taskmaster_thumb.jpg'),
(854, '|4324|', 10, '|1|', 1, 'Write two lines for a collaborative poem or song', 'In this task, the contestants are each instructed to contribute two lines to a collaborative poem or song.|The contestants are provided only with the lines immediately prior to their own, so they can build on or rhyme with them (if they choose).', '01028_write_two_lines_for_a_poem_about_the_taskmaster.jpg', '01028_write_two_lines_for_a_poem_about_the_taskmaster_thumb.jpg'),
(855, '|4325|', 10, '|10|', 1, 'Make a travel activity recommendation', 'In this homework task, the contestants must recommend an activity for the Taskmaster to partake in while they are visiting a specific city.', NULL, NULL),
(856, '|4326|', 10, '|1|', 1, 'Find the Taskmaster or Taskmaster\'s assistant', 'In this task, the contestants must try to be the quickest to find the Taskmaster or their assistant.', '00006_find_alex.jpg', '00006_find_alex_thumb.jpg'),
(857, '|2363|', 4, '|6|', 1, 'Find the bell pepper', 'In this task, the contestants are presented with a variety of chilli peppers and must try to find a bell pepper.|The bell pepper is usually presented in plain sight in the room, but behind where the contestants are standing, and above eye level.', '02363_find_the_bell_pepper.jpg', '02363_find_the_bell_pepper_thumb.jpg'),
(858, '|3660|', 1, '|6|', 1, 'Float or sink?', 'In this live studio task, the contestants are presented with a series of objects and must guess whether each of them will float or sink in water.', '03660_will_it_float_or_not_float.jpg', '03660_will_it_float_or_not_float_thumb.jpg'),
(859, '|2488|', 4, '|6|', 1, 'Count macaroni into a container', 'In this task, the contestants must attempt to accurately count pieces of macaroni into a vessel.|They begin with a very short time limit, but this limit gets reset each time they correctly set themselves and solve a new multiplication calculation (thus likely causing them to forget the number they have counted to so far).|The contestant who most accurately counts the pieces of macaroni they\'ve placed in the vessel wins.', '02488_count_macaroni_into_the_blue_cup.jpg', '02488_count_macaroni_into_the_blue_cup_thumb.jpg'),
(860, '|2736|', 1, '|6|', 1, 'Get the ball in the hole without touching it', 'In this task, the contestants must aim to get a ball into a golf hole as quickly as possible.|The contestants may only move the ball using air, and are provided with a range of items with which they may do this, such as bellows, wind instruments, and usually a leaf-blower attached to a wellington boot (which they must wear on their foot while in use).|Each time the contestants want to switch between items, they must pay a time penalty, either in the form of waiting for a given period, or performing an action (such as snapping their fingers) a certain number of times.|The task is further complicated by the presence of decoy golf holes consisting of pieces of black fabric pinned to the ground, which they will likely not spot until they are close to them. The actual hole they are aiming for is also concealed by the Taskmaster\'s assistant at the start of the task, by them standing in front of it, with the flag concealed in their trouser leg.', '02736_get_the_ball_in_the_hole_without_touching_it.jpg', '02736_get_the_ball_in_the_hole_without_touching_it_thumb.jpg'),
(861, '|2064|', 8, '|6|', 1, 'Build a big flag', 'In this task, the contestants must build a large version of a country\'s flag, after drawing a card from a deck.|Each card features the name of the country whose flag they must replicate, but the image of a completely different country (usually one which has a somewhat similar flag) to mislead them.', '02064_build_a_big_flag.jpg', '02064_build_a_big_flag_thumb.jpg'),
(862, '|2130|', 4, '|8|', 1, 'Perform a party trick', 'In this task, the contestants must demonstrate a party trick. The most impressive party trick wins.', '02130_show_off_your_best_party_trick.jpg', '02130_show_off_your_best_party_trick_thumb.jpg'),
(863, '|3975|', 3, '|1|', 1, 'Eat the chocolate item (or don’t)', 'In this task, each contestant is provided with a chocolate item (e.g. a chocolate bunny or duck), and is instructed to either eat it or not.|The outcome of the task depends on how many of the contestants choose to eat the item versus not eat it.|When assigned as a filmed task, the game is about predicting what the other contestants might do.|When assigned as a live task, additional elements of strategy and deception come into play.', '03975_eat_the_chocolate_bunny_or_dont.jpg', '03975_eat_the_chocolate_bunny_or_dont_thumb.jpg'),
(864, '|1595|', 4, '|4|', 1, 'Something that is too small', 'In this prize task, the contestants are instructed to bring in something that is too small, or which should be bigger.', '01595_something_that_is_too_small.jpg', '01595_something_that_is_too_small_thumb.jpg'),
(865, '|2450|', 14, '|1|', 1, 'Paint something from a balcony', 'In this task, the contestants are instructed to paint something specific on a canvas or piece of paper which is laid on the ground, while remaining on a balcony above.', '02450_paint_an_accurate_map_of_australia.jpg', '02450_paint_an_accurate_map_of_australia_thumb.jpg');
