--
-- Table structure for table `master_tasks`
--

CREATE TABLE `master_tasks` (
  `id` smallint(3) UNSIGNED NOT NULL COMMENT 'Unique identifier',
  `original_task_ids` varchar(18) COLLATE utf8_unicode_ci DEFAULT NULL COMMENT 'Pipe-separated list of original task IDs.',
  `originating_show_id` tinyint(2) UNSIGNED DEFAULT NULL COMMENT 'ID of originating show',
  `adapting_show_ids` varchar(40) COLLATE utf8_unicode_ci DEFAULT NULL COMMENT 'Pipe-separated list of shows which have adapted this task.',
  `adaptations` tinyint(3) UNSIGNED DEFAULT NULL COMMENT 'Number of adaptations',
  `title` varchar(256) COLLATE utf8_unicode_ci DEFAULT NULL COMMENT 'Task title',
  `description` varchar(1024) COLLATE utf8_unicode_ci DEFAULT NULL COMMENT 'Task description (separate paragraphs with pipes)',
  `cover_image` varchar(256) COLLATE utf8_unicode_ci DEFAULT NULL COMMENT 'Cover image filename',
  `cover_image_thumb` varchar(256) COLLATE utf8_unicode_ci DEFAULT NULL COMMENT 'Cover image thumbnail filename'
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;

